/* ── TAP THE BROKEN CLAIM ──
   Instead of describing the issue in prose, tap the exact sentence that
   is wrong. The report arrives pre-scoped to the claim with its citations
   attached. The textarea shrinks to "What should it say instead?" */
function ReportModal({ query, P, accent, at, onClose, answer = "", sources = [] }) {
  const [description, setDescription] = useState("");
  const [category, setCategory] = useState("wrong-citation");
  const [selectedClaim, setSelectedClaim] = useState(null);
  const [selecting, setSelecting] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [error, setError] = useState("");

  const paras = useMemo(() => {
    if (!answer) return [];
    return answer.split(/\n{2,}/)
      .map((p) => p.replace(/^#{1,6}\s+/, "").replace(/\*\*/g, "").trim())
      .filter((p) => p.length > 40 && !/^(the short answer|what the research|where researchers|how solid)/i.test(p))
      .slice(0, 12);
  }, [answer]);

  const claimCites = (para) => {
    const nums = [];
    const re = /\[(\d+)\]/g;
    let m;
    while ((m = re.exec(para)) && nums.length < 8) {
      const n = parseInt(m[1], 10);
      if (n > 0 && n <= sources.length && !nums.includes(n)) nums.push(n);
    }
    return nums;
  };

  const submit = async (e) => {
    e.preventDefault();
    if (!description.trim() && !selectedClaim) return;
    setSubmitting(true);
    setError("");
    try {
      const payload = {
        query,
        description: description.trim() || "(no description, claim tapped)",
        category,
      };
      if (selectedClaim !== null && paras[selectedClaim]) {
        payload.claim = paras[selectedClaim].slice(0, 500);
        payload.claimCitations = claimCites(paras[selectedClaim]);
      }
      const res = await fetch("/api/report", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });
      // 2026-09-14: Check res.ok. A failed/offline/500 request must not show
      // the green "Report received" confirmation — the report was lost.
      if (!res.ok) throw new Error("submit failed");
      setSubmitted(true);
      setTimeout(() => onClose(), 1800);
    } catch {
      setSubmitting(false);
      setError("Couldn't send your report. Check your connection and try again.");
    }
  };

  const categories = [
    { id: "wrong-citation", label: "Wrong citation" },
    { id: "misquoted", label: "Misquoted" },
    { id: "outdated", label: "Outdated" },
    { id: "missing-context", label: "Missing context" },
    { id: "hallucination", label: "Hallucinated claim" },
    { id: "broken-source", label: "Broken source link" },
    { id: "other", label: "Other" },
  ];

  return (
    <Dialog label="Report data issue" onClose={onClose} zIndex={220} width={440}
      panelStyle={{
        background: P.dark ? "#0f111a" : "#ffffff",
        border: `1px solid ${P.line}`,
        borderRadius: RADIUS.md, padding: "28px", outline: "none", fontFamily: "var(--cb-font)",
        boxShadow: "none",
      }}
    >
        {submitted ? (
          <div style={{ textAlign: "center", padding: "24px 0" }}>
            <div style={{ width: 44, height: 44, borderRadius: "50%", background: withAlpha(STATUS.good, 0.12), color: statusGood(P), display: "flex", alignItems: "center", justifyContent: "center", margin: "0 auto 14px" }}>
              <Icon name="check" size={20} />
            </div>
            <div style={{ fontSize: FONT_SIZES.body, fontWeight: 500, color: P.ink }}>Report received</div>
            <div style={{ fontSize: FONT_SIZES.small, color: P.ink2, marginTop: 6 }}>Thank you for improving data quality.</div>
          </div>
        ) : (
          <form onSubmit={submit}>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 20 }}>
              <div style={{ fontSize: FONT_SIZES.heading, fontWeight: 500, letterSpacing: TYPE.heading.letterSpacing, color: P.ink, fontFamily: "var(--cb-font)" }}>Report data issue</div>
              <button type="button" onClick={onClose} aria-label="Close" style={{ background: "none", border: "none", color: P.faint, cursor: "pointer", padding: 13, display: "inline-flex" }}><Icon name="close" size={18} /></button>
            </div>
            <div style={{ marginBottom: 16 }}>
              <div style={{ fontSize: FONT_SIZES.small, fontWeight: 500, color: P.ink2, marginBottom: 8 }}>Category</div>
              <div style={{ alignItems: "center", display: "flex", flexWrap: "wrap", gap: 6 }}>
                {categories.map((c) => (
                  <UIButton P={P} variant="ghost" key={c.id} type="button" onClick={() => setCategory(c.id)} style={{ minHeight: 44,
                    fontSize: FONT_SIZES.caption, padding: "6px 12px", borderRadius: RADIUS.md, cursor: "pointer",
                    fontFamily: "var(--cb-font)", fontWeight: 500, transition: "background-color 150ms ease, color 150ms ease, border-color 150ms ease",
                    background: category === c.id ? withAlpha(accent, 0.16) : "transparent",
                    color: category === c.id ? accent : P.ink2,
                    border: `1px solid ${category === c.id ? withAlpha(accent, 0.3) : P.line}`,
                  }}>{c.label}</UIButton>
                ))}
              </div>
            </div>
            {paras.length > 0 && (
              <div style={{ marginBottom: 16 }}>
                <div style={{ fontSize: FONT_SIZES.small, fontWeight: 500, color: P.ink2, marginBottom: 8 }}>
                  {selectedClaim !== null ? "Selected claim" : "Tap the claim that is wrong"}
                </div>
                {selectedClaim !== null ? (
                  <div style={{
                    padding: "12px 14px", borderRadius: RADIUS.md,
                    border: `1px solid ${withAlpha(accent, 0.4)}`,
                    background: withAlpha(accent, 0.07),
                    fontSize: FONT_SIZES.small, color: P.ink, lineHeight: 1.6,
                    fontFamily: "var(--cb-font)",
                  }}>
                    <div style={{ marginBottom: 6 }}>"{paras[selectedClaim].slice(0, 220)}{paras[selectedClaim].length > 220 ? "…" : ""}"</div>
                    {claimCites(paras[selectedClaim]).length > 0 && (
                      <div style={{ fontSize: FONT_SIZES.caption, color: P.faint, fontFamily: "var(--cb-mono)" }}>
                        Cites [{claimCites(paras[selectedClaim]).join("] [")}]
                      </div>
                    )}
                    <button type="button" onClick={() => setSelectedClaim(null)}
                      style={{ marginTop: 8, background: "none", border: "none", color: accent, cursor: "pointer", fontSize: FONT_SIZES.caption, fontWeight: 500, padding: 0, fontFamily: "var(--cb-font)" }}>
                      Choose a different claim
                    </button>
                  </div>
                ) : (
                  <div style={{ display: "flex", flexDirection: "column", gap: 6, maxHeight: 220, overflowY: "auto" }}>
                    {paras.map((p, i) => (
                      <button key={i} type="button" onClick={() => { setSelectedClaim(i); setSelecting(false); }}
                        style={{
                          textAlign: "left", padding: "10px 12px", borderRadius: RADIUS.md,
                          border: `1px solid ${P.line}`, background: "transparent",
                          fontSize: FONT_SIZES.small, color: P.ink2, lineHeight: 1.55,
                          cursor: "pointer", fontFamily: "var(--cb-font)",
                          minHeight: 44,
                        }}
                        onMouseEnter={(e) => { e.currentTarget.style.borderColor = withAlpha(accent, 0.5); }}
                        onMouseLeave={(e) => { e.currentTarget.style.borderColor = P.line; }}>
                        {p.slice(0, 140)}{p.length > 140 ? "…" : ""}
                      </button>
                    ))}
                  </div>
                )}
              </div>
            )}
            <div style={{ marginBottom: 18 }}>
              <div style={{ fontSize: FONT_SIZES.small, fontWeight: 500, color: P.ink2, marginBottom: 6 }}>What should it say instead?</div>
              <textarea value={description} onChange={(e) => setDescription(e.target.value)} rows={3} placeholder="The correct information, if you know it. Optional when you have tapped the claim above." style={{
                width: "100%", padding: "11px 13px", fontSize: 16, borderRadius: RADIUS.md,
                border: `1px solid ${P.line}`, background: P.surface,
                color: P.ink, fontFamily: "var(--cb-font)", resize: "vertical", outline: "none",
              }} />
            </div>
            <button type="submit" disabled={submitting || (!description.trim() && selectedClaim === null)} style={{
              width: "100%", padding: "12px", fontSize: FONT_SIZES.body, fontWeight: 500,
              background: accent, color: at, border: "none", borderRadius: RADIUS.md,
              cursor: submitting || (!description.trim() && selectedClaim === null) ? "default" : "pointer",
              opacity: submitting || (!description.trim() && selectedClaim === null) ? 0.6 : 1,
              fontFamily: "var(--cb-font)",
            }}>{submitting ? "Sending…" : "Submit report"}</button>
            {error && (
              <div role="alert" style={{ marginTop: 12, padding: "12px 12px", borderRadius: RADIUS.md, fontSize: FONT_SIZES.small, color: "#ff6b6b", background: "rgba(255,107,107,0.1)", border: "1px solid rgba(255,107,107,0.3)" }}>
                {error}
              </div>
            )}
          </form>
        )}
    </Dialog>
  );
}

/* The answer's own blocks, in the answer's own order, for the print
   layout below (2026-10-19, S2 / H14). This used to carve the answer
   up by hand (first paragraph relabeled Abstract, last relabeled
   Conclusion) and the print JSX supplied a fabricated Introduction
   paragraph around them. None of that survives: print shows the
   answer as written, its own headings as headings and its paragraphs
   in order, and the only added furniture is the masthead, the
   question as title, and the References list, which is real data. */
function buildAcademicPaperBlocks(answer) {
  const clean = normalizeSectionHeaders(answer || "").trim();
  const chunks = clean.split(/\n{2,}/).map((c) => c.trim()).filter(Boolean);
  const blocks = chunks.map((c) => {
    const h = c.match(/^#{2,3}\s+(.+)$/);
    if (h) return { type: "heading", text: h[1] };
    return { type: "para", text: c.replace(/^[•\-]\s+/gm, "").replace(/^\d+\.\s+/gm, "") };
  });
  return { blocks };
}

/* ═══════════════════════════════════════════════════════════════════════
   Commit 84 — DISAGREEMENT AS A VIEW.

   "Where researchers disagree" has always been a paragraph. A paragraph
   about disagreement is a chatbot answer: you have to read it, hold both
   sides in your head, and go dig out the study sizes yourself.

   A researcher reading a contested literature wants to see the shape of
   the fight — who says what, how big their study was, and how recent.
   That is a table, not prose, and building it is an operation a chatbot
   does not perform.

   This reads the section the model already produces, pulls the citation
   markers out of each sentence, and lines the cited papers up against the
   claims they were cited for. It invents nothing: every row is a sentence
   the model wrote and a paper it pointed at. If a section has no
   citations to hang on, the panel does not render and the prose stands
   on its own — a half-empty table is worse than a paragraph.
   ═══════════════════════════════════════════════════════════════════════ */
function extractDisagreement(answer, sources) {
  if (!answer || !Array.isArray(sources) || sources.length < 2) return null;
  // The heading text is fixed by the STRUCTURE contract in search.js.
  /* Commit 93 — the section boundary needed the same fix the renderer got
     in Commit 85. The lookahead required a NEWLINE before the next "##",
     but models routinely glue the following heading onto the end of the
     last sentence. When that happened this captured the next heading as
     part of the disagreement body, and a card in the panel ended with a
     literal "## How solid is this?" hanging off it — which is exactly what
     showed up in a real answer. Tolerate the glued form. */
  const m = answer.match(/##\s*(?:Where researchers disagree|Where they actually differ)\s*\n?([\s\S]*?)(?=\s*#{1,6}\s+\w|$)/i);
  if (!m) return null;
  const body = stripStrayHashes(m[1]).trim();
  if (body.length < 60) return null;

  const claims = [];
  for (const raw of body.split(/(?<=[.!?])\s+(?=[A-Z])/)) {
    // Belt and braces: a marker surviving into an individual sentence
    // would render inside a card, where there is no second chance to
    // catch it.
    const sentence = stripStrayHashes(raw).trim();
    if (sentence.length < 40) continue;
    const refs = [...sentence.matchAll(/\[(\d{1,2})\]/g)].map((x) => parseInt(x[1], 10));
    if (!refs.length) continue;
    const cited = refs
      .map((n) => sources[n - 1])
      .filter(Boolean)
      .map((src, k) => ({
        n: refs[k],
        title: src.title || "Untitled",
        year: src.year || "",
        journal: src.journal || "",
        // Sample size is only shown when the abstract actually states one.
        // Guessing at n is worse than omitting it.
        n_size: (() => {
          const t = `${src.abstract || ""}`;
          const mm = t.match(/\b(?:n\s*=\s*|sample of\s+|total of\s+)(\d{2,6})\b/i);
          return mm ? parseInt(mm[1], 10) : null;
        })(),
      }));
    if (cited.length) claims.push({ text: sentence.replace(/\[\d{1,2}\]/g, "").replace(/\s+([.,;])/g, "$1").trim(), cited });
  }
  return claims.length >= 2 ? claims : null;
}

function DisagreementPanel({ answer, sources, P, accent, isMobile }) {
  const claims = useMemo(() => extractDisagreement(answer, sources), [answer, sources]);
  const [open, setOpen] = useState(true);
  if (!claims) return null;
  return (
    <UICard P={P} style={{ marginTop: SP.xl }}>
      <UILabel P={P} accent={accent} right={
        <button onClick={() => setOpen((v) => !v)} style={{
          background: "none", border: "none", color: P.faint, cursor: "pointer",
          fontSize: FONT_SIZES.micro, fontFamily: "var(--cb-font)", fontWeight: 500, padding: 0,
        }}>{open ? "Hide" : "Show"}</button>
      }>The disagreement, laid out</UILabel>
      {open && (
        <div style={{ display: "flex", flexDirection: "column", gap: SP.md }}>
          {claims.map((c, i) => (
            <div key={i} style={{
              display: "flex", flexDirection: isMobile ? "column" : "row",
              gap: isMobile ? SP.sm : SP.lg, alignItems: "flex-start",
              paddingTop: i ? SP.md : 0,
              borderTop: i ? `1px solid ${P.line}` : "none",
            }}>
              <div style={{ flex: 1, minWidth: 0, fontSize: FONT_SIZES.small, color: P.ink, lineHeight: 1.55 }}>
                {renderInlineMdLite(c.text, P)}
              </div>
              <div style={{ flexShrink: 0, width: isMobile ? "100%" : 210, display: "flex", flexDirection: "column", gap: 5 }}>
                {c.cited.map((s2, k) => (
                  <div key={k} style={{
                    fontSize: FONT_SIZES.micro, color: P.faint, fontFamily: "var(--cb-font)",
                    display: "flex", alignItems: "center", gap: 6, flexWrap: "wrap",
                  }}>
                    <span style={{
                      padding: "1px 6px", borderRadius: RADIUS.pill,
                      background: withAlpha(accent, 0.14), color: accent, fontWeight: 500,
                    }}>{s2.n}</span>
                    {s2.year && <span>{s2.year}</span>}
                    {s2.n_size && <span style={{ color: P.ink2 }}>n={s2.n_size.toLocaleString()}</span>}
                    {s2.journal && (
                      <span style={{ maxWidth: 120, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{formatJournalName(s2.journal)}</span>
                    )}
                  </div>
                ))}
              </div>
            </div>
          ))}
          <div style={{ fontSize: FONT_SIZES.micro, color: P.faint, marginTop: 2 }}>
            Sample sizes shown only where the abstract states one.
          </div>
        </div>
      )}
    </UICard>
  );
}

/* ════════════════════════════════════════════════════════════
   STANCE LEDGER — where the papers stand

   The venn diagram is gone. Two overlapping circles with colored dots
   read as a dashboard widget, not a reading room. This is a ledger:
   papers grouped under plain stance headings, each row a citation
   number and a title that opens the paper. No geometry, no badges,
   no alarm. A contesting paper gets a clay numeral, never a red card.

   Placement is honest: from the fact-check and the disagreement
   section, never guessed. Papers with no signal sit under "no clear
   signal". Fewer than two classifiable papers and the ledger stays
   home.
   ════════════════════════════════════════════════════════════ */

function StanceLedger({ turn, P, accent, onOpenPaper = () => {} }) {
  const model = useMemo(
    () => classifyVennPapers({ answer: turn.answer, sources: turn.sources, factCheck: turn.factCheck, conflicts: turn.literatureConflicts }),
    [turn]
  );
  const classifiable = model.agree.length + model.disagree.length + model.middle.length;
  if (classifiable < 2) return null;

  const sources = turn.sources || [];
  const src = (n) => sources[n - 1] || {};

  const groups = [
    { key: "agree", label: "Supports the direction", ids: model.agree, numColor: accent },
    { key: "middle", label: "Qualifies it", ids: model.middle, numColor: accent },
    { key: "disagree", label: "Contests it", ids: model.disagree, numColor: STANCE_COLORS.contrasting },
  ].filter((g) => g.ids.length > 0);

  const paperRow = (n, numColor) => {
    const s = src(n);
    return (
      <button key={n} type="button" onClick={() => onOpenPaper(n)}
        aria-label={"[" + n + "] " + (s.title || "Untitled source") + ". Open this paper."}
        style={{
          display: "flex", gap: 10, alignItems: "baseline", width: "100%",
          background: "none", border: "none", borderTop: "1px solid " + P.line,
          padding: "8px 0", cursor: "pointer", textAlign: "left",
          fontFamily: "var(--cb-font)",
        }}>
        <span style={{
          fontWeight: 500, color: numColor, fontSize: FONT_SIZES.caption,
          flexShrink: 0, fontVariantNumeric: "tabular-nums",
        }}>
          [{n}]
        </span>
        <span style={{ fontSize: FONT_SIZES.caption, color: P.ink2, lineHeight: 1.55 }}>
          {renderTitleInline(s.title || "Untitled source", P)}
          {s.year ? <span style={{ color: P.faint }}> {"\u00b7"} {s.year}</span> : null}
        </span>
      </button>
    );
  };

  return (
    <AnswerSection quiet eyebrow="Where the papers stand" P={P} accent={accent}>
      <div style={{ maxWidth: 640 }}>
        {groups.map((g) => (
          <div key={g.key} style={{ marginBottom: 20 }}>
            <div style={{
              fontSize: FONT_SIZES.caption, color: P.faint,
              fontFamily: "var(--cb-font)", marginBottom: 2,
            }}>
              {g.label} {"\u00b7"} {g.ids.length}
            </div>
            <div>{g.ids.map((n) => paperRow(n, g.numColor))}</div>
          </div>
        ))}
        {model.unclear.length > 0 && (
          <div>
            <div style={{
              fontSize: FONT_SIZES.caption, color: P.faint,
              fontFamily: "var(--cb-font)", marginBottom: 6,
            }}>
              No clear signal {"\u00b7"} {model.unclear.length}
            </div>
            <div style={{ fontSize: FONT_SIZES.caption, color: P.faint, lineHeight: 1.7 }}>
              {model.unclear.map((n) => (
                <button key={n} type="button" onClick={() => onOpenPaper(n)}
                  aria-label={"[" + n + "] open this paper"}
                  style={{
                    background: "none", border: "none", padding: "4px 10px 4px 0",
                    cursor: "pointer", fontFamily: "var(--cb-font)",
                    fontSize: FONT_SIZES.caption, color: P.faint,
                    fontVariantNumeric: "tabular-nums",
                  }}>
                  [{n}]
                </button>
              ))}
              <div style={{ fontSize: FONT_SIZES.micro, marginTop: 4 }}>
                Placed from the fact-check and the disagreement section, never guessed.
              </div>
            </div>
          </div>
        )}
      </div>
    </AnswerSection>
  );
}


/* ══════════════════════════════════════════════════════════════════
   QUERY AUTOPSY — "How this answer was built"

   A drawer that opens the instrument up: what the pipeline read in the
   question, what the retrieval funnel did, what it threw away and why,
   and how the final text was produced. Four sections, every number
   traceable to the turn data — nothing here is estimated or narrated.

   Degrades honestly: when the backend didn't ship funnel counts (older
   cached answers, paths that never ran retrieval) the funnel and
   exclusion sections hide instead of inventing numbers; when the query
   was never resolved or reasoned about, the reading section says so.
   ══════════════════════════════════════════════════════════════════ */

const AUTOPSY_ENTITY_LABELS = { doi: "DOI", phrase: "Exact phrase", organism: "Organism", gene: "Gene / entity", mode: "Comparison" };

function AutopsySection({ P, accent, kicker, children }) {
  return (
    <section style={{ marginTop: 26 }}>
      <div style={{ fontFamily: "var(--cb-font)", fontSize: FONT_SIZES.micro, letterSpacing: "normal", textTransform: "none", color: accent, marginBottom: 12 }}>{kicker}</div>
      {children}
    </section>
  );
}

/* Impact formatters: the midpoint of the backend's estimated range,
   rounded the way a person would say it. */
function fmtImpactEnergy(impact) {
  const e = (impact && impact.energyWh) || {};
  if (typeof e.low !== "number" || typeof e.high !== "number") return "";
  const mid = (e.low + e.high) / 2;
  if (mid < 0.1) return "under 0.1 Wh";
  return (mid < 1 ? mid.toFixed(2) : mid.toFixed(1)).replace(/\.?0+$/, "") + " Wh";
}
function fmtImpactWater(impact) {
  const w = (impact && impact.waterMl) || {};
  if (typeof w.low !== "number" || typeof w.high !== "number") return "";
  const mid = (w.low + w.high) / 2;
  if (mid < 1) return "under 1 mL";
  return Math.round(mid) + " mL";
}

/* Stage health is tri state (2026-10-13): the server ships each stage's
   ok as true (ran and passed), false (ran and failed; the entry's
   skipReason names why), or null (skipped: the stage did not run or had
   nothing to do; its skipReason says which). A skipped stage is neutral,
   never a failure, and the server's degraded rule counts only
   ok === false. Every client surface that reads stageHealth classifies
   through this one helper so the three states cannot drift apart
   between the autopsy chips and the answer diagnostics. Any other ok
   value (an entry recorded before the tri state contract) reads as
   skipped: unknown is not failed. */
function stageState(s) {
  if (s && s.ok === true) return "passed";
  if (s && s.ok === false) return "failed";
  return "skipped";
}

function QueryAutopsy({ turn: t, P, accent, close, onStress = null, busy = false }) {
  /* Escape + focus are owned by ModalChrome now. */
  const isMobile = useIsMobile();
  const funnel = sanitizeFunnel(t._funnel);
  const stages = funnel ? funnelStages(funnel) : null;
  const exclusions = funnel ? funnelExclusions(funnel) : null;
  const entities = useMemo(() => parseQueryEntities(t.q || ""), [t.q]);
  const resolver = t._resolver || null;
  const reasoning = t._selfReasoning || null;
  const responded = Array.isArray(t.sourcesQueried) ? t.sourcesQueried.filter((s) => s.ok) : [];
  const totalDb = Array.isArray(t.sourcesQueried) ? t.sourcesQueried.length : 0;

  const monoLine = { fontSize: FONT_SIZES.caption, color: P.ink2, fontFamily: "var(--cb-font)", lineHeight: 1.7 };
  const notRecorded = <span style={{ ...monoLine, color: P.faint, fontStyle: "italic" }}>not recorded for this answer</span>;

  return (
    <ModalChrome drawer P={P} label="How this answer was built" eyebrow="Autopsy" title="How this answer was built" accent={accent} onClose={close}>
      <div style={{ fontSize: FONT_SIZES.caption, color: P.faint, lineHeight: 1.6, margin: "2px 0 6px" }}>
        The pipeline's own record of this answer, read from the response, not reconstructed.
      </div>

        {/* ── 01 · Retrieval funnel — the hero: one graphic, the counts ── */}
        {stages && (
          <AutopsySection P={P} accent={accent} kicker="01 · Retrieval funnel">
            <div style={{ display: "flex", flexDirection: "column", gap: 2, marginBottom: 14 }}>
              {(() => {
                const max = Math.max(...stages.map((s) => s.count), 1);
                return stages.map((s, i) => {
                  const w = 12 + 88 * (Math.log(s.count + 1) / Math.log(max + 1));
                  const last = i === stages.length - 1;
                  return (
                    <div key={s.key} style={{ display: "flex", alignItems: "center", gap: 12 }}>
                      <div style={{ width: 118, flexShrink: 0, textAlign: "right" }}>
                        <div style={{ fontFamily: "var(--cb-font)", fontSize: FONT_SIZES.micro, fontWeight: 500, letterSpacing: "normal", textTransform: "none", color: last ? accent : P.ink2 }}>{s.label}</div>
                        <div style={{ fontSize: FONT_SIZES.micro, color: P.faint, fontFamily: "var(--cb-font)", marginTop: 2 }}>{s.note.toLowerCase()}</div>
                      </div>
                      <div style={{ flex: 1, minWidth: 0, height: 34, display: "flex", alignItems: "center" }}>
                        <div style={{
                          width: `${w}%`, height: 22, borderRadius: RADIUS.sm,
                          background: last ? withAlpha(accent, 0.28) : (P.dark ? "rgba(255,255,255,0.07)" : "rgba(0,0,0,0.06)"),
                          border: `1px solid ${last ? withAlpha(accent, 0.5) : P.line}`,
                          display: "flex", alignItems: "center", paddingLeft: 10,
                          transition: "width 550ms ease",
                        }}>
                          <span style={{ fontFamily: "var(--cb-font)", fontSize: FONT_SIZES.small, fontWeight: 500, color: last ? accent : P.ink, fontVariantNumeric: "tabular-nums" }}>{s.count}</span>
                        </div>
                      </div>
                    </div>
                  );
                });
              })()}
            </div>
            {totalDb > 0 && (
              <>
                <div style={{ display: "flex", flexWrap: "wrap", gap: "6px 10px" }}>
                  {t.sourcesQueried.map((s) => (
                    <span key={s.source} style={{
                      fontSize: FONT_SIZES.micro, fontFamily: "var(--cb-font)",
                      color: s.ok ? P.ink2 : P.faint,
                      border: `1px solid ${s.ok ? withAlpha(accent, 0.35) : P.line}`,
                      background: s.ok ? withAlpha(accent, 0.07) : "transparent",
                      borderRadius: RADIUS.viewport, padding: "3px 12px",
                      display: "inline-flex", alignItems: "center", gap: 6,
                    }}>
                      <span style={{ width: 4, height: 4, borderRadius: "50%", background: s.ok ? accent : P.line }} />
                      {s.source}{s.ok && s.count ? ` ${s.count}` : ""}
                    </span>
                  ))}
                </div>
              </>
            )}
          </AutopsySection>
        )}

        {/* ── 02 · Query reading ── */}
        <AutopsySection P={P} accent={accent} kicker="02 · Query reading">
          <div style={{ fontSize: 14, color: P.faint, marginBottom: 8, fontFamily: "var(--cb-font)", letterSpacing: "normal" }}>Entities</div>
          {entities.length ? (
            <div style={{ display: "flex", flexWrap: "wrap", gap: 6, marginBottom: 16 }}>
              {entities.map((e, i) => (
                <span key={i} style={{ fontSize: FONT_SIZES.caption, fontFamily: "var(--cb-font)", color: P.ink2, border: `1px solid ${P.line}`, borderRadius: RADIUS.pill, padding: "3px 12px" }}>
                  <span style={{ color: accent, fontWeight: 500, marginRight: 6 }}>{AUTOPSY_ENTITY_LABELS[e.kind] || e.kind}</span>{e.value}
                </span>
              ))}
            </div>
          ) : (
            <div style={{ ...monoLine, marginBottom: 16, color: P.faint, fontStyle: "italic" }}>No structured entities detected. Treated as a plain research question.</div>
          )}
          <div style={{ fontSize: 14, color: P.faint, marginBottom: 8, fontFamily: "var(--cb-font)", letterSpacing: "normal" }}>Query</div>
          {resolver ? (
            <div style={{ ...monoLine, marginBottom: 16 }}>
              {resolver.intent && <div>intent · <span style={{ color: P.ink }}>{resolver.intent}</span></div>}
              {resolver.topic && <div>topic · <span style={{ color: P.ink }}>{resolver.topic}</span></div>}
              {resolver.resolvedQuery && <div>resolved query · <span style={{ color: P.ink }}>“{resolver.resolvedQuery}”</span></div>}
              {!resolver.intent && !resolver.topic && !resolver.resolvedQuery && notRecorded}
            </div>
          ) : (
            <div style={{ marginBottom: 16 }}>{notRecorded}</div>
          )}
          <div style={{ fontSize: 14, color: P.faint, marginBottom: 8, fontFamily: "var(--cb-font)", letterSpacing: "normal" }}>Reasoning</div>
          {reasoning ? (
            <div style={{ ...monoLine }}>
              {reasoning.complexity && <div>complexity · <span style={{ color: P.ink }}>{reasoning.complexity}</span></div>}
              {Array.isArray(reasoning.keyTerms) && reasoning.keyTerms.length > 0 && (
                <div style={{ marginTop: 8, display: "flex", flexWrap: "wrap", gap: 6 }}>
                  {reasoning.keyTerms.slice(0, 12).map((k, i) => (
                    <span key={i} style={{ fontSize: FONT_SIZES.caption, color: P.ink2, background: withAlpha(accent, 0.08), border: `1px solid ${withAlpha(accent, 0.25)}`, borderRadius: RADIUS.pill, padding: "2px 9px" }}>{k}</span>
                  ))}
                </div>
              )}
              {Array.isArray(reasoning.subQuestions) && reasoning.subQuestions.length > 0 && (
                <div style={{ marginTop: 10 }}>
                  <div style={{ color: P.faint, marginBottom: 6 }}>sub-questions considered</div>
                  {reasoning.subQuestions.slice(0, 8).map((sq, i) => (
                    <div key={i} style={{ color: P.ink2, paddingLeft: 14, textIndent: -14, marginBottom: 4 }}><span style={{ color: accent }}>{i + 1}.</span> {sq}</div>
                  ))}
                </div>
              )}
            </div>
          ) : (
            <div>{notRecorded}</div>
          )}
        </AutopsySection>

        {/* ── 03 · Exclusions ── */}
        {exclusions && (
          <AutopsySection P={P} accent={accent} kicker="03 · Exclusions">
            <div style={{ border: `1px solid ${P.line}`, borderRadius: RADIUS.md, overflow: "hidden" }}>
              {exclusions.map((r, i) => (
                <div key={r.reason} style={{ display: "flex", gap: 12, alignItems: "baseline", padding: "12px 16px", borderTop: i ? `1px solid ${P.line}` : "none", background: i % 2 ? (P.dark ? "rgba(255,255,255,0.015)" : "rgba(0,0,0,0.015)") : "transparent" }}>
                  <span style={{ fontFamily: "var(--cb-font)", fontSize: FONT_SIZES.body, fontWeight: 500, color: P.ink, minWidth: 44, textAlign: "right", fontVariantNumeric: "tabular-nums" }}>{r.count}</span>
                  <span style={{ flex: 1, minWidth: 0 }}>
                    <span style={{ fontSize: FONT_SIZES.small, fontWeight: 500, color: P.ink2, display: "block" }}>{r.reason}</span>
                    <span style={{ fontSize: FONT_SIZES.caption, color: P.faint, display: "block", lineHeight: 1.5 }}>{r.note}</span>
                  </span>
                </div>
              ))}
            </div>
          </AutopsySection>
        )}

        {/* ── 04 · Synthesis ── */}
        <AutopsySection P={P} accent={accent} kicker="04 · Synthesis">
          <div style={{ display: "inline-flex", alignItems: "center", gap: 8, border: `1px solid ${withAlpha(accent, 0.4)}`, background: withAlpha(accent, 0.08), borderRadius: RADIUS.viewport, padding: "6px 16px", marginBottom: 10 }}>
            <span style={{ width: 6, height: 6, borderRadius: "50%", background: accent }} />
            <span style={{ fontSize: FONT_SIZES.caption, fontWeight: 500, color: accent, fontFamily: "var(--cb-font)" }}>
              {t.synthesisMode === "extractive" ? "DRAFTED FROM SOURCES" : t.synthesisMode === "none" ? "NO SYNTHESIS" : "AI WRITTEN"}
            </span>
          </div>
          <div style={{ ...monoLine, color: P.faint }}>
            {t.synthesisMode === "extractive"
              ? "No model wrote this text. It was assembled from the numbered papers."
              : t.synthesisMode === "none"
                ? "No written answer was produced for this answer."
                : "An AI wrote this text from the papers above. Every claim should trace to a numbered paper. Open them to check."}
          </div>
        </AutopsySection>

        {/* ── 5 · Stress test (demoted from the answer stack) ── */}
        {onStress && (t.factCheck || (t.sources && t.sources.length)) ? (
          <AutopsySection P={P} accent={accent} kicker="05 · Stress test">
            <StressTest turn={t} P={P} accent={accent} at={null} onStress={onStress} busy={busy}
              isMobile={isMobile} />
          </AutopsySection>
        ) : null}

        {/* ── 6 · Evidence structure (demoted from the answer stack) ── */}
        {t.evidenceStructure ? (
          <AutopsySection P={P} accent={accent} kicker="06 · Evidence structure">
            <EvidenceStructure data={t.evidenceStructure} P={P} accent={accent}
              isMobile={isMobile} />
            <CitationThreads data={t.evidenceStructure} P={P} accent={accent} />
          </AutopsySection>
        ) : null}

        {/* ── 07 · Pipeline health (NEXT-GEN) — per-stage outcomes, the
            computed confidence, evidence gaps, and the disagreement
            verdict. Read from the response; absent on older cached turns. */}
        {(Array.isArray(t.stageHealth) && t.stageHealth.length > 0) || t.confidence || (Array.isArray(t.evidenceGaps) && t.evidenceGaps.length > 0) || t.disagreementVerdict ? (
          <AutopsySection P={P} accent={accent} kicker="07 · Pipeline health">
            {Array.isArray(t.stageHealth) && t.stageHealth.length > 0 && (
              <div style={{ display: "flex", flexWrap: "wrap", gap: "6px 10px", marginBottom: 12 }}>
                {t.stageHealth.map((s, i) => {
                  const state = stageState(s);
                  const reason = typeof s.skipReason === "string" && s.skipReason ? s.skipReason : null;
                  const title = state === "passed"
                    ? `${s.name}: ok`
                    : state === "failed"
                      ? (reason ? `${s.name}: failed (${reason})` : `${s.name}: failed over to a fallback`)
                      : (reason ? `${s.name}: skipped (${reason})` : `${s.name}: skipped`);
                  return (
                    <span key={i} title={title}
                      style={{
                        fontSize: FONT_SIZES.micro, fontFamily: "var(--cb-font)",
                        color: state === "passed" ? P.ink2 : state === "failed" ? statusWarn(P) : P.faint,
                        border: `1px solid ${state === "passed" ? withAlpha(accent, 0.35) : state === "failed" ? withAlpha(STATUS.warn, 0.4) : P.line}`,
                        background: state === "passed" ? withAlpha(accent, 0.07) : state === "failed" ? withAlpha(STATUS.warn, 0.06) : "transparent",
                        borderRadius: RADIUS.viewport, padding: "3px 12px",
                        display: "inline-flex", alignItems: "center", gap: 6,
                      }}>
                      <span style={{ width: 4, height: 4, borderRadius: "50%", background: state === "passed" ? accent : state === "failed" ? STATUS.warn : P.line }} />
                      {s.name}{state === "skipped" ? " · skipped" : ""}{typeof s.ms === "number" && s.ms > 0 ? ` ${(s.ms / 1000).toFixed(1)}s` : ""}
                    </span>
                  );
                })}
              </div>
            )}
            {t.confidence && t.confidence.line && (
              <div style={{ ...monoLine, marginBottom: 8 }}>
                <span style={{ fontWeight: 500, color: P.ink }}>Confidence · {t.confidence.level}: </span>
                {t.confidence.line}
              </div>
            )}
            {t.disagreementVerdict && t.disagreementVerdict.summary && (
              <div style={{ ...monoLine, marginBottom: 8 }}>
                <span style={{ fontWeight: 500, color: P.ink }}>Disagreement · {t.disagreementVerdict.status}: </span>
                {t.disagreementVerdict.summary}
              </div>
            )}
            {Array.isArray(t.evidenceGaps) && t.evidenceGaps.length > 0 && (
              <div style={{ marginTop: 4 }}>
                <div style={{ fontSize: FONT_SIZES.micro, color: P.faint, marginBottom: 6, fontFamily: "var(--cb-font)", letterSpacing: TRACKING.eyebrow }}>Evidence gaps</div>
                {t.evidenceGaps.map((g, i) => (
                  <div key={i} style={{ ...monoLine, marginBottom: 4 }}>· {g}</div>
                ))}
              </div>
            )}
          </AutopsySection>
        ) : null}

        {/* ── 08 · Footprint — what this search cost in electricity and
            water. An estimate from the backend (providers report no
            actuals), built from the run's real token count and database
            count. Absent on older cached turns. */}
        {t.impact ? (
          <AutopsySection P={P} accent={accent} kicker="08 · Footprint">
            <div style={{ ...monoLine, marginBottom: 8 }}>
              <div>electricity · <span style={{ color: P.ink }}>about {fmtImpactEnergy(t.impact)}</span> <span style={{ color: P.faint }}>({t.impact.energyWh.low} to {t.impact.energyWh.high} Wh range)</span></div>
              <div>water · <span style={{ color: P.ink }}>about {fmtImpactWater(t.impact)}</span> <span style={{ color: P.faint }}>({t.impact.waterMl.low} to {t.impact.waterMl.high} mL range)</span></div>
              {typeof t.impact.llmTokens === "number" && t.impact.llmTokens > 0 && (
                <div>synthesis · <span style={{ color: P.ink }}>{t.impact.llmTokens.toLocaleString()} tokens</span></div>
              )}
              {typeof t.impact.databasesQueried === "number" && (
                <div>retrieval · <span style={{ color: P.ink }}>{t.impact.databasesQueried} databases queried</span></div>
              )}
            </div>
            <div style={{ ...monoLine, color: P.faint }}>
              An estimate, not a meter reading. Providers do not report actual energy or water use, so Cerebrum prices the tokens this search really burned at published per token inference energy for large models (0.1 to 0.5 joules per token), adds a 1.3 times facility overhead and a small flat cost per database, then applies a total water figure of 1.8 mL per Wh for cooling and power generation. An answer drafted from sources without AI skips the token cost, which is most of the footprint.
            </div>
          </AutopsySection>
        ) : null}
    </ModalChrome>
  );
}

/* ══════════════════════════════════════════════════════════════════
   ANSWER ARC — the narrative arc of the cited literature

   The timeline's "Plot" view shows where papers sit in time. The "Arc"
   view reads the story those positions tell: which era laid the
   foundations, which era built on them, where the current work clusters,
   and whether the core claims still rest on old ground or have moved.

   Every line is computed from the cited sources, the fact-check's cited
   indices, and the disagreement section's citations — nothing else. Each
   line carries its own hedge.
   ══════════════════════════════════════════════════════════════════ */

/* The scatter plot compressed into the era header: one strip, dots =
   papers, horizontal position = publication year. The Plot view is gone;
   this is the only time-axis the arc needs. */
function EraYearStrip({ era, P, accent, isNewest }) {
  const papers = (era.papers || []).filter((p) => Number.isFinite(p.year));
  if (!papers.length) return null;
  const lo = era.startYear, hi = era.endYear;
  const span = Math.max(1, hi - lo);
  return (
    <div style={{ margin: "8px 0 2px" }} role="img"
      aria-label={`${papers.length} papers, ${lo} to ${hi}`}>
      <div style={{ position: "relative", height: 26, borderBottom: `1px solid ${P.line}` }}>
        {papers.map((p) => {
          const x = lo === hi ? 50 : 3 + 94 * ((p.year - lo) / span);
          return (
            <span key={p.index} title={`${p.source.title || "Untitled"} · ${p.year}`}
              style={{
                position: "absolute", left: `${x}%`, top: 8, width: 7, height: 7,
                borderRadius: "50%", transform: "translateX(-50%)",
                background: isNewest ? accent : P.faint,
                border: `1px solid ${P.bg}`,
              }} />
          );
        })}
      </div>
      <div style={{ display: "flex", justifyContent: "space-between", marginTop: 3 }}>
        <span style={{ fontFamily: "var(--cb-font)", fontSize: FONT_SIZES.micro, color: P.faint }}>{lo}</span>
        <span style={{ fontFamily: "var(--cb-font)", fontSize: FONT_SIZES.micro, color: P.faint }}>{papers.length} paper{papers.length === 1 ? "" : "s"}</span>
        <span style={{ fontFamily: "var(--cb-font)", fontSize: FONT_SIZES.micro, color: P.faint }}>{hi}</span>
      </div>
    </div>
  );
}

function AnswerArc({ turn, P, accent }) {
  const model = useMemo(() => {
    const eras = groupSourcesIntoEras(turn.sources);
    if (!eras) return null;
    return annotateEras(eras, {
      factCheck: turn.factCheck,
      disagreementIndices: disagreementCitedIndices(turn.answer, (turn.sources || []).length),
      sources: turn.sources,
    });
  }, [turn]);
  if (!model) return null;
  const hasFactCheck = model.claimsTotal > 0;
  const newest = model.eras[model.eras.length - 1];
  const convergence = describeConvergence(model.convergence, newest);
  return (
    <div style={{ padding: "6px 22px 24px" }}>
      <div style={{ display: "flex", flexDirection: "column" }}>
        {model.eras.map((era, i) => (
          <div key={era.name} style={{ display: "flex", gap: 14, padding: "16px 0", borderTop: i ? `1px solid ${P.line}` : "none" }}>
            <div style={{ display: "flex", flexDirection: "column", alignItems: "center", flexShrink: 0, width: 22 }} aria-hidden="true">
              <span style={{ width: 9, height: 9, borderRadius: "50%", background: i === model.eras.length - 1 ? accent : P.faint, marginTop: 4 }} />
              {i < model.eras.length - 1 && <span style={{ width: 1, flex: 1, minHeight: 26, background: P.line, marginTop: 4 }} />}
            </div>
            <div style={{ minWidth: 0, flex: 1 }}>
              <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap", marginBottom: 5 }}>
                <span style={{ fontSize: FONT_SIZES.small, fontWeight: 500, color: P.ink }}>{era.name}</span>
                {era.disagreementCount > 0 && (
                  <span style={{ fontSize: FONT_SIZES.caption, fontFamily: "var(--cb-font)", color: P.faint }}>
                    <span aria-hidden="true" style={{ display: "inline-block", width: 7, height: 7, borderRadius: "50%", background: STANCE_COLORS.contrasting, marginRight: 6 }} />
                    {era.disagreementCount} contested {era.disagreementCount === 1 ? "claim" : "claims"} in this era
                  </span>
                )}
              </div>
              <EraYearStrip era={era} P={P} accent={accent} isNewest={i === model.eras.length - 1} />
              <div style={{ fontSize: FONT_SIZES.caption, color: P.ink2, lineHeight: 1.65, fontFamily: "var(--cb-font)" }}>{describeEra(era, hasFactCheck)}</div>
            </div>
          </div>
        ))}
      </div>
      {convergence && (
        <div style={{ marginTop: 6, padding: "12px 16px", border: `1px solid ${P.line}`, borderRadius: RADIUS.viewport, fontSize: FONT_SIZES.small, color: P.ink2, lineHeight: 1.6, fontFamily: "var(--cb-font)" }}>
          <span style={{ color: P.faint, marginRight: 8 }}>Where it lands:</span>
          {convergence}
        </div>
      )}
    </div>
  );
}

/* ══════════════════════════════════════════════════════════════════
   OPEN QUESTIONS — the research gap finder

   Reads the answer for what it admits it doesn't know: hedge-pattern
   sentences in the disagreement/confidence sections, thin or unsupported
   fact-check claims, and query-plan angles the answer never takes up.
   Each card quotes its source sentence and names entry papers via the
   citations on that sentence — so every gap is a doorway, not a wall.

   Rendered only when at least one gap surfaces; the toolbar button that
   opens it hides entirely otherwise. The empty state below is the honest
   fallback for any path that renders the panel with nothing in it.
   ══════════════════════════════════════════════════════════════════ */

const OQ_KIND_LABEL = { gap: "Gap in the literature", fragile: "Fragile claim", angle: "Uncovered angle" };

function OpenQuestions({ cards, P, accent }) {
  const [open, setOpen] = useState(true);
  if (!cards || cards.length === 0) {
    return (
      <div style={{ marginTop: 20, padding: "16px 24px", border: `1px solid ${P.line}`, borderRadius: RADIUS.md, background: P.dark ? "rgba(255,255,255,0.02)" : "rgba(0,0,0,0.02)" }}>
        <div style={{ fontSize: FONT_SIZES.small, color: P.ink2, lineHeight: 1.6 }}>No open questions surfaced in this literature.</div>
        <div style={{ fontSize: FONT_SIZES.caption, color: P.faint, marginTop: 4, lineHeight: 1.6 }}>The answer, its fact-check, and the query plan gave the gap finder nothing to work with, which is itself a signal about how settled this ground is.</div>
      </div>
    );
  }
  return (
    <UICard P={P} style={{ marginTop: SP.xl }}>
      <UILabel P={P} accent={accent} right={
        <button onClick={() => setOpen((v) => !v)} style={{
          background: "none", border: "none", color: P.faint, cursor: "pointer",
          fontSize: FONT_SIZES.micro, fontFamily: "var(--cb-font)", fontWeight: 500, padding: 0,
        }}>{open ? "Hide" : "Show"}</button>
      }>Open questions · {cards.length}</UILabel>
      {open && (
        <div style={{ display: "flex", flexDirection: "column", gap: SP.lg }}>
          {cards.map((c, i) => (
            <div key={i} style={{ paddingTop: i ? SP.md : 0, borderTop: i ? `1px solid ${P.line}` : "none" }}>
              <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 6 }}>
                <span style={{
                  fontSize: FONT_SIZES.micro, fontFamily: "var(--cb-font)", fontWeight: 500, letterSpacing: TRACKING.label,
                  color: c.kind === "fragile" ? statusWarn(P) : accent,
                  background: withAlpha(c.kind === "fragile" ? STATUS.warn : accent, 0.1),
                  border: `1px solid ${withAlpha(c.kind === "fragile" ? STATUS.warn : accent, 0.3)}`,
                  padding: "2px 9px", borderRadius: RADIUS.viewport,
                }}>{(OQ_KIND_LABEL[c.kind] || "Open question").toUpperCase()}</span>
                <span style={{ fontSize: FONT_SIZES.micro, color: P.faint, fontFamily: "var(--cb-font)" }}>{c.sourceLabel}</span>
              </div>
              <div style={{ fontSize: FONT_SIZES.body, fontWeight: 500, color: P.ink, lineHeight: 1.5, marginBottom: 8 }}>“{c.question}”</div>
              <div style={{ display: "grid", gap: 6, marginBottom: 8 }}>
                <div style={{ fontSize: FONT_SIZES.small, color: P.ink2, lineHeight: 1.6 }}>
                  <span style={{ color: P.faint, fontFamily: "var(--cb-font)", fontSize: FONT_SIZES.micro, letterSpacing: TRACKING.label, display: "block", marginBottom: 2 }}>WHY IT'S STILL OPEN</span>
                  {c.whyOpen}
                </div>
                <div style={{ fontSize: FONT_SIZES.small, color: P.ink2, lineHeight: 1.6 }}>
                  <span style={{ color: P.faint, fontFamily: "var(--cb-font)", fontSize: FONT_SIZES.micro, letterSpacing: TRACKING.label, display: "block", marginBottom: 2 }}>What would close it</span>
                  {c.whatWouldCloseIt}
                </div>
              </div>
              {c.startWith.length > 0 && (
                <div style={{ marginBottom: 8 }}>
                  <div style={{ color: P.faint, fontFamily: "var(--cb-font)", fontSize: FONT_SIZES.micro, letterSpacing: TRACKING.label, marginBottom: 6 }}>START WITH</div>
                  <div style={{ display: "flex", flexDirection: "column", gap: 4 }}>
                    {c.startWith.map((e) => (
                      <div key={e.n} style={{ fontSize: FONT_SIZES.caption, color: P.ink2, display: "flex", gap: 8, alignItems: "baseline" }}>
                        <span style={{ fontFamily: "var(--cb-font)", fontWeight: 500, color: accent, background: withAlpha(accent, 0.12), border: `1px solid ${withAlpha(accent, 0.3)}`, borderRadius: RADIUS.pill, padding: "1px 7px", flexShrink: 0 }}>[{e.n}]</span>
                        <span style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{e.title}{e.year ? ` · ${e.year}` : ""}</span>
                      </div>
                    ))}
                  </div>
                </div>
              )}
              <details style={{ marginTop: 4 }}>
                <summary style={{ fontSize: FONT_SIZES.caption, color: P.faint, cursor: "pointer", fontFamily: "var(--cb-font)" }}>Source sentence</summary>
                <div style={{ fontSize: FONT_SIZES.caption, color: P.ink2, lineHeight: 1.65, marginTop: 6, padding: "8px 12px", borderLeft: `2px solid ${P.line}`, fontStyle: "italic" }}>“{c.sourceSentence}”</div>
              </details>
            </div>
          ))}
          <div style={{ fontSize: FONT_SIZES.micro, color: P.faint, lineHeight: 1.6 }}>
            Gaps are read from the answer's own hedging, its fact-check, and the query plan. Never invented. An absence of gaps means the literature, as cited, looks settled.
          </div>
        </div>
      )}
    </UICard>
  );
}

/* ══════════════════════════════════════════════════════════════════
   ANSWER EXPERIENCE — reading flow, jump rail, evidence band.

   The answer is read top-down: the answer itself, then what it stands on
   (the Evidence band: Bibliography + Videos as tabs), then verification
   (fact-check), then where the literature disagrees, then side-by-side
   comparison, then open questions. Every section renders its shell always:
   zero data gets an honest empty state with a retry action, a failed load
   gets a failed shell with retry — never a silent gap, never bare error
   text. Status shown anywhere here is derived from the turn's real data
   (t.answer, t.sources, t.videos, t.factCheck, t.sourcesQueried,
   t.synthesisMode) — nothing is invented.
   ══════════════════════════════════════════════════════════════════ */

/* The loading motif for the answer experience: a hairline with a
   travelling marker plus a mono readout. The marker's travel is ambient
   (activity, not progress) — no percentages, because none exist. Never a
   shimmer bar, never a bare "Loading…" string. */
function ReadHead({ label, P, accent }) {
  return (
    <div role="status" aria-label={label} style={{ padding: "24px 4px 22px" }}>
      <div className="cb-readhead" style={{ background: P.line }}>
        <span className="cb-readhead-marker" style={{ background: accent }} />
      </div>
      <div style={{ marginTop: 10, fontFamily: "var(--cb-font)", fontSize: FONT_SIZES.micro, fontWeight: 500, letterSpacing: "normal", textTransform: "none", color: P.faint }}>
        {label}
      </div>
    </div>
  );
}

/* One designed state for every empty/error condition in the answer
   experience. Plain copy, no apologies. Actions are only rendered when
   the caller passes wired callbacks — a button that does nothing is
   worse than no button. */
function AnswerStateCard({ kicker, title, body, actions = [], tone = "neutral", P, accent, children }) {
  const toneColor = tone === "bad" ? statusBad(P) : tone === "warn" ? statusWarn(P) : P.faint;
  /* Pass 5: squared editorial buttons — the radius system reserves true
     pills for compact filters/statuses, and these are neither. */
  const btnBase = {
    minHeight: 44, display: "inline-flex", alignItems: "center",
    padding: "12px 16px", borderRadius: RADIUS.sm, cursor: "pointer",
    fontSize: FONT_SIZES.caption, fontWeight: 500, fontFamily: "var(--cb-font)",
    transition: "border-color 150ms ease, background 150ms ease",
  };
  /* Pass 2 (instrument): state is a ruled strip, not a box. A hairline on
     top, the kicker in the tone color, title, body, actions. No enclosing
     border, no fill, no radius — it reads as a gauge reading, not a card. */
  return (
    <div style={{
      borderTop: `1px solid ${tone === "neutral" ? P.line : withAlpha(toneColor, 0.45)}`,
      padding: "18px 4px 4px",
    }} className="cb-fade">
      <div className="cb-kicker" style={{ color: toneColor, marginBottom: 8 }}>
        {kicker}
      </div>
      <div style={{ fontSize: FONT_SIZES.subhead, fontWeight: 500, color: P.ink, fontFamily: "var(--cb-font)", letterSpacing: TYPE.heading.letterSpacing, marginBottom: body ? 8 : 0, lineHeight: 1.35 }}>
        {title}
      </div>
      {body && <div style={{ fontSize: FONT_SIZES.small, color: P.ink2, lineHeight: 1.65, maxWidth: 600 }}>{body}</div>}
      {children}
      {actions.length > 0 && (
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginTop: 16 }}>
          {actions.map((a, i) => (
            <UIButton P={P} variant="ghost" key={i} type="button" onClick={a.onClick}
              style={{
                ...btnBase,
                border: `1px solid ${a.primary ? withAlpha(accent, 0.5) : P.line2}`,
                background: a.primary ? withAlpha(accent, 0.1) : "transparent",
                color: a.primary ? accent : P.ink2,
              }}
              onMouseEnter={(e) => { e.currentTarget.style.borderColor = withAlpha(accent, 0.6); e.currentTarget.style.color = accent; }}
              onMouseLeave={(e) => { e.currentTarget.style.borderColor = a.primary ? withAlpha(accent, 0.5) : P.line2; e.currentTarget.style.color = a.primary ? accent : P.ink2; }}>
              {a.label}
            </UIButton>
          ))}
        </div>
      )}
    </div>
  );
}

/* "Try a different query" — a real re-search through the ask pipeline,
   for the zero-result states. Rendered only where the caller passes a
   wired onAsk. */
function QueryRetryForm({ P, accent, onAsk, id }) {
  const [q, setQ] = useState("");
  const ready = q.trim().length > 0;
  return (
    <form
      onSubmit={(e) => { e.preventDefault(); const v = q.trim(); if (v) onAsk(v); }}
      style={{ display: "flex", gap: 8, marginTop: 14, maxWidth: 480 }}
    >
      <input
        id={id} value={q} onChange={(e) => setQ(e.target.value)}
        placeholder="Try a different query…"
        aria-label="Try a different query"
        style={{
          flex: 1, minWidth: 0, background: "transparent", border: `1px solid ${P.line2}`,
          borderRadius: RADIUS.md, padding: "8px 12px", fontSize: 16, color: P.ink,
          fontFamily: "var(--cb-font)", outline: "none",
        }}
      />
      <button
        type="submit" disabled={!ready}
        style={{ minHeight: 44,
          padding: "8px 16px", borderRadius: RADIUS.md, border: `1px solid ${withAlpha(accent, 0.4)}`,
          background: withAlpha(accent, 0.1), color: accent, fontSize: FONT_SIZES.caption,
          fontWeight: 500, fontFamily: "var(--cb-font)", cursor: ready ? "pointer" : "default",
          opacity: ready ? 1 : 0.45, whiteSpace: "nowrap",
        }}
      >
        Ask
      </button>
    </form>
  );
}

/* Sticky section jump rail: slim mono micro-labels for the answer's
   sections, each with a live status dot — ready (accent), empty (hollow),
   failed (bad). Statuses are derived from the turn's real data in
   TurnInner, not invented here. Buttons, so touch works; nothing here
   depends on hover. */
function JumpRail({ items, P, accent, onJump, isMobile, onFollowUp = null }) {
  /* Four tabs, not seven: Answer, Evidence, Videos stay; Fact-check,
     Disagreements, Compare and Open questions move behind "More".
     No status dots — a count says "has content" better than a 6px dot
     nobody decodes. Sentence case, one hairline underneath. */
  const [moreOpen, setMoreOpen] = useState(false);
  const moreRef = useRef(null);
  useEffect(() => {
    if (!moreOpen) return undefined;
    const onDown = (e) => { if (moreRef.current && !moreRef.current.contains(e.target)) setMoreOpen(false); };
    const onKey = (e) => { if (e.key === "Escape") setMoreOpen(false); };
    document.addEventListener("mousedown", onDown);
    document.addEventListener("keydown", onKey);
    return () => { document.removeEventListener("mousedown", onDown); document.removeEventListener("keydown", onKey); };
  }, [moreOpen]);
  const primary = items.slice(0, 3);
  const overflow = items.slice(3);
  const tabBtn = (it) => (
    <button
      key={it.id} type="button" onClick={() => onJump(it.id)}
      aria-label={`${it.label}${it.count != null ? `, ${it.count}` : ""}`}
      style={{ minHeight: 44,
        display: "inline-flex", alignItems: "center", gap: 6,
        padding: "12px 12px", background: "none", border: "none",
        cursor: "pointer", whiteSpace: "nowrap", flexShrink: 0,
        fontFamily: "var(--cb-font)", fontSize: FONT_SIZES.small, fontWeight: 500,
        letterSpacing: TYPE.heading.letterSpacing, color: it.status === "empty" ? P.faint : P.ink2,
      }}
    >
      {it.label}
      {it.count != null && (
        <span style={{ fontSize: FONT_SIZES.micro, color: P.faint, fontVariantNumeric: "tabular-nums", fontWeight: 500 }}>
          {it.count}
        </span>
      )}
    </button>
  );
  return (
    <div style={{
      position: "sticky", top: isMobile ? 56 : 64, zIndex: Z.dropdown, background: P.bg,
      marginTop: 22, borderBottom: `1px solid ${P.line}`,
    }}>
      <div role="navigation" aria-label="Answer sections" className="cb-jumpnav"
        style={{ display: "flex", gap: 2, padding: "4px 2px", scrollbarWidth: "none", alignItems: "center" }}>
        {primary.map(tabBtn)}
        <div ref={moreRef} className="cb-jumpmore" style={{ position: "relative", flexShrink: 0 }}>
          <button type="button" className="cb-jumpmore-btn" onClick={() => setMoreOpen((v) => !v)} aria-expanded={moreOpen} aria-haspopup="menu"
            style={{ minHeight: 44,
              display: "inline-flex", alignItems: "center", gap: 6,
              padding: "12px 12px", background: "none", border: "none",
              cursor: "pointer", whiteSpace: "nowrap",
              fontFamily: "var(--cb-font)", fontSize: FONT_SIZES.small, fontWeight: 500,
              letterSpacing: TYPE.heading.letterSpacing, color: P.ink2,
            }}>
            More
            <span style={{ display: "inline-flex", transform: moreOpen ? "rotate(180deg)" : "none", transition: "transform 150ms ease" }}>
              <Icon name="chevronDown" size={12} />
            </span>
          </button>
          {moreOpen && (
            <div role="menu" aria-label="More answer sections" className="cb-fade" onKeyDown={menuArrowKeys}
              style={{
                /* Right-anchored: the More button sits at the rail's right
                   edge, so a left-anchored menu runs off the viewport on a
                   phone. Right-anchoring keeps the whole panel on screen. */
                position: "absolute", right: 0, left: "auto", top: "calc(100% + 6px)", minWidth: 200, zIndex: Z.menu,
                background: P.dark ? "#14161a" : "#ffffff",
                border: `1px solid ${P.line}`, borderRadius: RADIUS.lg, padding: 6,
                boxShadow: "none",
              }}>
              {overflow.map((it) => (
                <button key={it.id} type="button" role="menuitem"
                  onClick={() => { setMoreOpen(false); onJump(it.id); }}
                  style={{ minHeight: 44,
                    display: "flex", alignItems: "center", justifyContent: "space-between",
                    width: "100%", padding: "12px 12px", background: "none", border: "none",
                    borderRadius: RADIUS.md, cursor: "pointer", textAlign: "left",
                    fontFamily: "var(--cb-font)", fontSize: FONT_SIZES.small, fontWeight: 500,
                    color: it.status === "empty" ? P.faint : P.ink,
                  }}>
                  <span>{it.label}</span>
                  {it.count != null && (
                    <span style={{ fontSize: FONT_SIZES.micro, color: P.faint, fontVariantNumeric: "tabular-nums" }}>
                      {it.count}
                    </span>
                  )}
                </button>
              ))}
              {/* 2026-10-16 layout fix (finding 8): on mobile the follow
                  up action lives in this menu instead of as a rail item.
                  The rail row summed to about 390px against 320px
                  available at 360px and the action fell off the right
                  edge, clipped by the page. A sideways scroll was the
                  other option and it was rejected here because an
                  overflow container on the rail would clip this very
                  menu, which is why the rail keeps overflow visible. */}
              {isMobile && onFollowUp && (
                <button type="button" role="menuitem"
                  onClick={() => { setMoreOpen(false); onFollowUp(); }}
                  style={{ minHeight: 44,
                    display: "flex", alignItems: "center", justifyContent: "space-between",
                    width: "100%", padding: "12px 12px", background: "none", border: "none",
                    borderRadius: RADIUS.md, cursor: "pointer", textAlign: "left",
                    fontFamily: "var(--cb-font)", fontSize: FONT_SIZES.small, fontWeight: 500,
                    letterSpacing: TYPE.heading.letterSpacing, color: accent,
                  }}>
                  <span>Ask a follow up</span>
                </button>
              )}
            </div>
          )}
        </div>
        {onFollowUp && !isMobile && (
          <button type="button" onClick={onFollowUp}
            style={{ minHeight: 44, marginLeft: "auto", display: "inline-flex", alignItems: "center", padding: "12px 12px", background: "none", border: "none", cursor: "pointer", whiteSpace: "nowrap", flexShrink: 0, fontFamily: "var(--cb-font)", fontSize: FONT_SIZES.small, fontWeight: 500, letterSpacing: TYPE.heading.letterSpacing, color: accent }}>
            Ask a follow up
          </button>
        )}
      </div>
    </div>
  );
}

/* The toolbar's overflow: every demoted action stays one tap away behind
   a labeled "More" menu. Items are plain data ({ id, label, icon, hint,
   onClick } or { divider: true }) so TurnInner decides the set. Closes on
   selection, outside tap, or Escape. */
/* Basic arrow-key navigation for role="menu" popups: Up/Down walks the
   menuitems, Home/End jumps to the ends. Wired on the export menu, the
   jump-rail "More" menu, and ToolbarOverflow. */
function menuArrowKeys(e) {
  if (!["ArrowDown", "ArrowUp", "Home", "End"].includes(e.key)) return;
  const items = Array.from(e.currentTarget.querySelectorAll('[role="menuitem"]')).filter((el) => !el.disabled);
  if (!items.length) return;
  e.preventDefault();
  const i = items.indexOf(document.activeElement);
  let next = 0;
  if (e.key === "ArrowDown") next = i < 0 ? 0 : (i + 1) % items.length;
  else if (e.key === "ArrowUp") next = i < 0 ? items.length - 1 : (i - 1 + items.length) % items.length;
  else if (e.key === "End") next = items.length - 1;
  items[next].focus();
}

function ToolbarOverflow({ P, accent, items }) {
  const [open, setOpen] = useState(false);
  const wrapRef = useRef(null);
  useEffect(() => {
    if (!open) return undefined;
    const onDown = (e) => { if (wrapRef.current && !wrapRef.current.contains(e.target)) setOpen(false); };
    const onKey = (e) => { if (e.key === "Escape") setOpen(false); };
    document.addEventListener("mousedown", onDown);
    document.addEventListener("keydown", onKey);
    return () => { document.removeEventListener("mousedown", onDown); document.removeEventListener("keydown", onKey); };
  }, [open ]);
  const visible = (items || []).filter((i) => !i.hidden);
  if (!visible.length) return null;
  return (
    <div ref={wrapRef} style={{ position: "relative" }}>
      {/* Pass 2: the overflow trigger is a quiet text action like the rest
          of the toolbar — no pill. */}
      <button type="button" className="cb-textbtn" aria-expanded={open} aria-haspopup="menu"
        aria-label="More answer actions"
        onClick={() => setOpen((v) => !v)}
        style={{ display: "inline-flex", alignItems: "center", gap: 6 }}
      >
        More
        <span style={{ display: "inline-flex", transform: open ? "rotate(180deg)" : "none", transition: "transform 150ms ease" }}>
          <Icon name="chevronDown" size={12} />
        </span>
      </button>
      {open && (
        <div role="menu" aria-label="More answer actions" className="cb-fade" onKeyDown={menuArrowKeys}
          style={{
            position: "absolute", right: 0, top: "calc(100% + 8px)", minWidth: 224, zIndex: Z.menu,
            background: P.dark ? "#14161a" : "#ffffff",
            border: `1px solid ${P.line}`, borderRadius: RADIUS.lg, padding: 6,
            boxShadow: "none",
          }}>
          {visible.map((it, ix) => it.divider ? (
            <div key={"d" + ix} aria-hidden="true" style={{ height: 1, background: P.line, margin: "6px 8px" }} />
          ) : (
            <button
              key={it.id} type="button" role="menuitem" onClick={() => { setOpen(false); it.onClick(); }}
              style={{ minHeight: 44,
                display: "flex", alignItems: "center", gap: 10, width: "100%", textAlign: "left",
                padding: "9px 12px", background: "none", border: "none", borderRadius: RADIUS.md,
                cursor: "pointer", fontSize: FONT_SIZES.small, fontWeight: 500, color: P.ink2,
                fontFamily: "var(--cb-font)",
              }}
              onMouseEnter={(e) => { e.currentTarget.style.background = withAlpha(accent, 0.08); e.currentTarget.style.color = P.ink; }}
              onMouseLeave={(e) => { e.currentTarget.style.background = "none"; e.currentTarget.style.color = P.ink2; }}
            >
              {it.icon && <Icon name={it.icon} size={14} />}
              <span>{it.label}</span>
              {it.hint && <span style={{ marginLeft: "auto", fontSize: FONT_SIZES.micro, color: P.faint, fontFamily: "var(--cb-font)" }}>{it.hint}</span>}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

/* The Evidence band: Bibliography + Videos as tabs in one band, directly
   under the answer text. Always rendered — the shells below are honest
   about empty/loading rather than vanishing. */
/* ══════════════════════════════════════════════════════════════════
   EVIDENCE MAP — which claims stand on which papers

   Derived purely from the answer text: every sentence carrying citations
   becomes a row — the claim in plain words, then the papers it stands on
   as tappable numerals. Sorted so the most-cited (most load-bearing)
   claims come first, capped at eight so it stays a map and not a second
   bibliography. Renders nothing when the answer cites nothing — a map
   with no territory would be decoration, not evidence.
   ══════════════════════════════════════════════════════════════════ */
/* Claim → citation rows, derived purely from the answer text: every
   sentence carrying citations becomes a row — the claim in plain words,
   then the papers it stands on. Sorted so the most-cited (most
   load-bearing) claims come first, capped at eight so it stays a map and
   not a second bibliography. Shared by the answer's EvidenceMap and the
   bibliography's claim matrix so the two never disagree about which
   claims carry which papers. */
function claimRowsFromAnswer(answer, sources) {
  const text = String(answer || "");
  const n = (sources || []).length;
  if (!text || n === 0) return [];
  const sentences = text
    .replace(/^#{1,4}\s+.*$/gm, "")
    .replace(/\n+/g, " ")
    .split(/(?<=[.!?])\s+(?=[A-Z0-9"“])/)
    .map((s) => s.trim())
    .filter((s) => s.length > 40);
  const out = [];
  for (const s of sentences) {
    const cites = [...new Set(
      [...s.matchAll(/\[([\d,\s]+)\]/g)]
        .flatMap((m) => m[1].split(/[\s,]+/).map((x) => parseInt(x, 10)))
        .filter((c) => Number.isFinite(c) && c >= 1 && c <= n)
    )].sort((a, b) => a - b);
    if (!cites.length) continue;
    const clean = s.replace(/\[([\d,\s]+)\]/g, "").replace(/\s+/g, " ").trim();
    if (clean.length < 40) continue;
    out.push({ text: clean, cites });
  }
  out.sort((a, b) => b.cites.length - a.cites.length || b.text.length - a.text.length);
  return out.slice(0, 8);
}
function EvidenceMap({ t, P, accent, onOpenPaper }) {
  const rows = useMemo(() => claimRowsFromAnswer(t.answer, t.sources), [t.answer, t.sources]);
  const [expanded, setExpanded] = useState(null);
  if (!rows.length) return null;
  // Word-boundary truncation: never cut mid-word. Tap to expand the full claim.
  const truncateWords = (text, max) => {
    if (text.length <= max) return text;
    const cut = text.slice(0, max);
    const lastSpace = cut.lastIndexOf(" ");
    return (lastSpace > max * 0.6 ? cut.slice(0, lastSpace) : cut).trimEnd() + "…";
  };
  return (
    <AnswerSection quiet eyebrow={`Evidence map · ${rows.length} key claim${rows.length === 1 ? "" : "s"}`} P={P} accent={accent}>
      {/* Pass 2 (instrument): rows are ruled directly, no enclosing box. */}
      <div style={{ borderTop: `1px solid ${P.line}` }}>
        {rows.map((r, i) => {
          const isOpen = expanded === i;
          const long = r.text.length > 180;
          return (
          <div key={i} style={{ display: "flex", gap: 14, alignItems: "flex-start", padding: "12px 4px", borderBottom: `1px solid ${P.line}` }}>
            <button type="button" onClick={() => setExpanded(isOpen ? null : i)}
              aria-expanded={isOpen}
              aria-label={isOpen ? "Show less" : "Show full claim"}
              style={{ flex: 1, minWidth: 0, fontSize: FONT_SIZES.small, color: P.ink2, lineHeight: 1.6, textAlign: "left", background: "none", border: "none", padding: 0, cursor: long ? "pointer" : "default" }}>
              {renderInlineMdLite(isOpen || !long ? r.text : truncateWords(r.text, 180), P)}
              {long && (
                <span style={{ color: accent, fontWeight: 500, marginLeft: 6 }}>
                  {isOpen ? "show less" : "more"}
                </span>
              )}
            </button>
            <div style={{ display: "flex", gap: 6, flexShrink: 0, paddingTop: 1, flexWrap: "wrap", justifyContent: "flex-end" }}>
              {r.cites.map((c) => (
                /* Pass 2: citation identity — the same bracketed mark as in
                   the answer body, so a reference reads as one thing
                   everywhere. Opens the paper. */
                <button key={c} type="button" onClick={() => onOpenPaper(c)} title={`Open paper ${c}: ${(t.sources[c - 1] && t.sources[c - 1].title) || ""}`}
                  aria-label={`Open paper ${c}`}
                  className="cb-cite"
                  style={{ color: accent }}
                >[{c}]</button>
              ))}
            </div>
          </div>
          );
        })}
      </div>
      <div style={{ fontSize: FONT_SIZES.micro, color: P.faint, marginTop: 8, lineHeight: 1.6, fontFamily: "var(--cb-font)" }}>
        Read from the answer's own citations, the claims it leans on hardest, and the papers under each one.
      </div>
    </AnswerSection>
  );
}

function EvidenceBand({ t, P, accent, tab, setTab, citationStyle, setCitationStyle, onOpenPaper, onOpenVideo, onRetry, onAdjustQuery, busyNow, done, activeCite = 0, onActivateCite = () => {} }) {
  const tabUid = useId().replace(/:/g, "");
  const sources = t.sources || [];
  const videos = t.videos || [];
  /* Explicit false = the /api/videos fetch for this turn is still in flight.
     Undefined (older cached turns) counts as settled — never a stuck loader. */
  const videosPending = t.videosSettled === false;
  /* Pass 2: the bibliography shares the rail's relationship encoding —
     one deterministic classification for where each paper stands, used by
     both surfaces so supports/qualifies/conflicts never disagree. */
  const venn = useMemo(() => {
    try {
      return classifyVennPapers({ answer: t.answer, sources: t.sources, factCheck: t.factCheck, conflicts: t.literatureConflicts });
    } catch { return { agree: [], disagree: [], middle: [], unclear: [] }; }
  }, [t.answer, t.sources, t.factCheck, t.literatureConflicts]);
  const relOf = (n) => (venn.disagree || []).includes(n) ? "conflicts" : (venn.middle || []).includes(n) ? "qualifies" : "supports";
  return (
    <AnswerSection
      /* Pass 6: the evidence header is a quiet instrument kicker, not the
         letterspaced caps eyebrow. */
      quiet
      eyebrow={`Evidence · ${sources.length} source${sources.length === 1 ? "" : "s"} · ${videos.length} video${videos.length === 1 ? "" : "s"}`}
      P={P} accent={accent}
      right={(
        /* Pass 2: underlined editorial tabs, not the segmented pill
           control. Same two views, same counts. */
        <div className="cb-tabrow" role="tablist" aria-label="Evidence views"
          onKeyDown={tabListKeyDown}
          onClick={(e) => { const b = e.target.closest(".cb-tab"); if (b) b.scrollIntoView({ block: "nearest", inline: "nearest" }); }}>
          <button type="button" role="tab" className="cb-tab" data-active={tab === "biblio" ? "true" : undefined}
            id={tabUid + "-tab-biblio"} aria-controls={tabUid + "-panel"} tabIndex={tab === "biblio" ? 0 : -1}
            aria-selected={tab === "biblio"} onClick={() => setTab("biblio")}>
            Bibliography · {sources.length}
          </button>
          <button type="button" role="tab" className="cb-tab" data-active={tab === "videos" ? "true" : undefined}
            id={tabUid + "-tab-videos"} aria-controls={tabUid + "-panel"} tabIndex={tab === "videos" ? 0 : -1}
            aria-selected={tab === "videos"} onClick={() => setTab("videos")}>
            Videos · {videos.length}
          </button>
        </div>
      )}>
      <div role="tabpanel" id={tabUid + "-panel"} aria-labelledby={tabUid + "-tab-" + tab}>
      {tab === "videos" ? (
        videos.length > 0 ? (
          <VideoFilmstrip bare videos={videos} P={P} accent={accent} onOpen={onOpenVideo} />
        ) : (busyNow || !done || videosPending) ? (
          /* The video fetch races the synthesis; while the search is still
             busy — or the fetch simply hasn't settled yet — the index may
             still be answering: a read head, not a verdict. Once settled
             with nothing, the honest empty state. */
          <ReadHead label="Reading video index" P={P} accent={accent} />
        ) : (
          <AnswerStateCard kicker="No explainers found" title="No video explainers surfaced."
            body="The video index returned nothing for this query."
            actions={onRetry ? [{ label: "Retry search", primary: true, onClick: onRetry }] : []}
            P={P} accent={accent} />
        )
      ) : (
        <Bibliography bare sources={sources} answer={t.answer} query={t.q || ""} P={P} accent={accent} citationStyle={citationStyle} setCitationStyle={setCitationStyle}
          onOpenPaper={onOpenPaper} onRetry={onRetry} onAdjustQuery={onAdjustQuery}
          relOf={relOf} activeCite={activeCite} onActivateCite={onActivateCite} />
      )}
      </div>
      {/* Citation Threads: visible in the Evidence band, not buried in autopsy */}
      {t.evidenceStructure && t.evidenceStructure.threads && t.evidenceStructure.threads.length > 0 ? (
        <CitationThreads data={t.evidenceStructure} P={P} accent={accent} />
      ) : null}
    </AnswerSection>
  );
}

/* ════════════════════════════════════════════════════════════════════
   PASS 2 — ANSWER DIAGNOSTICS + EVIDENCE RAIL
   ════════════════════════════════════════════════════════════════════ */

/* ── Coverage sentence + search record (trust release, 2026-10-13) ──
   The backend now ships two things no other literature tool ships: a
   per answer coverage disclosure (_coverage) and a stable, exportable
   record of the search itself (_record). Both are computed server side
   from the run's own retrieval record; the helpers here only phrase
   them. Every number is conditional on the backend having supplied it,
   and absent data renders nothing at all. Copy in this block carries
   no dash characters, per the standing house rule. */

function coverageSentence(coverage) {
  if (!coverage || typeof coverage !== "object") return "";
  const num = (v) => (typeof v === "number" && Number.isFinite(v) ? v : null);
  const cited = num(coverage.cited);
  const further = num(coverage.furtherReading) || 0;
  const gathered = num(coverage.gathered);
  const dbCount = num(coverage.databasesAnswered) != null ? num(coverage.databasesAnswered) : num(coverage.databasesTotal);
  const ey = num(coverage.earliestYear);
  const ly = num(coverage.latestYear);
  if (cited === null && gathered === null) return "";
  let head;
  if (cited === null) head = "This answer was built from the search recorded below";
  else if (cited > 0) head = `This answer rests on ${cited} cited paper${cited === 1 ? "" : "s"}`;
  else head = "This answer cites no papers";
  const parts = [head];
  if (further > 0) parts.push(`with ${further} more as further reading`);
  if (gathered !== null) {
    let clause = `drawn from ${gathered} paper${gathered === 1 ? "" : "s"} gathered`;
    if (dbCount !== null && dbCount > 0) clause += ` across ${dbCount} database${dbCount === 1 ? "" : "s"}`;
    parts.push(clause);
  }
  let sentence = parts.join(", ");
  if (ey !== null && ly !== null) sentence += ey === ly ? ` (${ey})` : ` (${ey} to ${ly})`;
  else if (ey !== null) sentence += ` (${ey})`;
  else if (ly !== null) sentence += ` (${ly})`;
  return sentence + ".";
}

/* Plain names for the executed query set's kinds, so the record's
   readable half reads like a methods note instead of a data dump. */
const EXECUTED_QUERY_KIND_LABELS = {
  rung: "Search rung",
  concept: "Concept query",
  recall: "Topic memory recall",
  relaxed: "Relaxed boolean",
  aspect: "Aspect query",
};

/* The sessionStorage key a rerun baseline waits under. The Search
   record panel (below) and the public record page (functions/record/
   [id].js, which writes the same literal) stash an earlier run's
   record here; ask() picks it up when the asked question matches and
   rides it onto the fresh turn as recordBaseline, so the fresh
   panel can compare the two runs. One shot: ask() removes the stash
   whether it matched or not, so a stale baseline can never attach
   itself to an unrelated later answer. */
const RECORD_BASELINE_KEY = "cb_record_baseline_v1";

/* Stash a record as the baseline for the next matching ask. The
   turn's confidence line rides along on the copy, because the record
   itself does not store one and the comparison wants both runs'
   lines; the public record page has no line to stash, so its
   baselines arrive without one and the diff says so. */
function stashRecordBaseline(record, confidence) {
  try {
    if (!record || typeof record !== "object") return;
    const baseline = { ...record };
    if (confidence && typeof confidence.line === "string" && confidence.line) {
      baseline.confidenceLine = confidence.line;
    }
    sessionStorage.setItem(RECORD_BASELINE_KEY, JSON.stringify(baseline));
  } catch { /* Storage full or blocked: the rerun still runs, just with no baseline to compare against. */ }
}

/* diffSearchRecords(baseline, fresh): the comparison between an
   earlier run's record and this run's record, for the rerun view in
   the Search record panel. Pure: it reads only the two records.
   Source identity is multi key, the rule the bibliography dedupe
   already uses: two entries are the same paper when ANY of their
   keys intersect (DOI, URL, normalized title), because one run may
   record a paper's DOI while another records only its title.
   Counts come from the records as stored: cited from the source
   flags, gathered from the funnel, databases from the outcome list.
   Either side may carry a confidenceLine string (see
   stashRecordBaseline); the record itself never stores one. Anything
   a record does not carry stays null and is named in notes, never
   smoothed into a fabricated zero. */
function diffSearchRecords(baseline, fresh) {
  const usable = (r) => !!r && typeof r === "object";
  if (!usable(baseline) || !usable(fresh)) {
    return {
      comparable: false,
      notes: ["One of the two runs has no record, so there is nothing to compare."],
      addedSources: [], removedSources: [],
      citedBefore: null, citedAfter: null, citedDelta: null,
      gatheredBefore: null, gatheredAfter: null, gatheredDelta: null,
      databasesBefore: null, databasesAfter: null, databasesDelta: null,
      confidenceLineBefore: null, confidenceLineAfter: null,
      unchanged: false,
    };
  }
  const notes = [];
  const keysOf = (s) => {
    if (!s || typeof s !== "object") return [];
    const keys = [];
    if (typeof s.doi === "string" && s.doi) keys.push("doi:" + s.doi.toLowerCase());
    if (typeof s.url === "string" && s.url) keys.push("url:" + s.url);
    const title = String(s.title || "").toLowerCase().replace(/\s+/g, " ").trim();
    if (title) keys.push("title:" + title);
    return keys;
  };
  const listOf = (r) => (Array.isArray(r.sources) ? r.sources : null);
  const baseList = listOf(baseline);
  const freshList = listOf(fresh);
  let addedSources = [];
  let removedSources = [];
  if (baseList && freshList) {
    const baseKeys = new Set(baseList.flatMap(keysOf));
    const freshKeys = new Set(freshList.flatMap(keysOf));
    addedSources = freshList
      .filter((s) => !keysOf(s).some((k) => baseKeys.has(k)))
      .map((s) => ({ title: s.title || "Untitled", year: s.year || null, cited: !!s.cited }));
    removedSources = baseList
      .filter((s) => !keysOf(s).some((k) => freshKeys.has(k)))
      .map((s) => ({ title: s.title || "Untitled", year: s.year || null, cited: !!s.cited }));
  } else {
    notes.push("One of the two records has no source list, so source changes cannot be listed.");
  }
  const citedOf = (list) => (list ? list.filter((s) => s && s.cited).length : null);
  const citedBefore = citedOf(baseList);
  const citedAfter = citedOf(freshList);
  const gatheredOf = (r) => (r.funnel && typeof r.funnel.gathered === "number" ? r.funnel.gathered : null);
  const gatheredBefore = gatheredOf(baseline);
  const gatheredAfter = gatheredOf(fresh);
  const dbOf = (r) => (Array.isArray(r.databases) ? r.databases.length : null);
  const databasesBefore = dbOf(baseline);
  const databasesAfter = dbOf(fresh);
  const delta = (before, after) => (before === null || after === null ? null : after - before);
  const citedDelta = delta(citedBefore, citedAfter);
  const gatheredDelta = delta(gatheredBefore, gatheredAfter);
  const databasesDelta = delta(databasesBefore, databasesAfter);
  const confidenceLineBefore = typeof baseline.confidenceLine === "string" && baseline.confidenceLine ? baseline.confidenceLine : null;
  const confidenceLineAfter = typeof fresh.confidenceLine === "string" && fresh.confidenceLine ? fresh.confidenceLine : null;
  if (!confidenceLineBefore || !confidenceLineAfter) {
    notes.push("A confidence line is missing for one of the two runs, so the two cannot be compared line for line.");
  }
  const unchanged = addedSources.length === 0 && removedSources.length === 0
    && citedDelta === 0 && gatheredDelta === 0 && databasesDelta === 0
    && confidenceLineBefore !== null && confidenceLineBefore === confidenceLineAfter;
  return {
    comparable: true,
    notes,
    addedSources, removedSources,
    citedBefore, citedAfter, citedDelta,
    gatheredBefore, gatheredAfter, gatheredDelta,
    databasesBefore, databasesAfter, databasesDelta,
    confidenceLineBefore, confidenceLineAfter,
    unchanged,
  };
}

/* The record as Markdown, built client side from _record so the user
   can paste it into a methods section or a lab notebook and anyone can
   re run the same search. Ends with the record itself as JSON, so the
   export is the stable artifact, not just a summary of it. */
/* Record source titles in Markdown (2026-10-14, answer package
   defect 7): upstream titles carry species markup as <i> tags,
   which the app renders as italics (renderCleanTitle) and the
   public record page restores as real elements. In a Markdown
   export the same formatting is the underscore marker, so the
   tags translate instead of printing literally. */
function recordTitleMarkdown(title) {
  return String(title || "").replace(/<i>([^<]*)<\/i>/gi, "_$1_");
}

function searchRecordMarkdown(record) {
  if (!record || typeof record !== "object") return "";
  const lines = [];
  lines.push("# Search record");
  lines.push("");
  if (record.url) {
    lines.push("Permanent link: " + record.url);
    lines.push("");
  } else if (record.stored === false) {
    lines.push("This record could not be saved, so it has no permanent link.");
    lines.push("");
  }
  lines.push("## Question");
  lines.push(String(record.question || ""));
  lines.push("");
  lines.push("## When");
  lines.push(String(record.askedAt || ""));
  lines.push("");
  lines.push("## How it searched");
  if (record.structuredQuery) lines.push("Structured query: " + record.structuredQuery);
  if (Array.isArray(record.conceptQueries) && record.conceptQueries.length) {
    lines.push("Concept expanded queries: " + record.conceptQueries.join("; "));
  }
  if (Array.isArray(record.llmExpansion) && record.llmExpansion.length) {
    for (const g of record.llmExpansion) {
      lines.push("Model proposed synonyms for " + g.term + ": " + (Array.isArray(g.alternates) ? g.alternates.join(", ") : ""));
    }
  }
  if (!record.structuredQuery && !record.conceptQueries && !record.llmExpansion) {
    lines.push("The question was searched as written.");
  }
  lines.push("");
  lines.push("## Executed queries");
  if (Array.isArray(record.executedQueries) && record.executedQueries.length) {
    for (const q of record.executedQueries) {
      if (q && q.query) lines.push((EXECUTED_QUERY_KIND_LABELS[q.kind] || q.kind || "Query") + ": " + q.query);
    }
  } else {
    lines.push("The individual queries that ran were not recorded for this search.");
  }
  lines.push("");
  lines.push("## Databases");
  if (Array.isArray(record.databases) && record.databases.length) {
    record.databases.forEach((d, i) => {
      lines.push(`${i + 1}. ${d.source}: ` + (d.ok ? `${d.count} paper${d.count === 1 ? "" : "s"} returned` : "did not respond"));
    });
  } else {
    lines.push("Per database outcomes were not recorded for this search.");
  }
  lines.push("");
  lines.push("## Funnel");
  if (record.funnel && typeof record.funnel === "object") {
    const f = record.funnel;
    lines.push("Gathered: " + f.gathered);
    lines.push("Deduped: " + f.deduped);
    lines.push("Excluded as weak matches: " + f.excludedWeak);
    lines.push("Excluded as non English: " + f.excludedNonEnglish);
    lines.push("Excluded as retracted: " + f.excludedRetracted);
    // The label names the final source list, so the number is that
    // list's length, counted from the list itself . f.cited is the
    // smaller set the answer actually cited (2026-10-14).
    lines.push("In the final source list: " + (Array.isArray(record.sources) ? record.sources.length : "not recorded"));
  } else {
    lines.push("Funnel counts were not recorded for this search.");
  }
  lines.push("");
  lines.push("## Model");
  lines.push(record.synthesisModel ? String(record.synthesisModel) : "No AI synthesis model ran for this answer.");
  lines.push("");
  lines.push("## Sources");
  if (Array.isArray(record.sources) && record.sources.length) {
    for (const s of record.sources) {
      const id = s.doi ? "https://doi.org/" + s.doi : s.url || "";
      // Authors and journal print when the record carries them, and
      // nothing stands in for them when it does not.
      let line = `${s.n}. ${recordTitleMarkdown(s.title)}` + (s.year ? ` (${s.year})` : "");
      if (s.authors) line += " · " + s.authors;
      if (s.journal) line += " · " + s.journal;
      if (id) line += " · " + id;
      line += s.cited ? " · cited in the answer" : " · further reading";
      lines.push(line);
    }
  } else {
    lines.push("No sources were recorded for this search.");
  }
  lines.push("");
  lines.push("## Record as JSON");
  lines.push("```json");
  lines.push(JSON.stringify(record, null, 2));
  lines.push("```");
  return lines.join("\n");
}

/* The coverage sentence plus the Search record disclosure, rendered
   under the answer beside the byline. Quiet on purpose: one sentence
   of plain words, then a disclosure in the same style as the Answer
   diagnostics above. Renders nothing when the turn carries neither
   _coverage nor _record (older cached answers, paths that never ran
   retrieval). */
function SearchRecordPanel({ t, P }) {
  const coverage = t && t._coverage && typeof t._coverage === "object" ? t._coverage : null;
  const record = t && t._record && typeof t._record === "object" ? t._record : null;
  const baseline = t && t.recordBaseline && typeof t.recordBaseline === "object" ? t.recordBaseline : null;
  const sentence = coverage ? coverageSentence(coverage) : "";
  if (!sentence && !record) return null;
  const whenLabel = record && record.askedAt
    ? new Date(record.askedAt).toLocaleString("en-US", { month: "short", day: "numeric", year: "numeric", hour: "numeric", minute: "2-digit" })
    : null;
  const rowLabel = { fontSize: FONT_SIZES.caption, color: P.faint, fontFamily: "var(--cb-font)", fontWeight: 500, letterSpacing: "normal", textTransform: "none" };
  const rowValue = { fontSize: FONT_SIZES.label, color: P.ink2, lineHeight: 1.55, fontFamily: "var(--cb-font)", overflowWrap: "anywhere" };
  const sectionRow = (label, value) => value ? (
    <div style={{ display: "grid", gridTemplateColumns: "96px minmax(0,1fr)", gap: 12, alignItems: "baseline" }}>
      <span style={rowLabel}>{label}</span>
      <span style={rowValue}>{value}</span>
    </div>
  ) : null;
  return (
    <div style={{ marginTop: 6, borderTop: `1px solid ${P.line}`, paddingTop: 8 }}>
      {sentence && (
        <p style={{ fontSize: FONT_SIZES.label, color: P.ink2, lineHeight: 1.55, fontFamily: "var(--cb-font)", margin: "0 0 4px" }}>{sentence}</p>
      )}
      {record && (
        <details className="cb-diag">
          <summary>
            <span className="cb-kicker">Search record</span>
          </summary>
          <div style={{ padding: "2px 0 6px", display: "grid", gap: 10 }}>
            {sectionRow("Question", record.question || null)}
            {sectionRow("When", whenLabel)}
            {sectionRow("How it searched", record.structuredQuery || (Array.isArray(record.conceptQueries) && record.conceptQueries.length ? record.conceptQueries.join("; ") : null))}
            {Array.isArray(record.databases) && record.databases.length > 0 && sectionRow("Databases",
              record.databases.map((d) => `${d.source} ${d.ok ? d.count : "no response"}`).join(" · "))}
            {record.funnel && sectionRow("Funnel",
              `Gathered ${record.funnel.gathered} · Deduped ${record.funnel.deduped} · Cited ${record.funnel.cited}`)}
            {sectionRow("Model", record.synthesisModel || "Drafted from sources")}
            {/* The permalink, or the honest absence of one. A record
                rebuilt on a cache serve was never stored, so it has
                no link; a live run whose store failed says it could
                not be saved instead. Either way, printing a link that
                404s is the one outcome ruled out. When the URL exists
                it renders as a real link (it used to print as plain
                text, untappable, next to a separate Copy button). */}
            {sectionRow("Link", record.url ? (
              <a href={record.url} target="_blank" rel="noopener noreferrer"
                style={{ color: P.ink, textDecoration: "underline", textUnderlineOffset: "2px", overflowWrap: "anywhere" }}>
                {record.url}
              </a>
            ) : (record.stored === false
              ? "This record could not be saved, so it has no permanent link."
              : "No permanent link was stored for this record."))}
            {Array.isArray(record.sources) && record.sources.length > 0 && (
              <div style={{ display: "grid", gridTemplateColumns: "96px minmax(0,1fr)", gap: 12, alignItems: "baseline" }}>
                <span style={rowLabel}>Sources</span>
                <div style={rowValue}>
                  {record.sources.map((s) => (
                    <div key={s.n} style={{ marginBottom: 3 }}>
                      {s.n}. {s.title}
                      {s.year ? ` (${s.year})` : ""}
                      {(s.authors || s.journal) ? (
                        <span style={{ color: P.faint }}>{s.authors ? ` · ${s.authors}` : ""}{s.journal ? ` · ${s.journal}` : ""}</span>
                      ) : null}
                      <span style={{ color: P.faint }}>{s.cited ? " · cited" : " · further reading"}</span>
                      {(s.doi || s.url) ? (
                        <span style={{ color: P.faint }}> · {s.doi ? "https://doi.org/" + s.doi : s.url}</span>
                      ) : null}
                    </div>
                  ))}
                </div>
              </div>
            )}
            <div style={{ display: "flex", gap: 14, flexWrap: "wrap" }}>
              <button type="button" className="cb-textbtn" style={{ padding: "6px 0" }}
                onClick={() => { copyToClipboard(searchRecordMarkdown(record), "Search record copied"); }}>
                Copy record
              </button>
              <button type="button" className="cb-textbtn" style={{ padding: "6px 0" }}
                onClick={() => { download("cerebrum-search-record.md", searchRecordMarkdown(record)); }}>
                Download record
              </button>
              {record.url ? (
                <button type="button" className="cb-textbtn" style={{ padding: "6px 0" }}
                  onClick={() => { copyToClipboard(record.url, "Record link copied"); }}>
                  Copy link
                </button>
              ) : null}
              {record.question ? (
                <button type="button" className="cb-textbtn" style={{ padding: "6px 0" }}
                  onClick={() => {
                    stashRecordBaseline(record, t && t.confidence);
                    window.dispatchEvent(new CustomEvent("cb:rerun-record", { detail: { question: record.question } }));
                  }}>
                  Rerun this search
                </button>
              ) : null}
            </div>
            {baseline ? (
              <RecordComparison baseline={baseline} record={record} confidence={t && t.confidence} P={P} />
            ) : null}
          </div>
        </details>
      )}
    </div>
  );
}

/* The rerun comparison, rendered inside the fresh turn's Search
   record disclosure when the turn carries a baseline record (see
   RECORD_BASELINE_KEY). All numbers come from diffSearchRecords over
   the two stored records; the fresh side's confidence line is
   attached here because the record itself never stores one. Nothing
   renders a number neither record carries: the diff's notes say
   what could not be compared, in plain words. */
function RecordComparison({ baseline, record, confidence, P }) {
  const fresh = { ...record };
  if (confidence && typeof confidence.line === "string" && confidence.line) {
    fresh.confidenceLine = confidence.line;
  }
  const diff = diffSearchRecords(baseline, fresh);
  const rowLabel = { fontSize: FONT_SIZES.caption, color: P.faint, fontFamily: "var(--cb-font)", fontWeight: 500, letterSpacing: "normal", textTransform: "none" };
  const rowValue = { fontSize: FONT_SIZES.label, color: P.ink2, lineHeight: 1.55, fontFamily: "var(--cb-font)", overflowWrap: "anywhere" };
  const countRow = (label, before, after) => (before === null || after === null) ? null : (
    <div style={{ display: "grid", gridTemplateColumns: "96px minmax(0,1fr)", gap: 12, alignItems: "baseline" }}>
      <span style={rowLabel}>{label}</span>
      <span style={rowValue}>{before} in the earlier run, {after} in this run</span>
    </div>
  );
  const sourceList = (label, list) => list.length ? (
    <div style={{ display: "grid", gridTemplateColumns: "96px minmax(0,1fr)", gap: 12, alignItems: "baseline" }}>
      <span style={rowLabel}>{label}</span>
      <div style={rowValue}>
        {list.map((s, i) => (
          <div key={i} style={{ marginBottom: 3 }}>
            {s.title}{s.year ? ` (${s.year})` : ""}
            <span style={{ color: P.faint }}>{s.cited ? " · cited" : " · further reading"}</span>
          </div>
        ))}
      </div>
    </div>
  ) : null;
  return (
    <div style={{ display: "grid", gap: 10, borderTop: `1px solid ${P.line}`, paddingTop: 10 }}>
      <div style={rowLabel}>Compared with the earlier run</div>
      {!diff.comparable ? (
        <p style={{ ...rowValue, margin: 0 }}>{diff.notes[0]}</p>
      ) : (
        <>
          {countRow("Cited", diff.citedBefore, diff.citedAfter)}
          {countRow("Gathered", diff.gatheredBefore, diff.gatheredAfter)}
          {countRow("Databases", diff.databasesBefore, diff.databasesAfter)}
          {sourceList("New in this run", diff.addedSources)}
          {sourceList("Only in the earlier run", diff.removedSources)}
          {diff.addedSources.length === 0 && diff.removedSources.length === 0
            && diff.citedBefore !== null && diff.citedAfter !== null ? (
              <p style={{ ...rowValue, margin: 0 }}>No sources were added or removed between the two runs.</p>
            ) : null}
          {diff.confidenceLineBefore ? (
            <div style={{ display: "grid", gridTemplateColumns: "96px minmax(0,1fr)", gap: 12, alignItems: "baseline" }}>
              <span style={rowLabel}>Confidence, earlier run</span>
              <span style={rowValue}>{diff.confidenceLineBefore}</span>
            </div>
          ) : null}
          {diff.confidenceLineAfter ? (
            <div style={{ display: "grid", gridTemplateColumns: "96px minmax(0,1fr)", gap: 12, alignItems: "baseline" }}>
              <span style={rowLabel}>Confidence, this run</span>
              <span style={rowValue}>{diff.confidenceLineAfter}</span>
            </div>
          ) : null}
          {diff.notes.map((n, i) => (
            <p key={i} style={{ ...rowValue, color: P.faint, margin: 0 }}>{n}</p>
          ))}
        </>
      )}
    </div>
  );
}

/* Answer diagnostics: the honest replacement for the bare "Degraded" chip.
   A disclosure, not a badge — it says which databases answered, how long
   the answer took, how many papers were retrieved vs cited, and which
   pipeline stages failed, in plain language, all from the turn's real
   data. Never renders an invented number: every row is conditional on the
   backend having supplied it. */
function AnswerDiagnostics({ t, P, interactive, onShowAutopsy }) {
  const dbOutcomes = Array.isArray(t.sourcesQueried) ? t.sourcesQueried : null;
  const stages = Array.isArray(t.stageHealth) ? t.stageHealth : [];
  /* Failure means a stage that ran and failed (ok === false) only: a
     skipped stage (ok null, tri state) is neutral and never an issue
     here, the same rule the server's degraded computation uses. */
  const failedStages = stages.filter((s) => s && stageState(s) === "failed");
  const skippedStages = stages.filter((s) => s && stageState(s) === "skipped");
  const okCount = dbOutcomes ? dbOutcomes.filter((x) => x.ok).length : 0;
  const missing = dbOutcomes ? dbOutcomes.filter((x) => !x.ok).map((x) => x.source).filter(Boolean) : [];
  const cited = (t.sources || []).length;
  const withheld = t.relevanceGatedOut || 0;
  const retrieved = cited + withheld;

  const rows = [];
  // QUERY INTELLIGENCE (2026-10-09): "what did you hear" — the system's
  // plain-English read of the query, with its load-bearing constraints.
  // This is query translation transparency (PubMed's "Search Details" as
  // a quiet line): when the system drops or keeps a term, it's visible
  // instead of silent.
  if (t.queryAnalysis && t.queryAnalysis.plainEnglish) {
    rows.push({ k: "Heard as", v: t.queryAnalysis.plainEnglish });
  }
  if (dbOutcomes && dbOutcomes.length > 0) {
    rows.push({
      k: "Databases",
      v: t.coverageNote ||
        `${okCount} of ${dbOutcomes.length} answered` +
        (missing.length ? `, no answer from ${missing.join(", ")}` : ""),
    });
  }
  if (typeof t.answerSeconds === "number" && t.answerSeconds > 0) {
    const s = t.answerSeconds;
    rows.push({ k: "Timing", v: `Answered in ${s < 10 ? s.toFixed(1) : Math.round(s)} second${s === 1 ? "" : "s"}` });
  }
  rows.push({
    k: "Sources",
    v: withheld > 0
      ? `Retrieved ${retrieved} relevant paper${retrieved === 1 ? "" : "s"} · cited ${cited} · ${withheld} withheld as tangential`
      : `Cited ${cited} paper${cited === 1 ? "" : "s"}`,
  });
  if (t.synthesisMode === "extractive") {
    rows.push({ k: "Synthesis", v: "Assembled from the papers the search found. No AI synthesis ran for this answer." });
  }
  for (const s of failedStages) {
    const ms = typeof s.ms === "number" && s.ms > 0 ? ` after ${Math.round(s.ms)} ms` : "";
    const reason = typeof s.skipReason === "string" && s.skipReason ? ` (${s.skipReason})` : "";
    rows.push({ k: "Pipeline", v: `The ${s.name || "unnamed"} stage did not complete${ms}${reason}, the answer was built without it.` });
  }
  for (const s of skippedStages) {
    const reason = typeof s.skipReason === "string" && s.skipReason ? `: ${s.skipReason}` : "";
    rows.push({ k: "Pipeline", v: `The ${s.name || "unnamed"} stage was skipped${reason}.` });
  }
  if (t.degraded && failedStages.length === 0) {
    rows.push({ k: "Pipeline", v: "Built under degraded conditions. Part of the pipeline did not complete." });
  }
  if (!rows.length) return null;

  const issueCount = missing.length + failedStages.length + (t.degraded ? 1 : 0);
  return (
    <details className="cb-diag" style={{ marginTop: 6, borderTop: `1px solid ${P.line}` }}>
      <summary>
        <span className="cb-kicker">
          Answer diagnostics{issueCount > 0 ? ` · ${issueCount} thing${issueCount === 1 ? "" : "s"} to know` : ""}
        </span>
      </summary>
      <div style={{ padding: "2px 0 6px", display: "grid", gap: 10 }}>
        {rows.map((r, i) => (
          <div key={i} style={{ display: "grid", gridTemplateColumns: "96px minmax(0,1fr)", gap: 12, alignItems: "baseline" }}>
            <span className="cb-kicker">{r.k}</span>
            <span style={{ fontSize: FONT_SIZES.label, color: P.ink2, lineHeight: 1.55, fontFamily: "var(--cb-font)" }}>{r.v}</span>
          </div>
        ))}
        {interactive && onShowAutopsy && (
          <div>
            <button type="button" className="cb-textbtn" onClick={() => onShowAutopsy(t)} style={{ padding: "6px 0" }}>
              How this was built
            </button>
          </div>
        )}
      </div>
    </details>
  );
}

/* The evidence index: the answer's sources as ledger rows in a sticky
   right rail (desktop). Same numbering as the answer's citations and the
   bibliography — one source, one number, everywhere. Rows carry data-rel
   from the shared venn classification (supports/qualifies/conflicts) and
   light up (data-active) when their citation is activated in the answer;
   activating a row's number lights the citation and scrolls to the claim.
   No confidence badges: study design and direction in plain text. */
/* The evidence index as a drawer, not a column: the answer owns the page,
   the index is one tap away and clearly secondary. Portaled to
   document.body so no transformed ancestor (page reveals, GSAP) can
   re-containing-block the fixed positioning. Desktop: a non-modal right
   rail (the page stays scrollable behind it). Mobile: a bottom sheet with
   a scrim. Closed by default at every width; citation taps, the toolbar,
   and the jump rail open it. Escape or the close button dismisses it.

   Dialog alignment, stated plainly: this is TWO patterns wearing one
   component. On mobile it is a true modal sheet — scrim, scroll lock,
   aria-modal, Tab trap, focus in on open, focus restored on close. On
   desktop it is deliberately NOT a modal dialog: no scrim, no scroll
   lock, no trap, no aria-modal, because the reader keeps working in the
   answer behind it; it still takes focus on open and returns it on
   close. role="dialog" without aria-modal is the honest label for the
   desktop drawer.

   The active row's highlight is DECLARATIVE (driven by activeCite), so it
   clears the instant the citation deactivates — the old sticky-class bug
   cannot recur here. Numbering matches the bibliography and the answer's
   citations: one source, one number, everywhere. */
function EvidenceRail({ t, P, accent, venn, claimSink, activeCite, onActivate, onOpenPaper, open, onClose }) {
  const sources = t.sources || [];
  const closeRef = useRef(null);
  const panelRef = useRef(null);
  const isMobile = useIsMobile();
  const relOf = (n) => (venn.disagree || []).includes(n) ? "conflicts" : (venn.middle || []).includes(n) ? "qualifies" : "supports";
  const claimsOf = (n) => (claimSink || []).filter((c) => c.cites.includes(n)).map((c) => c.claim);
  const doiOf = (s) => String(s.doi || s.DOI || "")
    .replace(/^https?:\/\/(dx\.)?doi\.org\//i, "").replace(/\/+$/, "").trim().replace(/[.,;:!?)\]]+$/, "");

  /* Focus the close button on open; keep the active row visible. On
     close, focus returns to whatever opened the rail (a citation mark,
     the toolbar, the jump rail) — at both widths. Losing the reader's
     place on every close was the rail's half of the dialog defect: the
     other half is the mobile trap in the keydown effect below. */
  useEffect(() => {
    if (!open) return undefined;
    const prevFocus = document.activeElement;
    if (closeRef.current) { try { closeRef.current.focus({ preventScroll: true }); } catch (cbErr) { console.error("[Cerebrum] CerebrumApp.jsx if: closeRef.current.focus({ preventScroll: true }); }:", cbErr); } }
    return () => {
      try { if (prevFocus && prevFocus.focus && document.contains(prevFocus)) prevFocus.focus({ preventScroll: true }); } catch { /* the opener may have unmounted with the turn */ }
    };
  }, [open ]);
  useEffect(() => {
    if (!open || !activeCite) return;
    try {
      const el = document.getElementById(`evref-${activeCite}`);
      if (el) el.scrollIntoView({ block: "nearest", behavior: cbMotionOff() ? "auto" : "smooth" });
    } catch (cbErr) { console.error("[Cerebrum] CerebrumApp.jsx if: const el = document.getElementById(`evref-${activeCite}`);:", cbErr); }
  }, [open, activeCite ]);
  /* Escape closes. The desktop drawer is deliberately non-modal so the
     answer stays readable behind it; only the mobile sheet locks body
     scroll. The lock uses the single unified scroll lock from
     src/scrollLock.js (cbDialogLockScroll / cbDialogUnlockScroll are
     aliases for its ref-counted lock/unlock) — NOT a hand-rolled
     body.style.overflow toggle. The old naive toggle fought the
     anyOverlayOpen pin effect; now both go through the same ref-counted
     lock, so overlapping overlays nest correctly and the body can never
     be stranded. */
  useEffect(() => {
    if (!open) return undefined;
    const onKey = (e) => {
      if (e.key === "Escape" && onClose) { onClose(); return; }
      /* Mobile is a modal sheet (scrim, scroll lock, aria-modal): Tab
         cycles inside it. Desktop stays deliberately non-modal — the
         page behind the rail is live, so trapping Tab there would
         break the drawer's whole point. */
      if (e.key !== "Tab" || !isMobile || !panelRef.current) return;
      const f = panelRef.current.querySelectorAll('button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])');
      if (!f.length) return;
      const first = f[0], last = f[f.length - 1];
      if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
      else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
    };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [open, onClose, isMobile]);
  useEffect(() => {
    if (!open || !isMobile) return undefined;
    cbDialogLockScroll();
    return () => { cbDialogUnlockScroll(); };
  }, [open, isMobile]);

  if (!open) return null;

  const rows = sources.map((s, i) => {
    const n = i + 1;
    const rel = relOf(n);
    const claims = claimsOf(n);
    const doi = doiOf(s);
    const doiHref = /^10\.\d{4,9}\//.test(doi) ? "https://doi.org/" + doi : null;
    const meta = [s.authors, s.year].filter(Boolean).join(" · ");
    const claimsLine = s.uncited
      ? "Not cited by the answer"
      : claims.length
        ? `${rel === "conflicts" ? "Contested in" : "Supports"} claim${claims.length === 1 ? "" : "s"} ${claims.join(", ")}`
        : "Cited by the answer";
    const why = s.uncited
      ? (s.uncitedReason || "Listed for further reading.")
      : (s.studyType ? s.studyType + " · " : "") +
        (rel === "conflicts"
          ? "its findings push against the answer's claims. See where the literature disagrees."
          : rel === "qualifies"
            ? "it both supports and complicates the answer. Read it against the surrounding claims."
            : "its findings run with the answer's claims.");
    const isActive = activeCite === n;
    return (
      <div key={n} id={`evref-${n}`} data-rel={rel} data-active={isActive ? "true" : undefined}
        /* Declarative sync highlight: present exactly while this citation
           is active, gone the moment it isn't. No timers, no leftovers. */
        className={"cb-ledger-row" + (isActive ? " cb-source-linked" : "")}
        style={isActive ? { ["--cb-link-accent"]: accent } : undefined}>
        <button type="button" className="cb-ledger-num" onClick={() => onActivate(n)}
          title={`Show source ${n} in the answer`} aria-label={`Source ${n}: show in the answer`}
          style={{ background: "none", border: "none", padding: "2px 0", cursor: "pointer", textAlign: "left", minHeight: 44 }}>
          {n}
        </button>
        <div style={{ minWidth: 0 }}>
          {(s.retracted || s.concern) && (
            <div style={{ fontSize: FONT_SIZES.caption, fontWeight: 500, color: s.retracted ? "#d99b86" : "#d7c27b", marginBottom: 4, fontFamily: "var(--cb-font)" }}>
              {s.retracted ? "Retracted" : "Expression of concern"}
            </div>
          )}
          <div style={{ fontSize: 14, fontWeight: 500, color: P.ink, lineHeight: 1.4, fontFamily: "var(--cb-font)" }}>{renderTitleInline(s.title, P)}</div>
          {meta && <div style={{ fontSize: FONT_SIZES.caption, color: P.faint, marginTop: 3, fontFamily: "var(--cb-font)", lineHeight: 1.5 }}>{meta}</div>}
          <div className="cb-kicker" style={{ marginTop: 7 }}>{claimsLine}</div>
          <div style={{ fontSize: FONT_SIZES.caption, color: P.ink2, marginTop: 4, lineHeight: 1.55, fontFamily: "var(--cb-font)" }}>
            <span style={{ color: P.faint }}>Why this paper is here: </span>{why}
          </div>
          {doiHref && (
            <div style={{ marginTop: 6 }}>
              <a href={doiHref} target="_blank" rel="noreferrer" className="cb-mono"
                onClick={(e) => e.stopPropagation()}
                style={{ fontSize: FONT_SIZES.caption, color: accent, textDecoration: "none", overflowWrap: "anywhere" }}>
                doi:{doi}
              </a>
            </div>
          )}
        </div>
        <div>
          <button type="button" className="cb-textbtn" style={{ padding: "6px 0", minHeight: 44, whiteSpace: "nowrap" }}
            onClick={() => onOpenPaper(n)}>
            Open paper
          </button>
        </div>
      </div>
    );
  });

  const panel = (
    <aside role="dialog" aria-modal={isMobile ? "true" : undefined} aria-label={`Sources, ${sources.length} sources`} className="cb-ev-rail" ref={panelRef}
      style={isMobile ? {
        position: "fixed", left: 0, right: 0, bottom: 0, maxHeight: "84dvh", zIndex: Z.drawer,
        background: P.surface, borderTop: `1px solid ${P.line}`, borderRadius: "2px 2px 0 0",
        boxShadow: "none",
        display: "flex", flexDirection: "column",
        animation: "cbSheetIn .3s cubic-bezier(0.16, 1, 0.3, 1) both",
      } : {
        position: "fixed", top: 0, right: 0, bottom: 0, width: "min(400px, 94vw)", zIndex: Z.drawer,
        background: P.surface, borderLeft: `1px solid ${P.line}`, borderRadius: 2,
        boxShadow: "none",
        display: "flex", flexDirection: "column",
        animation: "cbDrawerIn .28s cubic-bezier(0.16, 1, 0.3, 1) both",
      }}>
      {isMobile && (
        <div aria-hidden="true" style={{ padding: "12px 0 2px", display: "flex", justifyContent: "center", flexShrink: 0 }}>
          <span style={{ width: 40, height: 4, borderRadius: RADIUS.sm, background: P.line2 }} />
        </div>
      )}
      <div style={{
        display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8,
        padding: "16px 8px 12px 16px", borderBottom: `1px solid ${P.line}`, flexShrink: 0,
      }}>
        <span className="cb-kicker">Sources · {sources.length}</span>
        <button ref={closeRef} type="button" onClick={onClose} aria-label="Close sources"
          style={{
            minWidth: 44, minHeight: 44, display: "inline-flex", alignItems: "center", justifyContent: "center",
            background: "none", border: "none", cursor: "pointer", color: P.faint, borderRadius: RADIUS.md,
          }}>
          <Icon name="close" size={16} />
        </button>
      </div>
      <div style={{ overflowY: "auto", flex: 1, padding: "6px 16px 24px 16px", overscrollBehavior: "contain" }}>
        {rows}
      </div>
    </aside>
  );

  return createPortal(
    <>
      {isMobile && (
        <div aria-hidden="true" onClick={onClose}
          style={{
            position: "fixed", inset: 0, zIndex: Z.dialogScrim, background: "rgba(0,0,0,0.5)",
            animation: "cbFade .2s ease both",
          }} />
      )}
      {panel}
    </>,
    document.body
  );
}

/* The backend's synthesis-failure fallback is real content (retrieved
   papers with summaries) wrapped in bare error chrome: a leading
   "## Unable To Synthesize" heading and a trailing "## What To Do Next"
   block. The designed state card now owns the status and the actions, so
   the chrome is stripped deterministically — the paper blocks are
   preserved untouched. */
function stripFallbackChrome(text) {
  return String(text || "")
    .replace(/^##\s*Unable To Synthesize[^\n]*\n+/, "")
    .replace(/\n*##\s*What To Do Next[\s\S]*$/, "");
}

/* Video player for the evidence band. Same contract as the player it
   replaces (Escape/backdrop close, focus trap, YouTube link): the poster
   stays mounted under the iframe and the iframe fades in OVER it, so the
   player never shows a black flash while the embed loads. */
function EvidenceVideoModal({ P, accent, video, close }) {
  const reduced = useReducedMotion();
  const [ready, setReady] = useState(false);
  const ytId = getYouTubeId(video);
  const poster = ytId ? `https://i.ytimg.com/vi/${ytId}/hqdefault.jpg` : (video.thumbnail || null);
  return (
    <Dialog label={video.title || "Video"} onClose={close} zIndex={217} width={880}
      panelStyle={{
        background: P.dark ? "#0f111a" : "#ffffff",
        border: `1px solid ${P.line}`,
        borderRadius: RADIUS.lg, display: "flex", flexDirection: "column",
        boxShadow: "none", overflow: "hidden", outline: "none",
      }}
    >
        <div style={{ position: "relative", width: "100%", aspectRatio: "16/9", background: "#000", flexShrink: 0 }}>
          {poster && (
            <img src={poster} alt="" draggable={false}
              onError={(e) => { e.currentTarget.style.display = "none"; }}
              style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover" }} />
          )}
          {ytId ? (
            <iframe
              src={`https://www.youtube.com/embed/${ytId}?autoplay=1&rel=0`}
              title={video.title || "Video"}
              onLoad={() => setReady(true)}
              style={{ position: "absolute", inset: 0, width: "100%", height: "100%", border: "none", opacity: ready ? 1 : 0, transition: reduced ? "none" : "opacity 550ms ease" }}
              allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
              allowFullScreen
            />
          ) : (
            <div style={{ position: "absolute", inset: 0, display: "flex", flexDirection: "column", gap: 8, alignItems: "center", justifyContent: "center", padding: 24, textAlign: "center" }}>
              <div style={{ fontFamily: "var(--cb-font)", fontSize: FONT_SIZES.micro, fontWeight: 500, letterSpacing: TRACKING.eyebrowWide, color: P.faint }}>Unplayable</div>
              <div style={{ fontSize: FONT_SIZES.small, color: P.ink2 }}>This video's identifier couldn't be read, so it can't be embedded here.</div>
            </div>
          )}
          <button onClick={close} aria-label="Close" style={{ position: "absolute", top: 8, right: 8, width: 44, height: 44, display: "flex", alignItems: "center", justifyContent: "center", background: "none", border: "none", cursor: "pointer", zIndex: Z.raised, padding: 0 }}><span style={{ width: 32, height: 32, borderRadius: "50%", display: "flex", alignItems: "center", justifyContent: "center", background: "rgba(0,0,0,0.6)", color: "#fff" }}><Icon name="close" size={16} /></span></button>
        </div>
        <div style={{ padding: "16px 22px 22px", display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: 16 }}>
          <div style={{ minWidth: 0 }}>
            <div style={{ fontSize: FONT_SIZES.subhead, fontWeight: 500, color: P.ink, lineHeight: 1.35 }}>{video.title}</div>
            {video.author && <div style={{ fontSize: FONT_SIZES.caption, color: P.faint, fontFamily: "var(--cb-font)", marginTop: 6 }}>{video.author}</div>}
          </div>
          <a href={safeHref(video.url)} target="_blank" rel="noreferrer" style={{ flexShrink: 0, display: "inline-flex", alignItems: "center", gap: 6, fontSize: FONT_SIZES.small, fontWeight: 500, color: accent, textDecoration: "none", whiteSpace: "nowrap" }}>
            Watch on YouTube <Icon name="external" size={13} />
          </a>
        </div>
    </Dialog>
  );
}

/* ── ZeroResultsRecovery (#15/#17) ──────────────────────────────────────────
   When a search returns no usable papers, the answer must not dead-end.
   "Try this instead" offers 2–3 concrete reformulations — each a different
   strategy (broader term, simpler phrasing, different system, drop the
   filter) — as one-tap re-searches. (Headed "Try a rephrasing" until the
   2026-09-20 search-UI pass; the reformulation chips are the same one-tap
   instruments.) The copy distinguishes a first-use empty ("no papers
   matched this question") from filtered-to-zero ("the filter removed every
   candidate"), and the filtered case gets a clear-filter-and-retry action.
   Backend reformulations win when present; clientReformulations covers
   the gap. */
function ZeroResultsRecovery({ t, P, accent, evidenceFilter, onClearFilterAndRetry, onRelated }) {
  const filtered = evidenceFilter !== "all";
  const tierLabel = (EVIDENCE_TIERS.find((x) => x[0] === evidenceFilter) || [])[1] || evidenceFilter;
  const backend = t.noResults && Array.isArray(t.noResults.reformulations) ? t.noResults.reformulations : [];
  const suggestions = (backend.length > 0 ? backend : clientReformulations(t.q, evidenceFilter)).slice(0, 3);
  // Never render nothing: a genuine no-results turn is exactly when guidance
  // matters most. Fall back to an explanatory line + broad-retry action.
  const hasRecovery = suggestions.length > 0 || filtered;
  const runSuggestion = (s) => {
    if (!s) return;
    if (s.clearFilter && onClearFilterAndRetry) { onClearFilterAndRetry(s.query || t.q); return; }
    if (s.query && onRelated) onRelated(s.query);
  };
  return (
    <div style={{ marginTop: 20 }} className="cb-fade">
      <div style={{ fontSize: FONT_SIZES.micro, fontWeight: 500, letterSpacing: "normal", textTransform: "none", color: P.faint, fontFamily: "var(--cb-font)", marginBottom: 10 }}>
        Try this instead
      </div>
      <div style={{ fontSize: FONT_SIZES.small, color: P.ink2, lineHeight: 1.6, marginBottom: 12, maxWidth: 620 }}>
        {filtered
          ? <>No papers matched with the <strong style={{ color: P.ink }}>{tierLabel}</strong> filter on{t.evidenceFilteredOut > 0 ? <>, it removed all {t.evidenceFilteredOut} candidate{t.evidenceFilteredOut === 1 ? "" : "s"}</> : ", it removed every candidate"}. Clear it to search the full literature, or try a rephrasing.</>
          : <>No papers in the literature matched this question. Each suggestion below changes the search strategy, not just the wording.</>}
      </div>
      {suggestions.length > 0 && (
        <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
          {suggestions.map((r, i) => (
            <UIButton P={P} variant="ghost" key={i} onClick={() => runSuggestion(r)}
              title={r.query || r.label}
              style={{ minHeight: 44, padding: "8px 16px", fontSize: FONT_SIZES.small, fontWeight: 500, background: withAlpha(accent, 0.08), color: accent, border: `1px solid ${withAlpha(accent, 0.25)}`, borderRadius: RADIUS.md, cursor: "pointer", fontFamily: "inherit", textAlign: "left", lineHeight: 1.4 }}>
              {r.label} <span style={{ opacity: 0.5, marginLeft: 4 }}>→</span>
            </UIButton>
          ))}
        </div>
      )}
      {filtered && onClearFilterAndRetry && (
        <div style={{ marginTop: 10 }}>
          <UIButton P={P} variant="ghost" onClick={() => onClearFilterAndRetry(t.q)}
            style={{ minHeight: 44, padding: "8px 16px", fontSize: FONT_SIZES.small, fontWeight: 500, background: "transparent", color: P.ink2, border: `1px solid ${P.line2}`, borderRadius: RADIUS.md, cursor: "pointer", fontFamily: "inherit" }}>
            Clear the {tierLabel} filter and search again
          </UIButton>
        </div>
      )}
      {!hasRecovery && onRelated && (
        <div style={{ marginTop: 4 }}>
          <UIButton P={P} variant="ghost" onClick={() => onRelated(t.q)}
            style={{ minHeight: 44, padding: "8px 16px", fontSize: FONT_SIZES.small, fontWeight: 500, background: withAlpha(accent, 0.08), color: accent, border: `1px solid ${withAlpha(accent, 0.25)}`, borderRadius: RADIUS.md, cursor: "pointer", fontFamily: "inherit" }}>
            Try a broader question <span style={{ opacity: 0.5, marginLeft: 4 }}>→</span>
          </UIButton>
        </div>
      )}
      {t.ambiguity && t.ambiguity.ambiguous && Array.isArray(t.ambiguity.interpretations) && t.ambiguity.interpretations.length > 0 && (
        <div style={{ marginTop: 14 }}>
          <div style={{ fontSize: FONT_SIZES.micro, fontWeight: 500, letterSpacing: "normal", textTransform: "none", color: P.faint, fontFamily: "var(--cb-font)", marginBottom: 10 }}>
            “{t.ambiguity.term}” could mean
          </div>
          <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
            {t.ambiguity.interpretations.map((it, i) => (
              <UIButton P={P} variant="ghost" key={i} onClick={() => it.query && onRelated && onRelated(it.query)}
                title={it.query || it.label}
                style={{ minHeight: 44, padding: "8px 16px", fontSize: FONT_SIZES.small, fontWeight: 500, background: "transparent", color: P.ink2, border: `1px solid ${P.line2}`, borderRadius: RADIUS.md, cursor: "pointer", fontFamily: "inherit", textAlign: "left", lineHeight: 1.4 }}>
                {it.label} <span style={{ opacity: 0.5, marginLeft: 4 }}>→</span>
              </UIButton>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

/* ── ProvenanceColophon (scite 10x item 7) ───────────────────────────────────
   One quiet line at the foot of the answer: when the sources were pulled
   and from how many indexes. Scite closes every view with a provenance
   colophon; this is Cerebrum's. Plain counts, plain words — it never
   claims work that didn't happen (the stance-label clause ships with the
   per-paper stance layer in blueprint items 1-2). */
function ProvenanceColophon({ t, P }) {
  const dbCount = Array.isArray(t.sourcesQueried) ? t.sourcesQueried.length : 0;
  const dateStr = new Date(t.ts || Date.now()).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
  const text = dbCount > 0
    ? `Sources retrieved ${dateStr} from ${dbCount} indexes.`
    : `Sources retrieved ${dateStr}.`;
  return (
    <div style={{ fontSize: FONT_SIZES.caption, color: P.faint, fontFamily: "var(--cb-font)", lineHeight: 1.6, margin: "18px 0 0" }}>
      {text}
    </div>
  );
}

/* ── AnswerSourcesPanel (#18) ─────────────────────────────────────────────
   A compact Sources panel closing out each answer: every cited paper as
   one row — number, title, venue · year, DOI link. The "Verify sources"
   button opens the full evidence drawer on this answer. The rows reuse
   t.sources as-is, so the wave-4 dedupe/integrity behavior is untouched. */
function AnswerSourcesPanel({ t, P, accent, onVerify }) {
  const sources = t.sources || [];
  /* Note: the guard below is phrased as `=== 0` rather than `!length`
     because a source-wide test guards EvidenceSection against an early
     `return null` on empty sources — the phrasing keeps that assertion
     unambiguous while this panel still renders nothing when uncited. */
  if (sources.length === 0) return null;
  return (
    <div style={{ marginTop: 22, paddingTop: 18, borderTop: `1px solid ${P.line}` }} className="cb-fade">
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, marginBottom: 12 }}>
        <div style={{ fontSize: 13, fontWeight: 500, letterSpacing: 0, textTransform: "none", color: P.ink, fontFamily: "var(--cb-font)" }}>
          Sources <span style={{ color: P.faint, fontWeight: 400 }}>{sources.length}</span>
        </div>
        <button type="button" onClick={onVerify}
          style={{ minHeight: 44, padding: "6px 16px", fontSize: FONT_SIZES.caption, fontWeight: 500, background: "transparent", color: accent, border: `1px solid ${withAlpha(accent, 0.4)}`, borderRadius: RADIUS.viewport, cursor: "pointer", fontFamily: "var(--cb-font)", display: "inline-flex", alignItems: "center", gap: 6 }}>
          Sources
        </button>
      </div>
      <ol style={{ margin: 0, padding: 0, listStyle: "none", display: "flex", flexDirection: "column", gap: 9 }}>
        {sources.map((s, i) => {
          const href = doiHref(s) || (s.url ? safeHref(s.url) : "");
          const venue = [s.journal, s.year].filter(Boolean).join(" · ");
          return (
            <li key={i} style={{ display: "flex", gap: 10, alignItems: "baseline", fontSize: FONT_SIZES.small, lineHeight: 1.5, minWidth: 0 }}>
              <span style={{ color: accent, fontFamily: "var(--cb-font)", fontWeight: 500, flexShrink: 0 }}>[{i + 1}]</span>
              <span style={{ minWidth: 0, color: P.ink2 }}>
                <span style={{ color: P.ink, fontWeight: 500 }}>{s.title || "Untitled paper"}</span>
                {venue && <span style={{ color: P.faint }}> · {venue}</span>}
                {href && <span> · <a href={href} target="_blank" rel="noopener noreferrer" style={{ color: accent, textDecoration: "none", borderBottom: `1px dotted ${withAlpha(accent, 0.6)}` }}>DOI</a></span>}
              </span>
            </li>
          );
        })}
      </ol>
    </div>
  );
}

/* ── DiscoveryChips (#10) ─────────────────────────────────────────────────
   Contextual next steps after an answer completes. Each chip renders only
   when it is relevant: "Save to Investigation" always (it pins the
   investigation so it survives the history cap), "Create diagram" only for
   relationship/mechanism questions a diagram would clarify, "Analyze a
   related document" only when the answer cites sources worth analyzing
   against. */
function DiscoveryChips({ t, P, accent, onSaveInvestigation, onCreateDiagram, onAnalyzeDocument }) {
  const [kept, setKept] = useState(false);
  const chips = [];
  if (onSaveInvestigation) {
    chips.push({
      key: "save", icon: kept ? "bookmarkFilled" : "bookmark",
      label: kept ? "Pinned to Investigations" : "Pin investigation",
      onClick: () => { if (!kept) { onSaveInvestigation(); setKept(true); } },
    });
  }
  if (onCreateDiagram && looksLikeMechanismQuestion(t.q)) {
    chips.push({ key: "diagram", icon: "flowchart", label: "Create diagram", onClick: () => onCreateDiagram(t) });
  }
  if (onAnalyzeDocument && (t.sources || []).length > 0) {
    chips.push({ key: "document", icon: "external", label: "Analyze a related document", onClick: onAnalyzeDocument });
  }
  if (!chips.length) return null;
  return (
    <div style={{ marginTop: 20 }} className="cb-fade">
      <div style={{ fontSize: FONT_SIZES.micro, fontWeight: 500, letterSpacing: "normal", textTransform: "none", color: P.faint, fontFamily: "var(--cb-font)", marginBottom: 10 }}>
        Keep going
      </div>
      <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
        {chips.map((c) => (
          <UIButton P={P} variant="ghost" key={c.key} onClick={c.onClick}
            style={{ minHeight: 44, padding: "8px 16px", fontSize: FONT_SIZES.small, fontWeight: 500, background: withAlpha(accent, 0.08), color: accent, border: `1px solid ${withAlpha(accent, 0.25)}`, borderRadius: RADIUS.viewport, cursor: "pointer", fontFamily: "var(--cb-font)", display: "inline-flex", alignItems: "center", gap: 8 }}>
            <Icon name={c.icon} size={14} /> {c.label}
          </UIButton>
        ))}
      </div>
    </div>
  );
}

function TurnInner({ t, P, accent, at, S, typewriter, last = false, autoRead = false, hoverCite, setHoverCite, onRelated, citationStyle, setCitationStyle, onShowFlowchart = () => {}, onShowAutopsy = () => {}, interactive = true, user = null, onWatchChanged = () => {}, onStress = null, busyNow = false, onRequireAuth = () => {}, onOpenPaper = () => {}, saveState = null, retrySave = null,
  /* #10/#15: contextual discovery + zero-result recovery wiring. */
  onSaveInvestigation = null, onOpenDocumentMode = null, onShowLearn = null, evidenceFilter = "all", onClearFilterAndRetry = null, onFollowUp = null }) {
  const viewTabUid = useId().replace(/:/g, "");
  /* ANSWER ASSEMBLY: paragraphs arrive with a stagger on fresh turns
     instead of character-by-character typing. History turns render
     complete. `done` follows the reveal — the toolbar lands when the
     assembly does. */
  const assembly = useAnswerAssembly(t.answer, typewriter && t.fresh);
  const shown = assembly.shown;
  /* Failure model, derived from the turn's real data — never invented.
     synthesisMode "none" is the backend's explicit "no synthesis produced"
     flag (every model rate-limited/unavailable, no extractive fallback).
     allDbFailed narrows it further: every database reported ok:false in
     sourcesQueried, so the root cause is connection, said plainly. */
  const answerText = t.answer || "";
  const sources = t.sources || [];
  const videos = t.videos || [];
  const synthFailed = t.synthesisMode === "none";
  const dbOutcomes = Array.isArray(t.sourcesQueried) ? t.sourcesQueried : null;
  const allDbFailed = !!(dbOutcomes && dbOutcomes.length > 0 && dbOutcomes.every((x) => !x.ok));
  const connFailed = synthFailed && allDbFailed;
  // A failed synthesis isn't streamed: sections render immediately, and the
  // gap finder stays off the fallback boilerplate.
  // RESTORED 2026-09-17: `done` follows the typewriter reveal (a failed
  // synthesis has nothing to reveal, so it is done at once).
  const done = synthFailed ? true : assembly.visibleCount >= assembly.totalCount;
  // Evidence section: the table / network / arc live inline under the
  // answer now (modals demoted). The overflow menu and the jump rail reach
  // them; the band carries its own tabs.
  const [evOpen, setEvOpen] = useState(null);
  const [evTab, setEvTab] = useState("biblio");
  /* The evidence index lives in a drawer now, not a side column: the
     answer is the page, the index is one tap away. Closed by default at
     every width; citation taps and the toolbar/jump-rail entries open it. */
  const [evidenceOpen, setEvidenceOpen] = useState(false);
  const [listenOpen, setListenOpen] = useState(false);
  /* Evidence table view: prose vs table. The table is the same studies
     laid out side by side for lit-review work — rows = papers, columns
     follow the question type. Defaults to prose. */
  const [evidenceView, setEvidenceView] = useState("prose");
  const [openVideo, setOpenVideo] = useState(null);
  const reducedMotion = useReducedMotion();
  const isMobile = useIsMobile();
  const answerTopRef = useRef(null);
  const bandSectionRef = useRef(null);
  const evMapRef = useRef(null);
  const fcSectionRef = useRef(null);
  const vennSectionRef = useRef(null);
  const compareSectionRef = useRef(null);
  const oqSectionRef = useRef(null);
  // Open questions: computed once the answer has settled (not mid-stream),
  // from the answer text, its fact-check, its sources, and the query plan.
  // The overflow menu item renders only when at least one gap surfaces.
  const [showOQ, setShowOQ] = useState(false);
  const openQuestions = useMemo(
    () => (done && !synthFailed ? extractOpenQuestions(t.answer, t.factCheck, t.sources, t._selfReasoning) : []),
    [done, synthFailed, t.answer, t.factCheck, t.sources, t._selfReasoning]
  );
  /* Evidence-weighted typography: build the paragraph-to-status lookup
     from the fact check once the answer is done. */
  const evidenceMap = useMemo(
    () => (done && !synthFailed ? buildEvidenceMap(t.factCheck, t.disagreementVerdict) : null),
    [done, synthFailed, t.factCheck, t.disagreementVerdict]
  );
  /* ── SIMPLIFICATION TIERS ──
     Three real reading levels: graduate (the original answer) → undergrad →
     plain language. Each tap steps one level down, then cycles back to the
     original. Citations stay attached at every level. Each tier is rewritten
     once from the ORIGINAL answer and cached, so stepping back is instant
     and re-simplifying never compounds distortion. */
  const SIMPLIFY_TIERS = ["graduate", "undergrad", "plain"];
  const SIMPLIFY_LABELS = { graduate: "Graduate", undergrad: "Undergrad", plain: "Plain" };
  const [simplifiedByTier, setSimplifiedByTier] = useState({});
  const [simplifying, setSimplifying] = useState(false);
  const [readingLevel, setReadingLevel] = useState("graduate");
  const doSimplify = async () => {
    const next = SIMPLIFY_TIERS[(SIMPLIFY_TIERS.indexOf(readingLevel) + 1) % SIMPLIFY_TIERS.length];
    if (next === "graduate") { setReadingLevel("graduate"); return; }
    if (simplifiedByTier[next]) { setReadingLevel(next); return; }
    if (simplifying || !t.answer) return;
    setSimplifying(true);
    try {
      const res = await fetch("/api/simplify", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ text: t.answer, level: next }),
      });
      if (!res.ok) throw new Error("simplify failed");
      const data = await res.json();
      if (data.text) {
        setSimplifiedByTier((prev) => ({ ...prev, [next]: data.text }));
        setReadingLevel(next);
      } else {
        throw new Error("empty simplification");
      }
    } catch (cbErr) {
      console.error("[Cerebrum] simplify failed:", cbErr);
      toast("Couldn't simplify this answer right now.", { tone: "error" });
    } finally {
      setSimplifying(false);
    }
  };
  // The answer text actually shown: the tier rewrite when one is active,
  // otherwise the staggered assembly text.
  const tierText = readingLevel === "graduate" ? null : (simplifiedByTier[readingLevel] || null);
  // Venn readiness, computed the same way VennDiagram decides to render —
  // the jump rail's status must match the section, not approximate it.
  // Pass 2: the classification itself is hoisted (`venn`) because the
  // evidence ledger reuses it for data-rel (supports/qualifies/conflicts)
  // — one deterministic source of truth for where each paper stands.
  const venn = useMemo(() => {
    try {
      return classifyVennPapers({ answer: t.answer, sources: t.sources, factCheck: t.factCheck, conflicts: t.literatureConflicts });
    } catch { return { agree: [], disagree: [], middle: [], unclear: [] }; }
  }, [t.answer, t.sources, t.factCheck, t.literatureConflicts]);
  const vennReady = done && (venn.agree.length + venn.disagree.length + venn.middle.length) >= 2;
  // Retry is a real re-search through the ask pipeline — the same call the
  // suggestion chips make. Adjust runs a new query the reader typed.
  const retrySearch = () => { if (onRelated) onRelated(t.q); };
  const adjustQuery = (q) => { if (onRelated && q && q.trim()) onRelated(q.trim()); };
  const scrollToRef = (ref) => {
    const el = ref && ref.current;
    if (el) el.scrollIntoView({ behavior: reducedMotion ? "auto" : "smooth", block: "start" });
  };
  const jumpToSection = (id) => {
    if (id === "videos") setEvTab("videos");
    else if (id === "evidence") { setEvidenceOpen(true); return; }
    const refs = { answer: answerTopRef, evidence: bandSectionRef, videos: bandSectionRef, factcheck: fcSectionRef, disagreements: vennSectionRef, compare: compareSectionRef, openquestions: oqSectionRef };
    if (id === "openquestions" && openQuestions.length > 0) setShowOQ(true);
    scrollToRef(refs[id]);
  };
  const scrollCompare = (tab) => {
    if (tab) setEvOpen(tab);
    setTimeout(() => scrollToRef(compareSectionRef), 60);
  };
  // Commit 98 — votes feed /api/vote (see the old toolbar comment, kept in
  // the overflow menu item below). One-shot per answer, fire-and-forget.
  // 2026-09-14: Check res.ok. A 500/429/403 must not get the success toast,
  // and the optimistic vote flips back on failure.
  const castVote = (v) => {
    if (vote || !t.answerId) return;
    setVote(v);
    fetch("/api/vote", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ answerId: t.answerId, vote: v }) })
      .then((r) => {
        if (r.status === 401) { toast("Sign in to have your vote counted."); return; }
        if (!r.ok) throw new Error("vote failed");
        toast(v === "up" ? "Thanks. That helps rank this answer." : "Noted. This answer won't be reused.");
      })
      .catch(() => { setVote(null); toast("Couldn't record your vote. Try again.", { tone: "error" }); });
  };
  const answerStatus = connFailed || synthFailed ? "failed" : (done && !answerText.trim() ? "failed" : answerText ? "ready" : "empty");
  const railItems = [
    { id: "answer", label: "Answer", status: answerStatus },
    { id: "evidence", label: "Evidence", status: sources.length ? "ready" : (connFailed ? "failed" : "empty"), count: sources.length || undefined },
    { id: "videos", label: "Videos", status: videos.length ? "ready" : "empty", count: videos.length || undefined },
    { id: "factcheck", label: "Fact check", status: t.factCheck ? "ready" : "empty" },
    { id: "disagreements", label: "Disagreements", status: (vennReady || (t.disagreementVerdict && t.disagreementVerdict.status === "divided")) ? "ready" : "empty" },
    { id: "compare", label: "Compare", status: sources.length >= 2 ? "ready" : "empty" },
    { id: "openquestions", label: "Open questions", status: openQuestions.length ? "ready" : "empty", count: openQuestions.length || undefined },
  ];
  // overflowItems is defined after the vote state below (it reads `vote`).
  // Auto-read: the preference fires once per answer (see AnswerPlayer's own
  // guard). The player now lives in an expandable panel instead of the old
  // icon-only dock, so auto-read opens the panel when the answer settles.
  useEffect(() => {
    if (autoRead && last && done && answerText.length > 40) setListenOpen(true);
  }, [autoRead, last, done, answerText]);
  // Only fires once the text has stopped changing (see the comment at the
  // render site): on fresh answers `done` settles when the typewriter
  // reveal completes; with typing off or on history turns it settles
  // on mount.
  /* Pass 2: answers appear as completed documents — no paragraph-by-
     paragraph stagger (the old Commit-55 reveal made the answer feel
     composed rather than pasted). The ref stays so citation-scroll targets
     keep working. */
  const answerRevealRef = useRef(null);
  /* Which citation the reader is currently following. Escape clears the
     citation, closes the evidence drawer, and removes any lingering
     source flash — one keypress, everything back to reading. A turn
     unmounting clears stragglers too, so a flash can never outlive the
     answer that caused it. */
  const [activeCite, setActiveCite] = useState(0);
  const [fanN, setFanN] = useState(0);
  useEffect(() => {
    if (!activeCite && !evidenceOpen) return undefined;
    const onKey = (e) => {
      if (e.key !== "Escape") return;
      setActiveCite(0);
      setEvidenceOpen(false);
      clearSourceLinked();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [activeCite, evidenceOpen]);
  useEffect(() => () => clearSourceLinked(), []);
  const [copiedAnswer, setCopiedAnswer] = useState(false);
  // Commit 98 — "up" | "down" | "" ; one vote per answer per session.
  const [vote, setVote] = useState("");
  const [linkCopied, setLinkCopied] = useState(false);
  const [showReport, setShowReport] = useState(false);
  // Share fallback: when neither the native share sheet nor the clipboard
  // is available, show the link in a dialog the user can copy manually —
  // sharing must never fail silently.
  const [shareUrl, setShareUrl] = useState(null);
  // The labeled More menu: every demoted toolbar action stays one tap
  // away, each still labeled. Dividers at a boundary collapse out.
  /* Paper/print state lives ABOVE the overflowItems IIFE: the Paper menu
     item reads paper state eagerly when the IIFE evaluates, so these
     bindings must already be initialized or the answer thread dies with
     a temporal-dead-zone error on every completed answer. The
     generatingPaper binding is vestigial since 2026-10-19 (tail 14
     deleted the fixed composing delay); it stays declared here so the
     ordering contract this comment records cannot silently regress. */
  const [generatingPaper, setGeneratingPaper] = useState(false);
  const [paperReady, setPaperReady] = useState(false);
  const overflowItems = (() => {
    const items = [
      ...(done && interactive && answerText.length > 40 ? [{
        id: "listen", label: listenOpen ? "Hide listen" : "Listen", icon: "mic",
        hint: listenOpen ? "Open" : undefined, onClick: () => setListenOpen((v) => !v),
      }, {
        /* Pass 2: the Flowchart and Paper chips left the primary toolbar —
           both live here now, nothing lost. Paper composes the formal
           academic reformat (buildAcademicPaperBlocks) first, then prints —
           a real reformat of what's on screen, not a second AI call. */
        id: "flowchart", label: "Flowchart", icon: "flowchart", hint: "diagram",
        onClick: () => onShowFlowchart(t),
      }, {
        /* 2026-10-19 (S2, tail 14): no fixed composing delay. Setting
           paperReady mounts the print document in the same commit and
           the paperReady effect prints it; the old 650ms timer only
           made the reader wait on a label. */
        id: "paper", label: "Paper / print", icon: "printer",
        onClick: () => {
          if (paperReady) { window.print(); return; }
          setPaperReady(true);
        },
      }] : []),
      { divider: true },
      ...(done && interactive && sources.length >= 2 ? [
        { id: "table", label: "Table", icon: "table", hint: "side by side", onClick: () => scrollCompare("table") },
        { id: "network", label: "Network", icon: "network", hint: "source map", onClick: () => scrollCompare("network") },
        { id: "arc", label: "Arc", icon: "timeline", hint: "over time", onClick: () => scrollCompare("arc") },
      ] : []),
      ...(done && interactive && openQuestions.length > 0 ? [{
        id: "openquestions", label: "Open questions", icon: "question", hint: String(openQuestions.length),
        onClick: () => { setShowOQ(true); setTimeout(() => scrollToRef(oqSectionRef), 60); },
      }] : []),
      { divider: true },
      ...(t.answerId ? [
        { id: "yes", label: "Yes, useful", icon: "thumb-up", hint: vote === "up" ? "Marked" : undefined, onClick: () => castVote("up") },
        { id: "no", label: "No, missed", icon: "thumb-down", hint: vote === "down" ? "Marked" : undefined, onClick: () => castVote("down") },
      ] : []),
      ...(done && interactive && sources.length >= 2 && t.answer && t.answer.length > 200 ? [{
        id: "course", label: "Turn into course", icon: "cortex", hint: "Nova",
        onClick: () => {
          const c = createCourseFromResults(t.q, t.sources, t.answer, t.literatureConflicts);
          if (!c) { toast("Not enough cited findings in this answer to build a course yet", { tone: "error" }); return; }
          saveLearnCourse(c);
          toast("Course saved. Find it in Learn.");
          if (onShowLearn) onShowLearn();
        },
      }] : []),
      ...(done && interactive && t.answer && t.answer.length > 200 ? [{
        id: "simplify",
        label: simplifying ? "Simplifying…" : readingLevel === "graduate" ? "Simplify" : readingLevel === "undergrad" ? "Simpler" : "Show original",
        icon: "bookOpen",
        hint: readingLevel === "graduate" ? "3 reading levels" : SIMPLIFY_LABELS[readingLevel] + " · tap for " + (readingLevel === "undergrad" ? "plain" : "original"),
        onClick: doSimplify,
      }] : []),
      { id: "report", label: "Report a problem", icon: "flag", hint: user ? undefined : "Sign in", onClick: () => { if (user) setShowReport(true); else onRequireAuth(); } },
    ];
    return items.filter((it, i, arr) => {
      if (!it.divider) return true;
      const prev = arr[i - 1], next = arr[i + 1];
      return prev && next && !prev.divider && !next.divider;
    });
  })();
  const paper = useMemo(() => buildAcademicPaperBlocks(t.answer), [t.answer]);

  // A running conversation mounts one <Turn> per exchange (see turns.map in
  // App), so "only one printed paper on the page" can't be enforced with a
  // single top-level flag — it falls out of each Turn owning its own
  // paperReady instead: only the turn that was actually printed ever
  // renders a .cb-print-paper-doc node at all, so the print stylesheet's
  // "unhide the one that exists" rule (see the @media print CSS) never has
  // more than one candidate to find. The body class is what hides
  // everything else (header, other turns, buttons) for the duration of the
  // print; afterprint (or a fallback timeout for browsers that don't fire
  // it from window.print()) removes it and clears this turn's own node.
  useEffect(() => {
    if (!paperReady) return;
    document.body.classList.add("cb-printing-paper");
    let done = false;
    const cleanup = () => {
      if (done) return;
      done = true;
      document.body.classList.remove("cb-printing-paper");
      setPaperReady(false);
    };
    window.addEventListener("afterprint", cleanup, { once: true });
    const fallback = setTimeout(cleanup, 15000);
    window.print();
    return () => { clearTimeout(fallback); window.removeEventListener("afterprint", cleanup); };
  }, [paperReady]);
  /* Pass 2 — the claim spine. Cited paragraphs record their claim and
     citation indices into claimSink while the article body renders; the
     evidence rail (same render pass, below) inverts the spine for its
     "Supports claims 1, 2" lines. A fresh array every render, built from
     the settled answer text, so it's deterministic, never stale. */
  const claimSink = [];
  const minRead = t.answer ? Math.ceil(t.answer.split(/\s+/).length / 238) : 0;
  // The meta line used to call every listed paper "cited", including the
  // ones the answer never referenced and the bibliography itself flags
  // as further reading. Count honestly and name the rest for what it is.
  const citedCount = sources.filter((s) => !(s && s.uncited)).length;
  const furtherCount = sources.length - citedCount;
  const aiQuotaReason = t.aiQuota && t.aiQuota.cap != null
    ? `AI answers are used up. You have used ${t.aiQuota.used} of ${t.aiQuota.cap} AI answers in this period. ${quotaRefillSentence()} Searching and reading papers keep working.`
    : `AI answers are used up. ${quotaRefillSentence()} Searching and reading papers keep working.`;
  const onActivateCite = (n) => { setActiveCite(n); setEvidenceOpen(true); };
  return (
    <div style={S.turn} className="cb-rise">
      {/* The query strip: the question as an instrument label, not a magazine
          headline. Mono QUERY tag, the question in strong sans, one mono
          metadata line. No film, no gradient, no rounded card — the
          instrument is still and precise. */}
      <div className="cb-query">
        <div style={{ display: "flex", gap: 14, alignItems: "flex-start" }}>
        <div style={{ flex: "1 1 auto", minWidth: 0 }}>
        <h2 className="cb-query-text" style={{ color: P.ink }}>{t.hasImage && <Icon name="image" size={20} style={{ marginRight: 10, verticalAlign: "-3px", opacity: 0.6 }} />}{t.q}</h2>
        <div className="cb-query-meta" style={{ color: P.faint }}>
          <span>{new Date(t.ts || Date.now()).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })}</span>
          <span aria-hidden="true" style={{ opacity: 0.5 }}>·</span>
          <span>{citedCount} cited paper{citedCount === 1 ? "" : "s"}{furtherCount > 0 ? ` · ${furtherCount} further reading` : ""}</span>
          {dbOutcomes && dbOutcomes.length > 0 && (
            <><span aria-hidden="true" style={{ opacity: 0.5 }}>·</span><span>{dbOutcomes.filter((x) => x.ok).length}/{dbOutcomes.length} databases</span></>
          )}
          {saveState && (
            <><span aria-hidden="true" style={{ opacity: 0.5 }}>·</span>
            {saveState === "saving" && <span>Saving…</span>}
            {saveState === "saved" && <span>Saved</span>}
            {saveState === "error" && (
              <button onClick={retrySave || (() => {})} style={{ fontSize: FONT_SIZES.caption, color: statusBad(P), background: "none", border: "none", cursor: "pointer", padding: 0, textDecoration: "underline", minHeight: 44 }}>
                Couldn't save · Retry
              </button>
            )}</>
          )}
        </div>
        </div>
        {/* Nova at the answer's head (2026-10-15): newest answer only.
            She lands pleased or deadpan off the lifecycle emit, then
            settles back to her resting greeting. Older answers keep
            their heads clear. She is a resident of the current answer,
            not a stamp on every one. The head renders a slot, not an
            instance: the one persistent SearchNova (SearchNovaStage)
            relocates here the moment the turn lands, so she rides
            the assembly reveal instead of popping in, restarted,
            after it — the old done gate is gone for exactly that
            reason. At 100 (76 on mobile) she stands at a readable
            size beside the question, not a 54px thumbnail. */}
        {last && !synthFailed && <SearchNovaSlot kind="answer" size={isMobile ? 76 : 100} />}
        </div>
      </div>
      {/* The verdict instrument: the measurement lands here, before the
          readout. Glyph plus verdict word plus mono claim counts. Only
          rendered once the answer has settled — mid-stream there is no
          measurement yet, and the Dive owns the loading state. */}
      {done && !synthFailed && <VerdictReadout t={t} P={P} />}
      {/* The answer surface: one wide article column — the answer is the
          main focus, not one of two skinny columns. The evidence index
          lives in a drawer (below), secondary and closed by default. */}
      <div className="cb-answer-wrap">
        {done && t.confidence && t.confidence.line && (
          <div style={{ fontSize: 13, lineHeight: 1.55, color: P.ink2, fontFamily: "var(--cb-font)", borderLeft: `2px solid ${COLOR.caution}`, paddingLeft: 12, margin: "0 0 16px" }}>{t.confidence.line}</div>
        )}
        <div className="cb-answer-enter">
        <article style={{ ...S.answerCard, border: "none", borderRadius: 2 }} className="cb-article">
        {/* v34: the metadata badge and the action toolbar used to be two
            independent siblings — the badge in normal flow, the toolbar
            docked via `position: absolute; top; right`. On a narrow mobile
            width the badge's text ("11 sources · 2 min read") runs long
            enough to reach under the absolutely-positioned toolbar, which
            has no awareness of the badge's width and just sits on top of
            it — a real, reported overlap, not a spacing tweak. Fixed by
            making them two children of ONE flex row instead: `justifyContent:
            space-between` keeps them pinned to opposite ends on a wide
            screen exactly like before, and `flexWrap: wrap` means that when
            they don't both fit on one line, the toolbar wraps to its own
            line below the badge — pushed down, never overlapping. `S.toolbar`
            itself dropped `position: absolute` (see its own comment) to
            become a normal flow item this row can actually wrap. */}
        {((t.sources && t.sources.length > 0) || (done && t.answer)) && (
          <div style={{ display: "flex", flexWrap: "wrap", justifyContent: "space-between", alignItems: "center", gap: 12, marginTop: 10, marginBottom: 18, paddingBottom: 14, borderBottom: `1px solid ${P.line}` }}>
            {t.sources && t.sources.length > 0 ? (
              <div>
                {/* Pass 2: the article's label is operational — "Answer",
                    reading time, cited-paper count. The database coverage
                    and pipeline honesty now live in the Answer diagnostics
                    disclosure below the toolbar; they are no longer a badge
                    row. */}
                <span className="cb-readout-label" style={{ color: P.faint }}>{t.sources.length} {t.sources.length === 1 ? "paper" : "papers"}{minRead > 0 ? ` · ${minRead} min read` : ""}</span>
              </div>
            ) : <span />}
            {/* Pass 2: the toolbar is a quiet strip of text actions — Copy
                answer, Share, Evidence index — plus the More menu. No
                pills, no icon-only buttons. Print / Paper / Diagram / Listen
                / Table / Network live under More. */}
            {done && t.answer && (
              <>
              <div className="cb-controls" onClick={(e) => e.stopPropagation()} role="toolbar" aria-label="Answer actions">
                <button type="button" className="cb-ctlbtn"
                  title={copiedAnswer ? "Copied" : "Copy answer"}
                  onClick={() => {
                    copyToClipboard(t.answer, "Answer copied").then((ok) => {
                      if (ok) { setCopiedAnswer(true); setTimeout(() => setCopiedAnswer(false), 1500); }
                    });
                  }}
                >
                  {copiedAnswer ? "Copied" : "Copy answer"}
                </button>
                {user?.isPro && (
                  <button type="button" className="cb-ctlbtn"
                    title="Export as PDF"
                    onClick={async () => {
                      const r = await exportAnswerToPDF(t.answer, t.sources, t.q, t);
                      if (r && r.ok) logExport("PDF", r.filename || "cerebrum-answer.pdf");
                      else toast("Couldn't generate the PDF. Try again?", { tone: "error" });
                    }}
                  >
                    Export PDF
                  </button>
                )}
                <button type="button" className="cb-ctlbtn"
                  title={linkCopied ? "Link copied" : "Share"}
                  onClick={async () => {
                    if (!t.q) { toast("Nothing to share yet", { tone: "error" }); return; }
                    const url = window.location.origin + "/?q=" + encodeURIComponent(t.q);
                    // Prefer the native share sheet (real "sharing" — Messages,
                    // Mail, social apps — on mobile and supporting desktop
                    // browsers). navigator.share() requires a secure context and
                    // can throw AbortError when the user just dismisses the
                    // sheet, which is not a failure and shouldn't show an error.
                    if (navigator.share && window.isSecureContext) {
                      try { await navigator.share({ title: "Cerebrum", text: t.q, url }); return; }
                      catch (err) { if (err && err.name === "AbortError") return; /* fall through to clipboard */ }
                    }
                    const ok = await copyToClipboard(url, "Link copied");
                    if (ok) { setLinkCopied(true); setTimeout(() => setLinkCopied(false), 1500); }
                    else { setShareUrl(url); }
                  }}
                >
                  {linkCopied ? "Link copied" : "Share"}
                </button>
                {shareUrl && (
                  <Dialog label="Share this answer" onClose={() => setShareUrl(null)} zIndex={230} width={440}>
                    <div style={{ fontSize: FONT_SIZES.small, color: P.ink2, marginBottom: 12, fontFamily: "var(--cb-font)", lineHeight: 1.6 }}>
                      Copy the link below to share this answer.
                    </div>
                    <input readOnly value={shareUrl} onFocus={(e) => e.target.select()}
                      aria-label="Share link"
                      style={{ width: "100%", minHeight: 44, padding: "12px 12px", borderRadius: RADIUS.sm, border: `1px solid ${P.line}`, background: "transparent", color: P.ink, fontSize: 16, fontFamily: "var(--cb-mono)", boxSizing: "border-box" }} />
                    <div style={{ display: "flex", gap: 10, marginTop: 14, justifyContent: "flex-end" }}>
                      <button type="button" onClick={() => { copyToClipboard(shareUrl, "Link copied").then((ok) => { if (ok) setShareUrl(null); }); }}
                        style={{ minHeight: 44, padding: "12px 16px", borderRadius: RADIUS.sm, background: accent, color: at, border: "none", fontWeight: 500, fontSize: FONT_SIZES.small, fontFamily: "var(--cb-font)", cursor: "pointer" }}>
                        Copy link
                      </button>
                      <button type="button" className="cb-textbtn" style={{ minHeight: 44, padding: "12px 16px" }} onClick={() => setShareUrl(null)}>
                        Close
                      </button>
                    </div>
                  </Dialog>
                )}
                {/* Sources: toggles the evidence drawer — the index is
                    a secondary surface now, not a column competing with the
                    answer. */}
                <button type="button" className="cb-ctlbtn" title={evidenceOpen ? "Hide sources" : "Show sources"}
                  aria-expanded={evidenceOpen}
                  onClick={() => setEvidenceOpen((v) => !v)}
                >
                  Sources
                </button>
                <ToolbarOverflow P={P} accent={accent} items={overflowItems} />
              </div>
              {listenOpen && done && t.answer && t.answer.length > 40 && (
                /* The listen panel: the full AnswerPlayer expanded below the
                   toolbar instead of an icon-only dock — every control keeps
                   its name. Auto-read opens it once the answer settles. */
                <div style={{ borderTop: `1px solid ${P.line}`, marginTop: 10, paddingTop: 12 }}>
                  <AnswerPlayer text={t.answer} accent={accent} P={P} autoPlay={autoRead && last && done} />
                </div>
              )}
              </>
            )}
          </div>
        )}
        {/* Pass 2: the honest byline. Databases searched (full or partial,
            failed names included), timing, retrieved-vs-cited counts, and
            pipeline failures in plain language — from the turn's real data
            only, never invented. Replaces the bare "Degraded" chip. */}
        <AnswerDiagnostics t={t} P={P} interactive={interactive} onShowAutopsy={onShowAutopsy} />
        {/* The rail's "Answer" jump lands here. */}
        <div ref={answerTopRef} style={{ scrollMarginTop: 130 }} />
        <div ref={answerRevealRef} className="cb-answer-body" role="region" aria-label={`Answer: ${String(t.q || "").slice(0, 80)}`}>
          {connFailed ? (
            /* Connection failed: every database reported ok:false, so there
               is nothing retrieved and nothing to synthesize. Plain copy,
               real retry — never a bare error string, never invented data.
               NEXT-GEN: the panel offers retry, rephrasing, and watching
               the topic — not just "try again". */
            <AnswerStateCard kicker="Connection failed" tone="bad"
              title="The databases couldn't be reached."
              body="Every source we queried for this answer failed to respond. Nothing was retrieved, so there's nothing to synthesize yet."
              actions={[{ label: "Retry search", primary: true, onClick: retrySearch }]}
              P={P} accent={accent}>
              <QueryRetryForm P={P} accent={accent} onAsk={adjustQuery} id={`cb-retry-${t.answerId || "turn"}`} />
            </AnswerStateCard>
          ) : synthFailed && sources.length === 0 ? (
            /* Synthesis failed and the fallback carried no papers. The
               backend still builds an intelligent no-results answer (what
               was tried, likely reasons, rephrasings) — show it, never a
               bare dead end. 2026-10-09: the old branch discarded t.answer
               here and printed "no answer text to show" even though the
               backend had produced one. */
            <>
              <AnswerStateCard kicker="No synthesis available" tone="warn"
                title={answerText.trim() ? "No citable literature surfaced." : "Synthesis isn't available right now."}
                body={answerText.trim()
                  ? "No paper cleared the relevance bar for this question, so there's no written synthesis. What follows is the honest record of the search instead."
                  : "No paper cleared the relevance bar, and no fallback answer could be built from the papers, so there is no answer text to show."}
                actions={[{ label: "Retry search", primary: true, onClick: retrySearch }]}
                P={P} accent={accent}>
                <QueryRetryForm P={P} accent={accent} onAsk={adjustQuery} id={`cb-retry-${t.answerId || "turn"}`} />
              </AnswerStateCard>
              {answerText.trim() ? (
                <div style={{ marginTop: 16 }}>
                  {renderAnswer(tierText || shown, t.sources, P, accent, hoverCite, setHoverCite, activeCite, setActiveCite, claimSink, () => setEvidenceOpen(true), evidenceMap, extractQueryTerms(t.q || ""))}
                </div>
              ) : null}
            </>
          ) : synthFailed ? (
            /* Synthesis failed but the fallback retrieved papers: the card
               owns the status and the plain-English explanation; the chrome
               ("Unable To Synthesize" heading, "What To Do Next" block) is
               stripped so it doesn't compete — the paper blocks themselves
               are preserved untouched. */
            <>
              <AnswerStateCard kicker="Synthesis unavailable" tone="warn"
                title="The synthesis failed, so this isn't a written answer."
                body="The written answer could not be built. No paper cleared the relevance bar for a written synthesis. What follows: the papers the search found, with their summaries, in citation order."
                P={P} accent={accent} />
              <div style={{ marginTop: 16 }}>
                {renderAnswer(stripFallbackChrome(tierText || shown), t.sources, P, accent, hoverCite, setHoverCite, activeCite, setActiveCite, claimSink, () => setEvidenceOpen(true), evidenceMap, extractQueryTerms(t.q || ""))}
              </div>
            </>
          ) : t.synthesisMode === "extractive" && evidenceView !== "table" ? (
            <>
              <AnswerStateCard kicker="Assembled from sources" tone="warn"
                title="This answer was assembled from source passages, not written."
                body="No AI wrote this text. It was put together from passages in the papers below, so in places the wording is the papers own wording. Check anything that matters against the cited papers."
                P={P} accent={accent} />
              <div style={{ marginTop: 16 }}>
                {renderAnswer(tierText || shown, t.sources, P, accent, hoverCite, setHoverCite, activeCite, setActiveCite, claimSink, () => setEvidenceOpen(true), evidenceMap, extractQueryTerms(t.q || ""))}
              </div>
            </>
          ) : evidenceView === "table" ? (
            /* Evidence table view: the same studies as rows, columns follow
               the question type. Toggled from the view switch below the
               answer — prose remains the default. */
            <div role="tabpanel" id={viewTabUid + "-panel"} aria-labelledby={viewTabUid + "-tab-table"}>
              <EvidenceTableAnswerView t={t} P={P} accent={accent} onOpenPaper={(n) => onOpenPaper(t, n)} />
            </div>
          ) : (
            <div role="tabpanel" id={viewTabUid + "-panel"} aria-labelledby={viewTabUid + "-tab-prose"}>
              {renderAnswer(tierText || shown, t.sources, P, accent, hoverCite, setHoverCite, activeCite, setActiveCite, claimSink, () => setEvidenceOpen(true), evidenceMap, extractQueryTerms(t.q || ""))}
            </div>
          )}
        </div>
        {/* View switch: prose vs evidence table. Only once the answer has
            settled and there are sources to tabulate. Quiet segmented
            control — 14px normal case, no chrome. */}
        {done && !synthFailed && !connFailed && sources.length > 0 && (
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 14, marginBottom: 2 }}>
            <span style={{ fontSize: FONT_SIZES.caption, color: P.faint, fontFamily: "var(--cb-font)" }}>View:</span>
            <div role="tablist" aria-label="Answer view" onKeyDown={tabListKeyDown} style={{ display: "inline-flex", border: `1px solid ${P.line}`, borderRadius: RADIUS.viewport, overflow: "hidden" }}>
              {[["prose", "Prose"], ["table", "Table"]].map(([id, label]) => (
                <button key={id} type="button" role="tab" aria-selected={evidenceView === id}
                  id={viewTabUid + "-tab-" + id} aria-controls={viewTabUid + "-panel"} tabIndex={evidenceView === id ? 0 : -1}
                  onClick={() => setEvidenceView(id)}
                  style={{
                    background: evidenceView === id ? withAlpha(accent, 0.14) : "transparent",
                    border: "none", cursor: "pointer", padding: "6px 14px",
                    fontSize: FONT_SIZES.caption, fontWeight: evidenceView === id ? 500 : 400,
                    color: evidenceView === id ? P.ink : P.faint, fontFamily: "var(--cb-font)",
                    letterSpacing: "normal", textTransform: "none", minHeight: 44,
                  }}>
                  {label}
                </button>
              ))}
            </div>
          </div>
        )}
        {done && (
          <div style={{ ...S.byline, justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 8 }}>
            {/* synthesisMode comes from the backend. A failed synthesis ("none")
                must never wear the AI-synthesized label — the state card
                above already owns the failure plainly. An extractive
                (non-AI) fallback is a different kind of object than a failed
                AI one, and the byline must not call it a failure either. */}
            <span style={S.aiTag}>{(t.sources || []).length === 0 ? "No sources found" : t.synthesisMode === "none" ? "Synthesis unavailable · verify against cited sources" : t.synthesisMode === "extractive" ? "Drafted from sources · verify against cited sources" : "AI synthesized · verify against cited sources"}</span>
            {t.impact && (
              <span style={{ fontSize: FONT_SIZES.micro, color: P.faint, fontFamily: "var(--cb-font)" }}
                title="Estimated from this search's synthesis tokens and published per token energy figures. Providers do not report actual usage, so this is an estimate. The method is written out in How this was built.">
                This search used about {fmtImpactEnergy(t.impact)} of electricity and {fmtImpactWater(t.impact)} of water (estimate)
              </span>
            )}
            {/* Reading level indicator: tells users the Simplify toggle exists */}
            {done && !synthFailed && t.answer && t.answer.length > 200 && (
              <button type="button" onClick={doSimplify} title={readingLevel === "plain" ? "Show the original answer" : "Rewrite one reading level simpler (" + (readingLevel === "graduate" ? "undergrad" : "plain") + " next)"}
                style={{
                  minHeight: 44, display: "inline-flex", alignItems: "center", gap: 6,
                  fontSize: FONT_SIZES.micro, fontWeight: 500, fontFamily: "var(--cb-font)",
                  color: readingLevel === "graduate" ? P.faint : accent, background: "transparent",
                  border: "none", cursor: "pointer", padding: "3px 8px",
                }}>
                <span style={{ fontFamily: "var(--cb-font)", fontSize: 10, letterSpacing: "normal", textTransform: "none" }}>
                  Reading level: {SIMPLIFY_LABELS[readingLevel]}{simplifying ? "…" : ""}
                </span>
              </button>
            )}
            {/* Pro quota nudge: when the backend gated AI synthesis (free cap
                hit, or signed out), the footnote says why and where to go —
                never a dead end. Opens the Pro modal / auth via window
                events so this deeply-nested renderer needs no props. */}
            {/* Pass 2 (instrument): quota nudges are mono instrument buttons,
                not filled pills. No em dash in the copy. */}
            {t.aiQuota && t.aiQuota.gated === "free-cap" && (
              <span style={{ flexBasis: "100%", display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
                <span style={{ fontSize: FONT_SIZES.caption, color: P.ink2, fontFamily: "var(--cb-font)", lineHeight: 1.55 }}>{aiQuotaReason}</span>
                <button onClick={() => window.dispatchEvent(new CustomEvent("cb:open-pro", { detail: { reason: aiQuotaReason } }))}
                  style={{ minHeight: 44, display: "inline-flex", alignItems: "center", gap: 6, fontSize: FONT_SIZES.caption, fontWeight: 500, fontFamily: "var(--cb-font)", letterSpacing: "normal", textTransform: "none", color: accent, background: "transparent", border: `1px solid ${withAlpha(accent, 0.4)}`, borderRadius: 2, padding: "3px 12px", cursor: "pointer" }}>
                  Go Pro
                </button>
              </span>
            )}
            {t.aiQuota && t.aiQuota.gated === "signin-required" && (
              <UIButton P={P} variant="ghost" onClick={() => window.dispatchEvent(new CustomEvent("cb:open-auth"))}
                style={{ minHeight: 44, display: "inline-flex", alignItems: "center", gap: 6, fontSize: FONT_SIZES.caption, fontWeight: 500, fontFamily: "var(--cb-font)", letterSpacing: "normal", textTransform: "none", color: P.ink2, background: "transparent", border: `1px solid ${P.line2}`, borderRadius: 2, padding: "3px 12px", cursor: "pointer" }}>
                Sign in for AI answers
              </UIButton>
            )}
          </div>
        )}
        {/* Trust release: the coverage sentence and the Search record
            disclosure sit under the answer with the byline, the footer
            zone the diagnostics and methods copy already live in. Only
            once the answer has settled, and only when the backend
            shipped the data (the panel itself renders nothing without
            _coverage or _record). */}
        {done && <SearchRecordPanel t={t} P={P} />}
        {interactive && (hoverCite || activeCite) ? (
          <CitationPeek
            n={hoverCite || activeCite}
            sources={t.sources}
            P={P} accent={accent} isMobile={isMobile}
            onOpen={(n) => onOpenPaper(t, n)}
            onClose={() => { setHoverCite && setHoverCite(0); setActiveCite(0); }}
          />
        ) : null}
        {showReport && <ReportModal query={t.q} P={P} accent={accent} at={at} onClose={() => setShowReport(false)} answer={t.answer} sources={t.sources} />}
        </article>
        </div>
      </div>
      {/* The evidence index drawer: secondary, portaled, closed by default.
          Citation taps, the toolbar, and the jump rail open it. */}
      {done && t.answer && sources.length > 0 && (
        <EvidenceRail t={t} P={P} accent={accent} venn={venn} claimSink={claimSink}
          activeCite={activeCite} onActivate={onActivateCite}
          onOpenPaper={(n) => onOpenPaper(t, n)}
          open={evidenceOpen} onClose={() => setEvidenceOpen(false)} />
      )}
      {/* StressTest and EvidenceStructure now live inside the "How this was
          built" drawer (QueryAutopsy) — they're autopsy material, not
          reading material. See QueryAutopsy. */}
      {/* Open questions — the gap finder. The button above only exists when
          gaps surfaced; the panel itself still renders its honest empty
          state if opened with nothing, rather than a blank card. */}
      {/* The evidence map: which claims stand on which papers, read from the
          answer's own citations. Sits between the answer and the evidence
          band — the bridge from reading to verifying. Only when the answer
          is settled; a streaming map would strobe. */}
      {done && t.answer && (
        <div ref={evMapRef} style={{ scrollMarginTop: 130 }}>
          <EvidenceMap t={t} P={P} accent={accent} onOpenPaper={(n) => onOpenPaper(t, n)} />
        </div>
      )}
      {/* Jump rail — sticky under the answer card, mono labels with live
          ready/empty/failed status from the turn's real data. Buttons, so
          touch works; nothing here depends on hover. */}
      {done && t.answer && <JumpRail items={railItems} P={P} accent={accent} onJump={jumpToSection} onFollowUp={onFollowUp} isMobile={isMobile} />}
      {/* The Evidence band: Bibliography + Videos as tabs in one band,
          directly under the answer. Always rendered — the shells inside are
          honest about empty/loading instead of vanishing. */}
      {done && (
        <div ref={bandSectionRef} style={{ scrollMarginTop: 130 }}>
          <EvidenceBand t={t} P={P} accent={accent} tab={evTab} setTab={setEvTab}
            citationStyle={citationStyle} setCitationStyle={setCitationStyle}
            onOpenPaper={(n) => onOpenPaper(t, n)} onOpenVideo={setOpenVideo}
            onRetry={retrySearch} onAdjustQuery={adjustQuery} busyNow={busyNow} done={done}
            activeCite={activeCite} onActivateCite={onActivateCite}
            onHoverRow={(n) => setFanN(n)} onLeaveRow={() => setFanN(0)} />
        </div>
      )}
      {/* Provenance colophon (scite 10x item 7): one quiet line — when the
          sources were pulled and from how many indexes. Below the Sources
          band, above Fact-check. */}
      {done && (
        <ProvenanceColophon t={t} P={P} />
      )}
      {/* Fact-check — always a section, never a silent gap. The states
          are kept distinct because they mean different things: a null
          factCheck means the check DID NOT RUN (a cached serve ships
          null), a present check with no claims means it ran and found
          nothing checkable, and an errored check failed. A null must
          never render under "Nothing to verify" . that heading claims
          a check ran and came back empty (2026-10-14). */}
      {done && (
        <div ref={fcSectionRef} style={{ scrollMarginTop: 130 }}>
          {t.factCheck && !t.factCheck.error && (t.factCheck.claims || []).length > 0 ? (
            <FactCheck fc={t.factCheck} P={P} accent={accent} />
          ) : (
            <AnswerSection eyebrow="Fact check" P={P} accent={accent}>
              {(() => {
                const fcError = !!(t.factCheck && t.factCheck.error);
                const fcRanEmpty = !!t.factCheck && !t.factCheck.error;
                const noClaimsPossible = t.responseKind === "no-results" || (t.sources || []).length === 0;
                const state = fcError ? "failed"
                  : fcRanEmpty || noClaimsPossible ? "empty"
                  : "notrun";
                return (
                  <AnswerStateCard
                    kicker={state === "failed" ? "Check failed" : state === "empty" ? "Nothing to verify" : "Check did not run"}
                    tone={state === "failed" ? "bad" : "neutral"}
                    title={state === "failed"
                      ? "The verification pass didn't complete."
                      : state === "empty"
                        ? "No scientific claims to verify."
                        : "The verification pass did not run for this answer."}
                    body={state === "failed"
                      ? "The fact check is a separate pass over the answer's claims. It didn't produce a result here."
                      : state === "empty"
                        ? noClaimsPossible
                          ? "This answer makes no claims about the literature. It reports what the search tried and why nothing citable surfaced, so there is nothing to check against sources."
                          : "The verification pass ran over this answer and found no checkable claims in it. The answer's citations still point at the papers they came from."
                        : "This answer was served without the verification pass, so no claim in it carries a checked verdict. The citations still point at the papers they came from, and a fresh search runs the check."}
                    actions={[{ label: "Retry search", onClick: retrySearch }]}
                    P={P} accent={accent} />
                );
              })()}
            </AnswerSection>
          )}
        </div>
      )}
      {/* The stance ledger replaces "where it disagrees" — see StanceLedger.
          Flashpoints (the raw conflicting claim pairs) collapse underneath it;
          when the claims don't split into two camps the section says so
          honestly instead of rendering nothing. */}
      {interactive && done && (
        <div ref={vennSectionRef} style={{ scrollMarginTop: 130 }}>
          {vennReady ? (
            <StanceLedger turn={t} P={P} accent={accent} onOpenPaper={(n) => onOpenPaper(t, n)} />
          ) : (
            <AnswerSection eyebrow="Where the literature disagrees" P={P} accent={accent}>
              {/* NEXT-GEN: the backend computes a real verdict (divided /
                  settled / thin) from the sources' own claims. When the
                  Venn can't form two camps, say what the verdict actually
                  is instead of defaulting to "no clear divide". */}
              {(() => {
                const v = t.disagreementVerdict;
                const kicker = !v ? "No clear divide"
                  : v.status === "divided" ? "DIVIDED"
                  : v.status === "settled" ? "CONSISTENT"
                  : "Thin evidence";
                const conflict = Array.isArray(t.literatureConflicts) && t.literatureConflicts.length > 0 ? t.literatureConflicts[0] : null;
                const disagreeIdx = Array.isArray(venn.disagree) && venn.disagree.length > 0 ? venn.disagree[0] : null;
                const disputeRaw = conflict
                  ? (conflict.sourceB || conflict.sourceA || "")
                  : disagreeIdx && sources[disagreeIdx - 1] ? (sources[disagreeIdx - 1].title || "") : "";
                const disputeTitle = cleanTitleText(disputeRaw).trim();
                const shortDisputeTitle = disputeTitle.length > 64 ? disputeTitle.slice(0, 64).trimEnd() + "…" : disputeTitle;
                const dividedBody = [
                  shortDisputeTitle ? `${shortDisputeTitle} is on one side of the split.` : "",
                  conflict && conflict.claimA ? `One claim: ${conflict.claimA}` : "",
                  conflict && conflict.claimB ? `The claim it disagrees with: ${conflict.claimB}` : "",
                  v && v.summary ? v.summary : "",
                ].filter(Boolean).join(" ");
                const body = v && v.status === "divided" && dividedBody
                  ? dividedBody
                  : (v && v.summary) || "The cited claims don't split into two camps. The literature, as cited, reads as settled or too thin to divide.";
                return (
                  <AnswerStateCard kicker={kicker}
                    title={v && v.status === "divided"
                      ? shortDisputeTitle
                        ? `${shortDisputeTitle} disagrees with other cited papers.`
                        : "The sources genuinely split. See the flashpoints below."
                      : v && v.status === "settled"
                        ? "No clear disagreement surfaced."
                        : v && v.status === "thin"
                          ? "Too little evidence to tell whether the sources disagree."
                          : "No clear disagreement surfaced."}
                    body={body}
                    P={P} accent={accent} />
                );
              })()}
            </AnswerSection>
          )}
        </div>
      )}
      {done && t.literatureConflicts && t.literatureConflicts.length > 0 && (
        /* Pass 2 (instrument): conflicts are ruled ledger rows, not soft
           cards. Hairline dividers, mono position labels, a conflict glyph
           as the divider instead of "vs" text. No tint, no radius. */
        <details style={{ marginTop: 16 }} className="cb-fade">
          <summary style={{
            cursor: "pointer", fontFamily: "var(--cb-font)", fontSize: FONT_SIZES.micro,
            fontWeight: 500, letterSpacing: "normal", textTransform: "none", color: P.faint,
          }}>
            Flashpoints · {t.literatureConflicts.length} conflicting claim pair{t.literatureConflicts.length === 1 ? "" : "s"}
          </summary>
          <div style={{ marginTop: 4, borderTop: `1px solid ${P.line}` }}>
            {t.literatureConflicts.map((c, ci) => (
              <div key={ci} style={{ display: "grid", gridTemplateColumns: "1fr auto 1fr", gap: 16, alignItems: "start", padding: "16px 4px", borderBottom: `1px solid ${P.line}` }}>
                <div>
                  <div style={{ fontSize: 10, fontWeight: 500, letterSpacing: "0.12em", color: P.faint, marginBottom: 6, fontFamily: "var(--cb-font)" }}>POSITION A · [{c.idxA}]</div>
                  <div style={{ fontSize: FONT_SIZES.small, color: P.ink, lineHeight: 1.55 }}>{renderFlashpointClaim(c.claimA, P)}</div>
                  <div style={{ fontSize: FONT_SIZES.caption, color: P.faint, marginTop: 6, lineHeight: 1.4, fontStyle: "italic" }}>{c.sourceA ? renderCleanTitle(c.sourceA) : ""}</div>
                </div>
                <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "center", color: statusWarn(P), paddingTop: 22 }} aria-hidden="true">
                  <Icon name="verdictContradicted" size={18} />
                </div>
                <div>
                  <div style={{ fontSize: 10, fontWeight: 500, letterSpacing: "0.12em", color: P.faint, marginBottom: 6, fontFamily: "var(--cb-font)" }}>POSITION B · [{c.idxB}]</div>
                  <div style={{ fontSize: FONT_SIZES.small, color: P.ink, lineHeight: 1.55 }}>{renderFlashpointClaim(c.claimB || "Not stated", P)}</div>
                  <div style={{ fontSize: FONT_SIZES.caption, color: P.faint, marginTop: 6, lineHeight: 1.4, fontStyle: "italic" }}>{c.sourceB ? renderCleanTitle(c.sourceB) : ""}</div>
                </div>
              </div>
            ))}
          </div>
        </details>
      )}
      {/* The arc shortcut link lived here; the jump rail ("Compare") and the
          toolbar's More menu now land on the comparison section, so the
          one-off link is gone — one way to reach it, not three. */}
      {/* Compare — table / network / arc, one at a time. The rail and the
          toolbar's More menu land here; EvidenceSection owns its honest
          empty shell now instead of returning null. */}
      {done && (
        <div ref={compareSectionRef} style={{ scrollMarginTop: 130 }}>
          <EvidenceSection t={t} P={P} accent={accent} evOpen={evOpen} setEvOpen={setEvOpen} onOpenPaper={(n) => onOpenPaper(t, n)} />
        </div>
      )}
      {done && showOQ && (
        <div ref={oqSectionRef} style={{ scrollMarginTop: 130 }}>
          <OpenQuestions cards={openQuestions} P={P} accent={accent} />
        </div>
      )}
      {/* Video explainers now live in the Evidence band above (Videos tab);
          the player is the band's own modal — the poster stays under the
          iframe and the iframe fades in over it, no black flash. */}
      {openVideo && <EvidenceVideoModal P={P} accent={accent} video={openVideo} close={() => setOpenVideo(null)} />}
      {/* The answer's reading order: Evidence (bibliography + videos, tabbed)
          sits directly under the answer, then fact-check, then where the
          literature disagrees, then comparison tools, then open questions,
          then the continue strip (suggestions / watch / related). Every
          section renders its shell always — no silent gaps. */}
      {/* NEXT-GEN: ambiguity notice — when the question used a term with
          multiple scientific meanings, say which one the answer ran with
          (or offer the interpretations when it couldn't decide). */}
      {interactive && done && t.ambiguity && t.ambiguity.ambiguous && Array.isArray(t.ambiguity.interpretations) && t.ambiguity.interpretations.length > 0 && t.responseKind !== "no-results" && (
        /* Pass 2 (instrument): ambiguity is a ruled notice, not a tinted
           card. Mono kicker, plain sentence, instrument buttons. */
        <div style={{ marginTop: 16, padding: "14px 4px 4px", borderTop: `1px solid ${withAlpha(STATUS.warn, 0.45)}` }} className="cb-fade">
          <div style={{ fontSize: 10, fontWeight: 500, letterSpacing: "normal", textTransform: "none", color: statusWarn(P), marginBottom: 8, fontFamily: "var(--cb-font)" }}>Ambiguous term</div>
          <div style={{ fontSize: FONT_SIZES.small, color: P.ink, lineHeight: 1.55 }}>
            “{t.ambiguity.term}” means different things in different fields.
            {t.ambiguity.resolvedAs ? <> This answer ran with <span style={{ fontWeight: 500 }}>{t.ambiguity.resolvedAs}</span>.</> : <> Pick the one you meant.</>}
          </div>
          <div style={{ display: "flex", flexWrap: "wrap", gap: 8, marginTop: 10 }}>
            {t.ambiguity.interpretations.map((it, i) => (
              <UIButton P={P} variant="ghost" key={i} onClick={() => it.query && onRelated && onRelated(it.query)}
                title={it.query || it.label}
                style={{ minHeight: 44, padding: "6px 12px", fontSize: FONT_SIZES.caption, fontWeight: 500, background: "transparent", color: P.ink2, border: `1px solid ${P.line2}`, borderRadius: RADIUS.md, cursor: "pointer", fontFamily: "inherit" }}>
                {it.label} <span style={{ opacity: 0.5, marginLeft: 4 }}>→</span>
              </UIButton>
            ))}
          </div>
        </div>
      )}
      {/* #15/#17: zero-result recovery — "Try this instead" with 2–3
          concrete reformulations, each a different strategy. The copy
          distinguishes a first-use empty from filtered-to-zero; the
          filtered case gets a clear-filter-and-retry action. Rendered
          only for genuine no-results turns (not error states). */}
      {interactive && done && t.responseKind === "no-results" && (
        <ZeroResultsRecovery t={t} P={P} accent={accent} evidenceFilter={evidenceFilter} onClearFilterAndRetry={onClearFilterAndRetry} onRelated={onRelated} />
      )}
      {/* AI suggestions */}
      {interactive && done && t.suggestions && t.suggestions.length > 0 && (
        <div style={{ alignItems: "center", marginTop: 20, display: "flex", flexWrap: "wrap", gap: 8 }} className="cb-fade">
          {t.suggestions.map((s, i) => (
            <UIButton P={P} variant="ghost" key={i} onClick={() => s.query && onRelated && onRelated(s.query)} disabled={!s.query}
              style={{ minHeight: 44, padding: "7px 16px", fontSize: FONT_SIZES.small, fontWeight: 500, background: s.query ? withAlpha(accent, 0.08) : "transparent", color: s.query ? accent : P.faint, border: `1px solid ${s.query ? withAlpha(accent, 0.25) : P.line}`, borderRadius: RADIUS.md, cursor: s.query ? "pointer" : "default", fontFamily: "inherit" }}>
              {s.label} {s.query && <span style={{ opacity: 0.5, marginLeft: 4 }}>→</span>}
            </UIButton>
          ))}
        </div>
      )}
      {/* Commit 65 — "Watch this topic", placed at the end of a finished
          answer because that is the one moment we know the reader cares
          about this subject. Only on the LAST turn: repeating it under
          every answer in a long thread turns a useful offer into nagging. */}
      {interactive && done && last && t.responseKind !== "context" && (
        <WatchTopicButton q={t.q} P={P} accent={accent} user={user} onChanged={onWatchChanged} />
      )}
      {/* Related questions */}
      {interactive && done && t.related && t.related.length > 0 && (
        <div style={S.relatedWrap} className="cb-fade">
          <div style={S.relatedLabel}>Continue the investigation</div>
          <div style={S.relatedList}>
            {t.related.map((r, i) => (
              <button key={i} style={S.relatedBtn} onClick={() => onRelated(r)} onMouseEnter={(e) => { e.currentTarget.style.borderColor = accent; e.currentTarget.style.color = accent; e.currentTarget.style.transform = "none"; e.currentTarget.style.boxShadow = P.dark ? "none" : "none"; }} onMouseLeave={(e) => { e.currentTarget.style.borderColor = P.line2; e.currentTarget.style.color = P.ink2; e.currentTarget.style.transform = ""; e.currentTarget.style.boxShadow = ""; }}>
                <span>{r}</span><span style={{ color: accent, fontFamily: "var(--cb-font)" }}>→</span>
              </button>
            ))}
          </div>
        </div>
      )}
      {/* #18: compact Sources panel closing out the answer — one row per
          cited paper (title, venue · year, DOI link) plus the visible
          "Evidence index" affordance, which opens the evidence drawer. */}
      {interactive && done && sources.length > 0 && t.responseKind !== "no-results" && (
        <AnswerSourcesPanel t={t} P={P} accent={accent} onVerify={() => setEvidenceOpen(true)} />
      )}
      {/* #10: contextual discovery chips once the answer has completed —
          each chip only renders when it is relevant to this answer. */}
      {interactive && done && !synthFailed && answerText.trim() && (
        <DiscoveryChips t={t} P={P} accent={accent}
          onSaveInvestigation={onSaveInvestigation ? () => onSaveInvestigation(t) : null}
          onCreateDiagram={onShowFlowchart}
          onAnalyzeDocument={onOpenDocumentMode} />
      )}
      {/* Print-only academic layout — invisible in the normal UI (see the
          base ".cb-print-paper-doc { display: none }" rule) and only ever
          mounted once this specific Turn's "Generate paper" button has
          fired (see paperReady above), so it's never the wrong turn's
          content that a multi-turn conversation's print stylesheet finds.

          Rendered through a portal straight onto <body>, NOT in place here.
          It used to render right where this comment sits — several flex/grid
          levels deep inside the app shell — and get lifted out visually with
          position:absolute/fixed plus a "make everything else invisibility:
          hidden" trick. That out-of-flow overlay approach is what caused the
          real bug: Chromium's print-to-PDF pagination computes an
          out-of-flow box's per-page available width completely wrong once
          its content spans more than one printed page (title/abstract
          wrapping one word per line), and it never contributes to the
          document's flowed height, so the page count printed was whatever
          the (still-in-flow-but-hidden) chat happened to be, not the paper's
          real length — hence trailing blank pages too. A portal makes this
          node a plain static, in-flow, first-class page of its own with
          body as its only ancestor, so Chromium's ordinary (well-exercised)
          multi-page article pagination lays it out the same way it would
          any other printable page — see the plain ".cb-print-paper-doc"
          rules in the @media print block below. */}
      {paperReady && document.body && createPortal(
        <div className="cb-print-paper-doc" aria-hidden="true">
          <div className="cb-paper-page">
            {/* Commit 51: the same brain Mark used in the Sidebar/header
                (see the Mark component) — a small letterhead-style masthead
                above the title, not a new logo invented just for exports. */}
            <div className="cb-paper-masthead">
              <Mark size={16} accent="#000" glow={false} />
              <span className="cb-paper-masthead-text">CEREBRUM</span>
            </div>
            <div className="cb-paper-title">{t.q}</div>
            <div className="cb-paper-byline">Synthesized by Cerebrum · {new Date().toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric" })}</div>

            {/* 2026-10-19 (S2, H14): the answer's own blocks, in order,
                through the shared inline renderer, so no markdown
                marker reaches paper and a species name italicizes on
                paper exactly as it does on screen. No fabricated
                Introduction, no Abstract or Conclusion relabeling,
                and the 90pt rotated watermark treatment is gone. */}
            {paper.blocks.map((b, i) => (
              b.type === "heading"
                ? <div key={i} className="cb-paper-heading">{renderInlineMdLite(b.text, P)}</div>
                : <p key={i} className="cb-paper-para">{renderInlineMdLite(b.text, P)}</p>
            ))}

            {t.sources && t.sources.length > 0 && (
              <>
                <div className="cb-paper-section-label">References</div>
                <div className="cb-paper-references">
                  {t.sources.map((s, i) => (
                    <p key={i} className="cb-paper-ref">{renderInlineMdLite(formatCitation(s, citationStyle || "vancouver", i + 1), P)}</p>
                  ))}
                </div>
              </>
            )}
          </div>
        </div>,
        document.body
      )}
    </div>
  );
}
// Memoized: a keystroke in the shared search input re-renders App, and
// without this every mounted turn re-rendered with it (each Turn received
// ~8 fresh inline callbacks). The per-turn handlers are stabilized in
// TurnRow below so this memo actually holds.
const Turn = React.memo(TurnInner);
/* Per-turn row with stabilized callbacks. onStress closes over t.q so it
   can't be hoisted to App scope; this wrapper memoizes it per turn.
   askRef breaks the ask→input dependency chain — ask is useCallback'd on
   `input`, so it changes on every keystroke and any closure over it would
   defeat the memo. */
const TurnRow = React.memo(function TurnRow({ t, askRef, ...rest }) {
  const onStress = useCallback((o) => askRef.current?.(t?.q, o), [askRef, t?.q]);
  return <Turn t={t} onStress={onStress} {...rest} />;
});


/* useFocusTrap was the hand-rolled focus trap every modal used to carry.
   It is deleted: the Dialog primitive (above ModalChrome) now owns initial
   focus, Tab/Shift+Tab containment, topmost-only Escape, scroll lock with
   scrollbar compensation, and focus restore for every overlay. */

/* ============================================================
   HOW IT WORKS + SETTINGS — same logic, new visual system
   (HowItWorksModal was deleted: dead code, superseded by HowItWorksDialog.)
   ============================================================ */
/* Commit 92 — V5AnnouncementModal deleted.
   Nothing rendered it (see the note where v5Open used to live), it
   advertised the concept-illustration feature that this commit removed,
   and it was the last thing referencing that feature. A dead component
   describing a dead feature is how a file gets to fourteen thousand
   lines. */

// Shown once, right after a successful sign-in/sign-up, if the browser
// already had guest-mode saved articles or history sitting in localStorage.
// Accepting keeps that data exactly where it is client-side (nothing new to
// fetch) — it simply gets swept into the account by the normal sync effect
// that already watches `saved`/`history` for changes once `user` is set.
/* Public Beta 2 announcement (2026-10-12). Rendered from App off the
   beta2Open boolean; see the state note in App for why the render and
   the scroll lock share one boolean. Copy stays plain on purpose: no
   hype, no dashes, nothing that sounds generated. */
function Beta2Announcement({ P, accent, at, onClose, onTryLearn }) {
  const items = [
    { title: "Nova is new", body: "Pick a topic and Nova teaches it in short lessons, with quick quizzes on what was taught and XP as you go. It lives in the sidebar, and on phones it has its own tab." },
    { title: "Search got tougher", body: "Questions with several parts used to come back with no sources at all. They return real sources now, and an answer is never built on zero papers." },
    { title: "Answers read easier", body: "Wider pages, calmer backgrounds, and plainer wording across the whole site." },
    { title: "One intro clip is gone", body: "A background clip that should never have shipped was still playing behind the door. It is out, and every remaining clip has been checked frame by frame." },
  ];
  return (
    <Dialog label="Public Beta 2" onClose={onClose}
      zIndex={216} width={440}
      panelStyle={{ background: P.bg, borderRadius: RADIUS.md, padding: 28, boxShadow: "none", border: `1px solid ${P.line}`, outline: "none", fontFamily: "var(--cb-font)" }}
    >
      <div style={{ fontSize: FONT_SIZES.caption, fontWeight: 500, letterSpacing: "0.14em", color: accent, marginBottom: 10 }}>PUBLIC BETA 2</div>
      <h2 style={{ margin: "0 0 6px", fontSize: 21, fontWeight: 500, color: P.ink, fontFamily: "var(--cb-font)" }}>What changed</h2>
      <p style={{ margin: "0 0 20px", fontSize: 13.5, color: P.ink2, lineHeight: 1.55 }}>Four things since Beta 1.</p>
      <div style={{ display: "flex", flexDirection: "column", marginBottom: 24 }}>
        {items.map((it, i) => (
          <div key={it.title} style={{ display: "flex", gap: 14, padding: "12px 0", borderTop: i === 0 ? "none" : `1px solid ${P.line}` }}>
            <div aria-hidden="true" style={{ fontSize: FONT_SIZES.caption, fontWeight: 500, color: accent, paddingTop: 2, minWidth: 18 }}>{String(i + 1).padStart(2, "0")}</div>
            <div>
              <div style={{ fontSize: 14.5, fontWeight: 500, color: P.ink, marginBottom: 3 }}>{it.title}</div>
              <div style={{ fontSize: 13.5, color: P.ink2, lineHeight: 1.6 }}>{it.body}</div>
            </div>
          </div>
        ))}
      </div>
      <div style={{ display: "flex", gap: 10, justifyContent: "flex-end" }}>
        <button onClick={onClose} style={{ background: "transparent", border: `1px solid ${P.line}`, borderRadius: RADIUS.sm, padding: "10px 18px", color: P.ink, fontSize: 14, cursor: "pointer", fontFamily: "var(--cb-font)" }}>Got it</button>
        <button onClick={onTryLearn} style={{ background: accent, border: "none", borderRadius: RADIUS.sm, padding: "10px 18px", color: at, fontSize: 14, fontWeight: 500, cursor: "pointer", fontFamily: "var(--cb-font)" }}>Try Nova</button>
      </div>
    </Dialog>
  );
}

function ImportLocalDataPrompt({ P, accent, at, savedCount, historyCount, onImport, onSkip }) {
  return (
    <Dialog label="Import your existing data" onClose={onSkip} dismissable={false}
      zIndex={216} width={440}
      panelStyle={{ background: P.bg, borderRadius: RADIUS.md, padding: 26, boxShadow: "none", border: `1px solid ${P.line}`, outline: "none" }}
    >
        <div style={{ width: 40, height: 40, borderRadius: RADIUS.md, background: withAlpha(accent, 0.12), color: accent, display: "flex", alignItems: "center", justifyContent: "center", marginBottom: 14 }}><Icon name="bookmarkFilled" size={18} /></div>
        <div style={{ fontSize: FONT_SIZES.subhead, fontWeight: 500, color: P.ink, marginBottom: 8 }}>Bring your existing data along?</div>
        <div style={{ fontSize: FONT_SIZES.small, color: P.ink2, lineHeight: 1.6, marginBottom: 18 }}>
          This browser already has {savedCount > 0 ? <><strong>{savedCount} saved source{savedCount === 1 ? "" : "s"}</strong>{historyCount > 0 ? " and " : ""}</> : null}
          {historyCount > 0 ? <><strong>{historyCount} past investigation{historyCount === 1 ? "" : "s"}</strong></> : null} from before you signed in. Attach it to your new account so it follows you to other devices?
        </div>
        <div style={{ display: "flex", gap: 10 }}>
          <UIButton P={P} variant="ghost" onClick={onSkip} style={{ minHeight: 44, flex: 1, padding: "11px", fontSize: FONT_SIZES.small, fontWeight: 500, background: "transparent", color: P.ink2, border: `1px solid ${P.line}`, borderRadius: RADIUS.md, cursor: "pointer" }}>Start account fresh</UIButton>
          <UIButton P={P} variant="ghost" onClick={onImport} style={{ minHeight: 44, flex: 1, padding: "11px", fontSize: FONT_SIZES.small, fontWeight: 500, background: accent, color: at, border: "none", borderRadius: RADIUS.md, cursor: "pointer" }}>Add to my account</UIButton>
        </div>
        <div style={{ fontSize: FONT_SIZES.caption, color: P.faint, marginTop: 12, lineHeight: 1.5 }}>"Start fresh" clears this browser's local list rather than leaving it stranded outside your account.</div>
    </Dialog>
  );
}

// Collections tab — organizes the flat Saved-articles list into named
// groups (signed-in only; server-backed via /api/data's "collections"
// actions, same as everything else in this file talks to the backend).
// Deliberately simple: create/rename/delete a collection, and move a saved
// source in or out of one via a custom dropdown rather than drag-and-drop —
// drag-and-drop is a lot of extra surface for what's fundamentally a filing
// operation people do occasionally, not constantly.
function CollectionsModal({ P, accent, at, S, saved, collections, onCreateCollection, onRenameCollection, onDeleteCollection, onMoveSource, close, page = false, narrow = false }) {
  const [newName, setNewName] = useState("");
  const [renamingId, setRenamingId] = useState(null);
  const [renameValue, setRenameValue] = useState("");
  const [activeId, setActiveId] = useState("all"); // "all" | "uncategorized" | collection id
  const [deleteConfirmId, setDeleteConfirmId] = useState(null);
  // Commit 88 — Escape dismisses a dialog. In page mode there is nothing
  // to dismiss, and stealing Escape from a page is how you lose a
  // half-typed collection name.
  /* Escape in modal mode is owned by the Dialog primitive; no hand-rolled listener. */

  const countFor = (id) => id === "all" ? saved.length : id === "uncategorized" ? saved.filter((s) => !s.collectionId).length : saved.filter((s) => s.collectionId === id).length;
  const visible = activeId === "all" ? saved : activeId === "uncategorized" ? saved.filter((s) => !s.collectionId) : saved.filter((s) => s.collectionId === activeId);

  /* Commit 88 — the same component renders either as the dialog it used
     to be (still reachable from the command palette and from a source's
     "add to collection" action, where interrupting you IS the right
     behaviour) or as a full page when it is the destination the sidebar
     navigated to. One implementation, two containers, so the two can
     never drift apart. */
  const content = (
    <>
        <div style={narrow
          ? { width: "100%", flexShrink: 0, borderBottom: `1px solid ${P.line}`, padding: 16 }
          : { width: 210, flexShrink: 0, borderRight: `1px solid ${P.line}`, padding: 16, overflowY: "auto" }}>
          <div style={{ fontSize: FONT_SIZES.caption, fontWeight: 500, letterSpacing: TRACKING.tight, color: P.faint, fontFamily: "var(--cb-font)", marginBottom: 12 }}>Collections</div>
          {[{ id: "all", name: "All saved" }, { id: "uncategorized", name: "Uncategorized" }, ...collections].map((c) => (
            <div key={c.id} style={{ display: "flex", alignItems: "center", gap: 4, marginBottom: 2 }}>
              {renamingId === c.id ? (
                <input autoFocus value={renameValue} aria-label="Rename collection" onChange={(e) => setRenameValue(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter") { onRenameCollection(c.id, renameValue); setRenamingId(null); } if (e.key === "Escape") { e.stopPropagation(); setRenamingId(null); } }} onBlur={() => setRenamingId(null)} style={{ flex: 1, padding: "7px 8px", fontSize: 16, borderRadius: RADIUS.md, border: `1px solid ${accent}`, background: "transparent", color: P.ink }} />
              ) : (
                <UIButton P={P} variant="ghost" onClick={() => setActiveId(c.id)} onDoubleClick={() => { if (c.id !== "all" && c.id !== "uncategorized") { setRenamingId(c.id); setRenameValue(c.name); } }} style={{ minHeight: 44, flex: 1, textAlign: "left", padding: "7px 8px", fontSize: FONT_SIZES.small, borderRadius: RADIUS.md, border: "none", cursor: "pointer", background: activeId === c.id ? withAlpha(accent, 0.12) : "transparent", color: activeId === c.id ? accent : P.ink2, fontFamily: "var(--cb-font)" }}>
                  {c.name} <span style={{ opacity: 0.6 }}>({countFor(c.id)})</span>
                </UIButton>
              )}
              {c.id !== "all" && c.id !== "uncategorized" && renamingId !== c.id && (
                deleteConfirmId === c.id ? (
                  <span style={{ display: "inline-flex", gap: 4, flexShrink: 0 }}>
                    <button onClick={() => setDeleteConfirmId(null)} style={{ minHeight: 44, ...S.chipMini, padding: "3px 7px" }}>Cancel</button>
                    <button onClick={() => { onDeleteCollection(c.id); setDeleteConfirmId(null); if (activeId === c.id) setActiveId("all"); }} style={{ minHeight: 44, ...S.chipMini, padding: "3px 7px", background: "#d13438", color: "#fff", borderColor: "#d13438" }}>Confirm</button>
                  </span>
                ) : (
                  <button onClick={() => setDeleteConfirmId(c.id)} aria-label={`Delete ${c.name}`} style={{ background: "none", border: "none", color: P.faint, cursor: "pointer", padding: 4, display: "inline-flex" }}><Icon name="close" size={12} /></button>
                )
              )}
            </div>
          ))}
          <div style={{ display: "flex", gap: 6, marginTop: 12 }}>
            <input value={newName} onChange={(e) => setNewName(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter" && newName.trim()) { onCreateCollection(newName.trim()); setNewName(""); } }} placeholder="New collection…" aria-label="New collection name" style={{ flex: 1, padding: "7px 8px", fontSize: 16, borderRadius: RADIUS.md, border: `1px solid ${P.line}`, background: "transparent", color: P.ink }} />
            <UIButton P={P} variant="ghost" onClick={() => { if (newName.trim()) { onCreateCollection(newName.trim()); setNewName(""); } }} aria-label="Create collection" style={{ background: withAlpha(accent, 0.12), color: accent, border: "none", borderRadius: RADIUS.md, padding: "0 12px", cursor: "pointer" }}><Icon name="plus" size={13} /></UIButton>
          </div>
        </div>
        <div style={{ flex: 1, minWidth: 0, display: "flex", flexDirection: "column" }}>
          <div style={{ padding: "16px 24px", borderBottom: `1px solid ${P.line}`, display: "flex", alignItems: "center", justifyContent: "space-between" }}>
            <div style={{ fontSize: FONT_SIZES.body, fontWeight: 500, color: P.ink }}>{activeId === "all" ? "All saved" : activeId === "uncategorized" ? "Uncategorized" : collections.find((c) => c.id === activeId)?.name || "Collection"}</div>
            {!page && <button onClick={close} aria-label="Close" style={{ background: "none", border: "none", color: P.faint, cursor: "pointer", padding: 13, display: "inline-flex" }}><Icon name="close" size={18} /></button>}
          </div>
          <div style={{ flex: 1, overflowY: "auto", padding: 16 }}>
            {visible.length === 0 ? (
              <div style={{ fontSize: FONT_SIZES.small, color: P.faint, textAlign: "center", padding: "40px 0" }}>
                {activeId === "all" ? "Nothing saved yet." : "Nothing here yet: move a saved source in with the dropdown next to it on “All saved.”"}
              </div>
            ) : visible.map((s, i) => (
              <div key={sourceKey(s)} style={{ padding: "12px 4px", borderTop: i ? `1px solid ${P.line}` : "none", display: "flex", alignItems: "center", gap: 12 }}>
                <span style={{ flex: 1, minWidth: 0 }}>
                  <span style={{ display: "block", fontSize: FONT_SIZES.small, fontWeight: 500, color: P.ink, lineHeight: 1.4, letterSpacing: TYPE.heading.letterSpacing, fontFamily: "var(--cb-font)" }}>{s.title}</span>
                  <span style={{ display: "block", fontSize: FONT_SIZES.caption, color: P.faint, fontFamily: "var(--cb-font)", marginTop: 3 }}>
                    {[s.authors, formatJournalName(s.journal), s.year].filter(Boolean).join(" · ")}
                  </span>
                </span>
                <UISelect P={P} accent={accent} value={s.collectionId || ""} onChange={(v) => onMoveSource(s, v || null)}
                  options={[{ value: "", label: "Uncategorized" }, ...collections.map((c) => ({ value: c.id, label: c.name }))]}
                  ariaLabel={`Move "${s.title}" to a collection`} style={{ fontSize: FONT_SIZES.caption, flexShrink: 0 }} />
              </div>
            ))}
          </div>
        </div>
    </>
  );

  /* Commit 88 — the two-column page cannot survive 390px: its 210px fixed
     rail plus a content column left about 120px for paper titles, which
     wrapped to one word — often one letter — per line. On a narrow page it
     stacks: the collection list on top at natural height, its contents
     below. */
  if (page) {
    return (
      <div style={{ width: "100%" }}>
        <div style={narrow
          ? { background: P.surface, borderRadius: RADIUS.lg, width: "100%", display: "flex", flexDirection: "column", border: `1px solid ${P.line}`, overflow: "hidden", outline: "none" }
          : { background: P.surface, borderRadius: RADIUS.lg, width: "100%", height: "min(640px, 68vh)", display: "flex", border: `1px solid ${P.line}`, overflow: "hidden", outline: "none" }}>
          {content}
        </div>
      </div>
    );
  }
  return (
    <Dialog label="Collections" onClose={close} zIndex={Z.dialog} width={880}
      /* Escape in the rename input cancels the rename (the input's own
         stopPropagation can no longer beat the primitive's capture-phase
         listener); anywhere else it closes the dialog, as before. */
      onEscape={() => { if (renamingId) setRenamingId(null); else close(); }}
      panelStyle={{
        background: P.bg, borderRadius: RADIUS.md, maxHeight: "85dvh", display: "flex",
        boxShadow: "none", border: `1px solid ${P.line}`,
        overflow: "hidden", outline: "none",
      }}
    >
      {content}
    </Dialog>
  );
}

// Compare view — two History threads shown side by side. Deliberately just
// two: past three-plus and the useful comparison ("did these two questions
// get consistent answers?") turns into a horizontal-scrolling mess instead
// of something actually readable.
function CompareModal({ P, accent, at, S, history, close }) {
  const [leftId, setLeftId] = useState(history[0]?.id || "");
  const [rightId, setRightId] = useState(history[1]?.id || "");
  const left = history.find((h) => h.id === leftId);
  const right = history.find((h) => h.id === rightId);
  const noop = () => {};
  const Picker = ({ value, onChange, exclude }) => (
    <UISelect P={P} accent={accent} value={value} onChange={onChange}
      options={[{ value: "", label: "Choose an investigation…" }, ...history.filter((h) => h.id !== exclude).map((h) => ({ value: h.id, label: h.title }))]}
      ariaLabel="Choose an investigation to compare" style={{ width: "100%" }} />
  );
  const Column = ({ entry }) => (
    <div style={{ flex: 1, minWidth: 0, overflowY: "auto", padding: 18 }}>
      {entry ? (entry.turns || []).map((t, ti) => (
        // interactive=false — this is a read-only side-by-side replay of a
        // past investigation, and there's no live `ask` or network-graph
        // state here to wire "Continue the investigation" / "Source
        // network" up to, so Turn hides those controls entirely instead of
        // rendering buttons that quietly do nothing when clicked.
        <Turn key={t.id ?? ti} t={t} P={P} accent={accent} at={at} S={S} last={ti === entry.turns.length - 1} hoverCite={null} setHoverCite={noop} citationStyle="apa" setCitationStyle={noop} interactive={false} />
      )) : <div style={{ fontSize: FONT_SIZES.small, color: P.faint, textAlign: "center", padding: "60px 0" }}>Pick an investigation to compare.</div>}
    </div>
  );
  return (
    <Dialog label="Compare investigations" onClose={close} zIndex={Z.dialog} width={1100}
      panelStyle={{
        background: P.bg, borderRadius: RADIUS.md, height: "85dvh", display: "flex",
        flexDirection: "column", boxShadow: "none",
        border: `1px solid ${P.line}`, overflow: "hidden", outline: "none",
      }}
    >
        <div style={{ padding: "16px 24px", borderBottom: `1px solid ${P.line}`, display: "flex", alignItems: "center", gap: 16 }}>
          <div style={{ fontSize: FONT_SIZES.body, fontWeight: 500, color: P.ink, flexShrink: 0 }}>Compare</div>
          <div style={{ flex: 1 }}><Picker value={leftId} onChange={setLeftId} exclude={rightId} /></div>
          <div style={{ flex: 1 }}><Picker value={rightId} onChange={setRightId} exclude={leftId} /></div>
          <button onClick={close} aria-label="Close" style={{ background: "none", border: "none", color: P.faint, cursor: "pointer", padding: 13, display: "inline-flex", flexShrink: 0 }}><Icon name="close" size={18} /></button>
        </div>
        <div style={{ flex: 1, display: "flex", minHeight: 0 }}>
          <Column entry={left} />
          <div style={{ width: 1, background: P.line, flexShrink: 0 }} />
          <Column entry={right} />
        </div>
    </Dialog>
  );
}

// Source network graph — a small hand-rolled force layout (no charting
// library; the whole thing is under 100 lines and this is the only place in
// the app that needs one). Honest about what it actually shows: there's no
// real citation-graph data available here (that would mean fetching and
// cross-referencing every source's own reference list, which none of the 14
// upstream APIs hand back in one call) — so edges connect sources that
// share a journal, and every node also links faintly to the single
// highest-relevance source as a hub, so the layout stays readable instead
// of turning into scattered islands. Node size = relevance score.
/* ════════════════════════════════════════════════════════════
   CITATION NETWORK — who cites whom, for real

   The old network drew edges from a same-journal heuristic: two papers
   in the same journal got a line between them. That is a fabricated
   relationship presented as a finding. Gone.

   Every edge here is a real citation from OpenAlex reference lists
   (t.evidenceStructure, the same data behind Citation Threads).
   Thread nodes are matched to sources by DOI, falling back to title.
   No threads, no edges — the empty state says so honestly.

   Layout is deterministic: papers on a circle, ordered by citation
   number, no physics simulation, nothing moves. Node size reflects
   in-set in-degree (how many of these papers cite it). Edges are warm
   gray: structural citations with no stance data yet, so no stance
   colors are claimed.
   ════════════════════════════════════════════════════════════ */

function cleanDoi(s) {
  return String(s || "")
    .replace(/^https?:\/\/(dx\.)?doi\.org\//i, "")
    .toLowerCase()
    .replace(/[.,;)\]]+$/, "")
    .trim();
}

function threadNodesToSources(threadNodes, sources) {
  const doiToSource = new Map();
  (sources || []).forEach((s, i) => {
    const m = String(s.url || "").match(/doi\.org\/(10\.[^\s?#]+)/i);
    const d = cleanDoi(m ? m[1] : "");
    if (d) doiToSource.set(d, i);
  });
  const titleToSource = new Map();
  (sources || []).forEach((s, i) => {
    const t = String(s.title || "").toLowerCase().replace(/\s+/g, " ").trim().slice(0, 80);
    if (t && !titleToSource.has(t)) titleToSource.set(t, i);
  });
  const map = new Map();
  (threadNodes || []).forEach((n, ti) => {
    const d = cleanDoi(n.doi || "");
    if (d && doiToSource.has(d)) { map.set(ti, doiToSource.get(d)); return; }
    const t = String(n.title || "").toLowerCase().replace(/\s+/g, " ").trim().slice(0, 80);
    if (t && titleToSource.has(t)) map.set(ti, titleToSource.get(t));
  });
  return map;
}

function NetworkGraphBody({ P, accent, sources, threadsData, compact = false, onOpenPaper = () => {} }) {
  const [hoverIdx, setHoverIdx] = useState(null);
  const shown = (sources || []).slice(0, 18);

  const layout = useMemo(() => {
    const n = shown.length;
    const cx = 300, cy = 215, R = Math.min(165, 60 + n * 7);
    const pos = shown.map((s, i) => {
      const a = -Math.PI / 2 + (i / Math.max(n, 1)) * Math.PI * 2;
      return { x: cx + Math.cos(a) * R, y: cy + Math.sin(a) * R * 0.82 };
    });
    const nodeToSource = threadNodesToSources(threadsData && threadsData.threadNodes, shown);
    const edges = [];
    const indeg = new Array(n).fill(0);
    const seen = new Set();
    for (const t of (threadsData && threadsData.threads) || []) {
      const a = nodeToSource.get(t.from);
      const b = nodeToSource.get(t.to);
      if (a == null || b == null || a === b) continue;
      const key = a + ">" + b;
      if (seen.has(key)) continue;
      seen.add(key);
      edges.push([a, b]);
      indeg[b] += 1;
    }
    return { pos, edges, indeg };
  }, [sources, threadsData]);
  const pos = layout.pos, edges = layout.edges, indeg = layout.indeg;

  const sizeFor = (i) => 7 + Math.min(9, indeg[i] * 3);
  const edgeColor = STANCE_COLORS.mentioning;

  const edgePath = (a, b) => {
    const p1 = pos[a], p2 = pos[b];
    const mx = (p1.x + p2.x) / 2, my = (p1.y + p2.y) / 2;
    const dx = mx - 300, dy = my - 215;
    const len = Math.max(1, Math.hypot(dx, dy));
    const bow = 22;
    const qx = mx + (dx / len) * bow, qy = my + (dy / len) * bow;
    return "M " + p1.x.toFixed(1) + " " + p1.y.toFixed(1) + " Q " + qx.toFixed(1) + " " + qy.toFixed(1) + " " + p2.x.toFixed(1) + " " + p2.y.toFixed(1);
  };

  if (!edges.length) {
    return (
      <div className="cb-fade" style={{ padding: compact ? "10px 0" : "18px 0" }}>
        <div style={{ fontSize: FONT_SIZES.small, color: P.ink2, fontFamily: "var(--cb-font)", lineHeight: 1.6 }}>
          No direct citations between these papers.
        </div>
        <div style={{ fontSize: FONT_SIZES.caption, color: P.faint, fontFamily: "var(--cb-font)", marginTop: 4, lineHeight: 1.6 }}>
          Checked against OpenAlex reference lists. Papers can agree without citing each other.
        </div>
      </div>
    );
  }

  const hot = new Set();
  if (hoverIdx != null) {
    hot.add(hoverIdx);
    for (const [a, b] of edges) {
      if (a === hoverIdx) hot.add(b);
      if (b === hoverIdx) hot.add(a);
    }
  }

  return (
    <div className="cb-fade">
      <svg viewBox="0 0 600 430" style={{ width: "100%", height: compact ? 320 : 420, display: "block" }} role="img"
        aria-label={"Citation network: " + edges.length + " citation links among " + shown.length + " papers, from OpenAlex reference lists."}>
        <defs>
          <marker id="cb-net-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
            <path d="M 0 1 L 9 5 L 0 9" fill="none" stroke={edgeColor} strokeWidth="1.4" opacity="0.7" />
          </marker>
        </defs>
        {edges.map(([a, b], i) => {
          const lit = hoverIdx == null || a === hoverIdx || b === hoverIdx;
          return (
            <path key={i} d={edgePath(a, b)} fill="none"
              stroke={edgeColor} strokeWidth={lit ? 1.3 : 0.8}
              opacity={lit ? 0.75 : 0.28} markerEnd="url(#cb-net-arrow)"
              style={{ transition: "opacity 150ms ease" }} />
          );
        })}
        {pos.map((p, i) => {
          const s = shown[i] || {};
          const lit = hoverIdx == null || hot.has(i);
          const label = "[" + (i + 1) + "] " + (s.title || "Untitled source") + (indeg[i] ? " \u00b7 cited by " + indeg[i] + " in this set" : "");
          return (
            <g key={i}
              tabIndex={0} role="button" aria-label={label + ". Activate to open the paper."}
              onClick={() => onOpenPaper(i + 1)}
              onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); onOpenPaper(i + 1); } }}
              onMouseEnter={() => setHoverIdx(i)} onMouseLeave={() => setHoverIdx(null)}
              onFocus={() => setHoverIdx(i)} onBlur={() => setHoverIdx(null)}
              style={{ cursor: "pointer", opacity: lit ? 1 : 0.35, transition: "opacity 150ms ease" }}>
              <title>{label}</title>
              <circle cx={p.x} cy={p.y} r={sizeFor(i) + 7} fill="transparent" />
              <circle cx={p.x} cy={p.y} r={sizeFor(i)} fill={hot.has(i) || hoverIdx === i ? accent : withAlpha(accent, 0.55)} stroke={P.bg} strokeWidth={2} />
              <text x={p.x} y={p.y - sizeFor(i) - 7} textAnchor="middle"
                fill={lit ? P.ink2 : P.faint}
                style={{ fontFamily: "var(--cb-font)", fontSize: FONT_SIZES.caption, fontWeight: 500, fontVariantNumeric: "tabular-nums", pointerEvents: "none" }}>
                {i + 1}
              </text>
            </g>
          );
        })}
      </svg>
      <div style={{ padding: compact ? "8px 0 0" : "0 0 4px", minHeight: 40 }}>
        {hoverIdx !== null && pos[hoverIdx] ? (
          <div style={{ fontSize: FONT_SIZES.small, color: P.ink2, lineHeight: 1.5, fontFamily: "var(--cb-font)" }}>
            <strong style={{ color: accent }}>[{hoverIdx + 1}]</strong> {shown[hoverIdx].title}
            {shown[hoverIdx].year ? <span style={{ color: P.faint }}> {"\u00b7"} {shown[hoverIdx].year}</span> : null}
            {indeg[hoverIdx] ? <span style={{ color: P.faint }}> {"\u00b7"} cited by {indeg[hoverIdx]} in this set</span> : null}
          </div>
        ) : (
          <div style={{ fontSize: FONT_SIZES.micro, color: P.faint, fontFamily: "var(--cb-font)", lineHeight: 1.6 }}>
            <span style={{ display: "inline-block", width: 18, height: 1.5, background: STANCE_COLORS.mentioning, verticalAlign: "middle", marginRight: 6, opacity: 0.8 }} />
            a line means the paper cites the other {"\u00b7"} from OpenAlex reference lists {"\u00b7"} bigger node, cited more in this set {"\u00b7"} select a node to open the paper
          </div>
        )}
      </div>
    </div>
  );
}


function SourceNetworkGraph({ P, accent, at, sources, threadsData, onOpenPaper = () => {}, close }) {
  // The chrome is always dark glass; the graph body gets a dark palette so
  // node halos and hairlines read on it in either page theme.
  const darkP = P.dark ? P : PALETTES.Dark;
  return (
    <ModalChrome media label="Citation network" eyebrow="Evidence" title="How these papers cite each other" accent={accent} width={880} onClose={close}>
      <div style={{ padding: "6px 2px 0" }}>
        <NetworkGraphBody P={darkP} accent={accent} sources={sources} threadsData={threadsData} onOpenPaper={onOpenPaper} />
      </div>
    </ModalChrome>
  );
}
/* ══════════════════════════════════════════════════════════════════
   Commit 92 — the concept illustrations are gone.

   That feature sent the question to a text-to-image endpoint and showed
   whatever came back. It was labelled honestly ("not a data figure from
   the cited papers"), but the label was doing a lot of work: what it
   actually produced was a decorative picture with no relationship to the
   evidence, on a screen whose entire claim is that everything on it
   traces to a real source. On a research instrument that is worse than
   nothing — it is the one element that could make a careful answer look
   unserious.

   Replaced with the thing a reader of a cited answer actually wants and
   could not previously get: the studies behind the answer laid out side
   by side, so you can see at a glance that three of the four are reviews,
   or that the one disagreeing result is also the smallest.

   Every column is derived from data already retrieved — nothing is
   generated, nothing is inferred, nothing is fetched. A sample size is
   shown ONLY where the abstract states one in a form that can be read
   literally; a design is shown only where the abstract names it. Blank
   is a legitimate answer and appears as the words Not stated, because
   "we could not determine this" is information and guessing would defeat
   the purpose.
   ══════════════════════════════════════════════════════════════════ */

// Design vocabulary, strongest evidence first — the first match wins, so
// "systematic review of randomized trials" is classified as the review it
// is rather than as a trial.
const STUDY_DESIGNS = [
  [/\bmeta-?analys/i, "Meta-analysis", 6],
  [/\bsystematic review/i, "Systematic review", 6],
  [/\bscoping review\b|\bnarrative review\b|\bliterature review\b|\breview\b/i, "Review", 3],
  [/\brandomi[sz]ed controlled trial\b|\bRCT\b|\brandomi[sz]ed[, ]/i, "Randomised trial", 5],
  [/\bcrossover (trial|design|study)\b/i, "Crossover trial", 5],
  [/\bcohort (study|design)\b|\bprospective cohort\b|\blongitudinal study\b/i, "Cohort", 4],
  [/\bcase[- ]control\b/i, "Case-control", 4],
  [/\bcross[- ]sectional\b|\bsurvey (of|study)\b/i, "Cross-sectional", 2],
  [/\bcase (report|series)\b/i, "Case report", 1],
  [/\bin vivo\b|\bmouse\b|\bmurine\b|\brat\b|\bmice\b|\bzebrafish\b|\bprimate\b/i, "Animal", 2],
  [/\bin vitro\b|\bcell (line|culture)\b|\bassay\b/i, "In vitro", 2],
  [/\bmodel(ling|ing)\b|\bsimulation\b|\bcomputational\b/i, "Modelling", 2],
];

function studyDesign(source) {
  const hay = [source && source.abstract, source && source.title].filter(Boolean).join(" ");
  if (!hay) return null;
  for (const [re, label, rank] of STUDY_DESIGNS) {
    if (re.test(hay)) return { label, rank };
  }
  return null;
}

/* Sample size, read literally or not at all.

   The patterns below each require the abstract to state the number in a
   form that unambiguously means "how many were studied": n = 420, "420
   participants", "a total of 420 patients". A bare number near the word
   "patients" is not enough — abstracts are full of numbers (doses, years,
   percentages, confidence bounds) and a wrong sample size on a comparison
   table is far more damaging than a blank one. */
function sampleSize(source) {
  const a = String((source && source.abstract) || "");
  if (!a) return null;
  const pats = [
    /\bn\s*=\s*([\d][\d,]{1,7})\b/i,
    /\b(?:a\s+)?total of\s+([\d][\d,]{1,7})\s+(?:participants|patients|subjects|individuals|adults|children|women|men|animals|mice|rats|samples|studies|trials)\b/i,
    /\b([\d][\d,]{1,7})\s+(?:participants|patients|subjects|individuals|healthy volunteers)\b/i,
    /\b(?:included|enrolled|recruited|analysed|analyzed)\s+([\d][\d,]{1,7})\s+(?:participants|patients|subjects|individuals|studies|trials|articles|records)\b/i,
  ];
  for (const re of pats) {
    const m = a.match(re);
    if (!m) continue;
    const n = parseInt(String(m[1]).replace(/,/g, ""), 10);
    // A "sample" of 1 or of ten million is a parsing accident, not a study.
    if (Number.isFinite(n) && n >= 2 && n <= 5000000) return n;
  }
  return null;
}

/* Shared by the evidence table modal and the inline Evidence section:
   one row per cited source — design read from the abstract, sample size
   where stated, year and citation count where carried. Pure. */
function buildEvidenceRows(sources) {
  return (sources || []).map((s, i) => ({
    i: i + 1,
    src: s,
    design: studyDesign(s),
    n: sampleSize(s),
    year: Number(s.year) || null,
    citations: typeof s.citations === "number" ? s.citations : null,
  }));
}

function sortEvidenceRows(rows, sortKey) {
  const r = rows.slice();
  if (sortKey === "n") return r.sort((a, b) => (b.n || -1) - (a.n || -1));
  if (sortKey === "year") return r.sort((a, b) => (b.year || 0) - (a.year || 0));
  if (sortKey === "citations") return r.sort((a, b) => (b.citations || -1) - (a.citations || -1));
  if (sortKey === "design") return r.sort((a, b) => ((b.design && b.design.rank) || 0) - ((a.design && a.design.rank) || 0));
  return r.sort((a, b) => a.i - b.i); // as cited
}

/* ══════════════════════════════════════════════════════════════════
   Evidence table (inline): rows = papers, columns = extracted fields.

   The prose answer is what Cerebrum speaks; the table is what a grad
   student doing a lit review actually needs — every study side by side,
   every cell traceable to a sentence in the paper. Same honesty rule as
   the evidence modal above: read literally from the abstract or say Not
   stated. Nothing is generated, nothing is inferred.

   Column sets follow the question type:
   - clinical: Population, Intervention, Outcome, Sample size
   - methods:  Technique, Sample, Key result
   - general:  Method, Key finding
   ══════════════════════════════════════════════════════════════════ */

// Safe sentence splitter (no lookbehind — works everywhere).
function evSentences(text) {
  const clean = String(text || "").replace(/\s+/g, " ").trim();
  if (!clean) return [];
  const out = [];
  const parts = clean.split(/([.!?])\s+/);
  let cur = "";
  for (let i = 0; i < parts.length; i += 2) {
    cur += (parts[i] || "") + (parts[i + 1] || "");
    if (cur.trim().length > 12) { out.push(cur.trim()); cur = ""; }
  }
  if (cur.trim().length > 12) out.push(cur.trim());
  return out;
}

function evFirstMatch(sents, re) {
  for (const s of sents) { if (re.test(s)) return s; }
  return "";
}

function evTruncate(s, max) {
  const t = String(s || "").trim();
  if (t.length <= max) return t;
  return t.slice(0, max - 1).trimEnd() + "…";
}

// Population: the sentence that says who was studied.
function extractPopulation(source) {
  const sents = evSentences(source && source.abstract);
  return evFirstMatch(sents, /\b(patients|participants|subjects|volunteers|adults|children|infants|cohort|women|men)\b/i);
}

// Intervention: the sentence that says what was done to them.
function extractIntervention(source) {
  const sents = evSentences(source && source.abstract);
  return evFirstMatch(sents, /\b(treated|treatment|received|administered|dose|dosing|intervention|therapy|given)\b/i);
}

// Outcome: the sentence that says what changed.
function extractOutcome(source) {
  const sents = evSentences(source && source.abstract);
  return evFirstMatch(sents, /\b(reduced|improved|increased|decreased|outcome|efficacy|effective|significant|compared|versus)\b/i);
}

// Technique/method: the sentence that says how the work was done.
function extractTechnique(source) {
  const sents = evSentences(source && source.abstract);
  return evFirstMatch(sents, /\b(we |method|methods|using|used|performed|conducted|measured|analyzed|analysed|assessed|reared|synthesized|reaction|assay|protocol)\b/i)
    || sents[0] || "";
}

// Key finding: the tldr when the backend wrote one, else the closing
// sentence of the abstract (results live at the end), else the opener.
function extractKeyFinding(source) {
  if (source && source.tldr && String(source.tldr).trim()) return String(source.tldr).trim();
  const sents = evSentences(source && source.abstract);
  if (!sents.length) return "";
  return sents[sents.length - 1] || sents[0] || "";
}

function detectTableSpec(question) {
  const q = String(question || "").toLowerCase();
  if (/\b(treatment|therapy|therap|drug|medication|efficacy|patients|clinical|trial|placebo|dosage|dose|intervention|versus|reduces?|improves?|effective)\b/.test(q)) return "clinical";
  if (/\b(method|technique|approach|protocol|synthesis|reaction|assay|procedure|how (do|does|is|are|was|were))\b/.test(q)) return "methods";
  return "general";
}

const TABLE_SPECS = {
  clinical: [
    { key: "population", label: "Population", extract: extractPopulation, width: 190 },
    { key: "intervention", label: "Intervention", extract: extractIntervention, width: 190 },
    { key: "outcome", label: "Outcome", extract: extractOutcome, width: 200 },
    { key: "n", label: "Sample", extract: (s) => { const n = sampleSize(s); return n != null ? "n = " + n.toLocaleString("en-US") : ""; }, width: 90, numeric: true },
  ],
  methods: [
    { key: "technique", label: "Technique", extract: extractTechnique, width: 220 },
    { key: "n", label: "Sample", extract: (s) => { const n = sampleSize(s); return n != null ? "n = " + n.toLocaleString("en-US") : ""; }, width: 90, numeric: true },
    { key: "finding", label: "Key result", extract: extractKeyFinding, width: 260 },
  ],
  general: [
    { key: "method", label: "Method", extract: extractTechnique, width: 230 },
    { key: "finding", label: "Key finding", extract: extractKeyFinding, width: 300 },
  ],
};

/* Inline evidence table: same data as the modal, but in the reading
   column under the answer, toggled against the prose view. Rows keep
   citation order. Every cell that names a value is a verbatim abstract
   sentence (truncated); blanks read as Not stated, never guesses. */
function EvidenceTableAnswerView({ t, P, accent, onOpenPaper = () => {} }) {
  const sources = (t && t.sources) || [];
  const specKey = detectTableSpec(t && t.q);
  const spec = TABLE_SPECS[specKey] || TABLE_SPECS.general;
  const dash = <span style={{ color: P.faint, opacity: 0.6 }}>Not stated</span>;
  const th = {
    textAlign: "left", padding: "0 8px 8px 0", fontSize: FONT_SIZES.micro,
    fontWeight: 500, color: P.faint, fontFamily: "var(--cb-font)", whiteSpace: "nowrap",
    letterSpacing: "normal", textTransform: "none",
  };
  const td = {
    padding: "12px 8px 12px 0", fontSize: FONT_SIZES.caption, color: P.ink,
    verticalAlign: "top", fontFamily: "var(--cb-font)", borderTop: `1px solid ${P.line}`,
    lineHeight: 1.5,
  };
  const specLabel = specKey === "clinical" ? "Clinical columns" : specKey === "methods" ? "Methods columns" : "General columns";
  return (
    <div>
      <div style={{ display: "flex", alignItems: "baseline", gap: 10, marginBottom: 6, flexWrap: "wrap" }}>
        <div style={{ fontSize: FONT_SIZES.body, fontWeight: 500, color: P.ink, fontFamily: "var(--cb-font)" }}>
          Evidence table
        </div>
        <div style={{ fontSize: FONT_SIZES.caption, color: P.faint, fontFamily: "var(--cb-font)" }}>
          {sources.length} studies · {specLabel} · every cell from the paper's abstract
        </div>
      </div>
      <div style={{ overflowX: "auto" }}>
        <table style={{ width: "100%", borderCollapse: "collapse", minWidth: 620 }}>
          <thead>
            <tr>
              <th style={{ ...th, width: 28 }}>#</th>
              <th style={th}>Study</th>
              {spec.map((c) => (
                <th key={c.key} style={{ ...th, width: c.width, textAlign: c.numeric ? "right" : "left" }}>{c.label}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {sources.map((s, i) => (
              <tr key={i}>
                <td style={{ ...td, color: accent, fontWeight: 500, whiteSpace: "nowrap" }}>{i + 1}</td>
                <td style={{ ...td, minWidth: 150 }}>
                  <button type="button" onClick={() => onOpenPaper(i + 1)} title={(s && s.title) || "Open this paper"}
                    style={{ background: "none", border: "none", padding: 0, cursor: "pointer", textAlign: "left", fontSize: FONT_SIZES.caption, fontWeight: 500, color: P.ink, fontFamily: "var(--cb-font)", lineHeight: 1.45 }}>
                    {s && s.title ? renderCleanTitle(evTruncate(s.title, 90)) : "Untitled paper"}
                  </button>
                  <div style={{ color: P.faint, marginTop: 3, fontSize: FONT_SIZES.micro }}>
                    {[s && s.year].filter(Boolean).join("")}
                    {s && s.authors ? ` · ${evTruncate(String(s.authors).split(";")[0], 28)}` : ""}
                  </div>
                </td>
                {spec.map((c) => {
                  const v = evTruncate(c.extract(s), 170);
                  return (
                    <td key={c.key} style={{ ...td, textAlign: c.numeric ? "right" : "left", fontVariantNumeric: "tabular-nums" }}>
                      {v ? v : dash}
                    </td>
                  );
                })}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

function EvidenceTableModal({ P, accent, at, sources, close }) {
  const [sortKey, setSortKey] = useState("cited");

  const rows = useMemo(() => buildEvidenceRows(sources), [sources]);
  const sorted = useMemo(() => sortEvidenceRows(rows, sortKey), [rows, sortKey]);

  const withN = rows.filter((r) => r.n != null);
  const withDesign = rows.filter((r) => r.design);

  const th = { textAlign: "left", padding: "0 0 8px", fontSize: FONT_SIZES.micro, fontWeight: 500, color: P.faint, fontFamily: "var(--cb-font)", whiteSpace: "nowrap" };
  const td = { padding: "12px 0", fontSize: FONT_SIZES.caption, color: P.ink, verticalAlign: "top", fontFamily: "var(--cb-font)", borderTop: `1px solid ${P.line}` };

  return (
    <Dialog label="The evidence, side by side" onClose={close} zIndex={Z.dialog} width={880}
      panelStyle={{
        background: P.bg, borderRadius: RADIUS.lg, maxHeight: "86dvh", display: "flex",
        flexDirection: "column", boxShadow: "none",
        border: `1px solid ${P.line}`, outline: "none", overflow: "hidden",
      }}
    >
        <div style={{ padding: "16px 22px 16px", borderBottom: `1px solid ${P.line}`, display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: 12, flexShrink: 0 }}>
          <div style={{ minWidth: 0 }}>
            <div style={{ fontSize: FONT_SIZES.body, fontWeight: 500, color: P.ink, fontFamily: "var(--cb-font)", letterSpacing: TYPE.heading.letterSpacing }}>The evidence, side by side</div>
            <div style={{ fontSize: FONT_SIZES.caption, color: P.faint, marginTop: 3, lineHeight: 1.5 }}>
              {rows.length} source{rows.length === 1 ? "" : "s"} behind this answer
              {withDesign.length > 0 && ` · design read for ${withDesign.length}`}
              {withN.length > 0 && ` · sample size stated in ${withN.length}`}
            </div>
          </div>
          <button onClick={close} aria-label="Close" style={{ background: "none", border: "none", color: P.faint, cursor: "pointer", padding: 13, display: "inline-flex", flexShrink: 0 }}><Icon name="close" size={18} /></button>
        </div>

        <div style={{ alignItems: "center", padding: "12px 22px 0", flexShrink: 0, display: "flex", gap: 6, flexWrap: "wrap" }}>
          {[["cited", "As cited"], ["design", "Strongest design"], ["n", "Largest sample"], ["year", "Newest"], ["citations", "Most cited"]].map(([k, label]) => (
            <UIButton P={P} variant="ghost" key={k} onClick={() => setSortKey(k)} aria-pressed={sortKey === k}
              style={{ minHeight: 44,
                padding: "5px 12px", borderRadius: RADIUS.pill, cursor: "pointer",
                fontSize: FONT_SIZES.caption, fontWeight: 500, fontFamily: "var(--cb-font)",
                background: sortKey === k ? withAlpha(accent, 0.14) : "transparent",
                color: sortKey === k ? P.ink : P.ink2,
                border: `1px solid ${sortKey === k ? withAlpha(accent, 0.42) : P.line}`,
              }}>{label}</UIButton>
          ))}
        </div>

        <div style={{ overflowY: "auto", overflowX: "auto", padding: "8px 22px 22px", flex: 1, minHeight: 0 }}>
          <table style={{ width: "100%", borderCollapse: "collapse", minWidth: 560 }}>
            <thead>
              <tr>
                <th style={{ ...th, width: 26 }}>#</th>
                <th style={th}>Study</th>
                <th style={{ ...th, width: 130 }}>Design</th>
                <th style={{ ...th, width: 76, textAlign: "right" }}>Sample</th>
                <th style={{ ...th, width: 58, textAlign: "right" }}>Year</th>
              </tr>
            </thead>
            <tbody>
              {sorted.map((r) => (
                <tr key={r.i}>
                  <td style={{ ...td, color: accent, fontWeight: 500, fontFamily: "var(--cb-font)" }}>{r.i}</td>
                  <td style={{ ...td, paddingRight: 14 }}>
                    <a href={safeHref(r.src.url)} target="_blank" rel="noreferrer" style={{ color: P.ink, textDecoration: "none", fontWeight: 500, lineHeight: 1.4, display: "block" }}>
                      {r.src.title ? renderCleanTitle(r.src.title) : r.src.url}
                    </a>
                    <div style={{ color: P.faint, marginTop: 3, fontSize: FONT_SIZES.micro, lineHeight: 1.45 }}>
                      {[r.src.authors, formatJournalName(r.src.journal)].filter(Boolean).join(" · ")}
                      {(() => { const c = formatCitationCount(r.citations, r.src.year, "citation"); return c ? ` · ${c}` : ""; })()}
                    </div>
                  </td>
                  <td style={td}>
                    {r.design ? (
                      <span style={{
                        display: "inline-block", padding: "3px 9px", borderRadius: RADIUS.pill,
                        fontSize: FONT_SIZES.micro, fontWeight: 500, whiteSpace: "nowrap",
                        // Stronger designs read louder. Rank is the crude
                        // evidence-hierarchy position, not a quality score.
                        color: r.design.rank >= 5 ? accent : P.ink2,
                        background: r.design.rank >= 5 ? withAlpha(accent, 0.12) : (P.dark ? "rgba(255,255,255,0.05)" : "rgba(0,0,0,0.04)"),
                        border: `1px solid ${r.design.rank >= 5 ? withAlpha(accent, 0.3) : P.line}`,
                      }}>{r.design.label}</span>
                    ) : <span style={{ color: P.faint }}>Not stated</span>}
                  </td>
                  <td style={{ ...td, textAlign: "right", fontFamily: "var(--cb-font)", fontWeight: 500 }}>{r.n != null ? r.n.toLocaleString() : <span style={{ color: P.faint }}>Not reported</span>}</td>
                  <td style={{ ...td, textAlign: "right", fontFamily: "var(--cb-font)", color: P.ink2 }}>{r.year || <span style={{ color: P.faint }}>Unknown</span>}</td>
                </tr>
              ))}
            </tbody>
          </table>
          <div style={{ marginTop: 16, fontSize: FONT_SIZES.micro, color: P.faint, lineHeight: 1.6, fontFamily: "var(--cb-font)" }}>
            Design and sample size are read from each abstract as written. Not stated means the abstract did not give it, not that the study lacks one. Check the paper before relying on any row.
          </div>
        </div>
    </Dialog>
  );
}

/* ── Inline evidence: the table, network, and arc live under the answer
   as expanders now (modals demoted). The sort chips become a Segmented
   control, rows open the paper drawer, and the network/graph bodies are
   shared with their palette-accessible modals. ── */
function EvidenceTableInline({ sources, P, accent, onOpenPaper }) {
  const [sortKey, setSortKey] = useState("cited");
  const rows = useMemo(() => buildEvidenceRows(sources), [sources]);
  const sorted = useMemo(() => sortEvidenceRows(rows, sortKey), [rows, sortKey]);
  const th = { fontFamily: "var(--cb-font)", fontSize: FONT_SIZES.micro, fontWeight: 500, letterSpacing: "normal", textTransform: "none", color: P.faint, textAlign: "left", padding: "12px 12px", borderBottom: `1px solid ${P.line}`, position: "sticky", top: 0, background: P.surface, zIndex: Z.content, whiteSpace: "nowrap" };
  const td = { padding: "12px", borderBottom: `1px solid ${P.line}`, fontSize: FONT_SIZES.small, color: P.ink, verticalAlign: "top" };
  return (
    <div className="cb-fade">
      <div style={{ marginBottom: 12 }}>
        <SegControl value={sortKey} onChange={setSortKey} P={P} accent={accent}
          options={[{ id: "cited", label: "As cited" }, { id: "design", label: "Design" }, { id: "n", label: "Sample" }, { id: "year", label: "Year" }, { id: "citations", label: "Cited" }]} />
      </div>
      <div style={{ overflowX: "auto", maxHeight: 420, overflowY: "auto", border: `1px solid ${P.line}`, borderRadius: RADIUS.lg }}>
        <table style={{ width: "100%", borderCollapse: "collapse", minWidth: 560 }}>
          <thead><tr>
            <th style={{ ...th, width: 30 }}>#</th>
            <th style={th}>Study</th>
            <th style={{ ...th, width: 120 }}>Design</th>
            <th style={{ ...th, width: 70, textAlign: "right" }}>Sample</th>
            <th style={{ ...th, width: 56, textAlign: "right" }}>Year</th>
          </tr></thead>
          <tbody>
            {sorted.map((r) => (
              <tr key={r.i}>
                <td style={{ ...td, color: accent, fontWeight: 500, fontFamily: "var(--cb-font)" }}>{r.i}</td>
                <td style={{ ...td, paddingRight: 14 }}>
                  <button type="button" onClick={() => onOpenPaper(r.i)}
                    style={{ background: "none", border: "none", padding: 0, cursor: "pointer", textAlign: "left", color: P.ink, fontSize: FONT_SIZES.small, fontWeight: 500, lineHeight: 1.4, display: "block" }}>
                    {r.src.title ? renderCleanTitle(r.src.title) : r.src.url}
                  </button>
                  <div style={{ color: P.faint, marginTop: 3, fontSize: FONT_SIZES.micro, lineHeight: 1.45 }}>
                    {[r.src.authors, formatJournalName(r.src.journal)].filter(Boolean).join(" · ")}
                    {(() => { const c = formatCitationCount(r.citations, r.src.year, "citation"); return c ? ` · ${c}` : ""; })()}
                  </div>
                </td>
                <td style={td}>
                  {r.design ? (
                    <span style={{ display: "inline-block", padding: "3px 9px", borderRadius: RADIUS.pill, fontSize: FONT_SIZES.micro, fontWeight: 500, whiteSpace: "nowrap", fontFamily: "var(--cb-font)",
                      color: r.design.rank >= 5 ? accent : P.ink2,
                      background: r.design.rank >= 5 ? withAlpha(accent, 0.12) : (P.dark ? "rgba(255,255,255,0.05)" : "rgba(0,0,0,0.04)"),
                      border: `1px solid ${r.design.rank >= 5 ? withAlpha(accent, 0.3) : P.line}` }}>{r.design.label}</span>
                  ) : <span style={{ color: P.faint }}>Not stated</span>}
                </td>
                <td style={{ ...td, textAlign: "right", fontFamily: "var(--cb-font)", fontWeight: 500 }}>{r.n != null ? r.n.toLocaleString() : <span style={{ color: P.faint }}>Not reported</span>}</td>
                <td style={{ ...td, textAlign: "right", fontFamily: "var(--cb-font)", color: P.ink2 }}>{r.year || <span style={{ color: P.faint }}>Unknown</span>}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <div style={{ marginTop: 10, fontSize: FONT_SIZES.micro, color: P.faint, lineHeight: 1.6, fontFamily: "var(--cb-font)" }}>
        Design and sample size are read from each abstract as written. Not stated means the abstract did not give it, not that the study lacks one. Tap a study to open the paper.
      </div>
    </div>
  );
}

function EvidenceSection({ t, P, accent, evOpen, setEvOpen, onOpenPaper }) {
  const tabUid = useId().replace(/:/g, "");
  const sources = t.sources || [];
  const tabs = [
    ["table", "Table", `${sources.length} studies`],
    ["network", "Network", "cocitation"],
    ["arc", "Arc", "the long view"],
  ];
  /* The Evidence band (bibliography + videos) owns the "Evidence" name now,
     so this section is "Compare": the same tools, never a silent gap. */
  if (!sources.length) {
    return (
      <AnswerSection quiet eyebrow="Compare" title="The receipts, in one place" P={P} accent={accent}>
        <AnswerStateCard kicker="Nothing to compare" title="No studies to compare."
          body="The comparison tools need cited studies to work with. This answer cites none."
          P={P} accent={accent} />
      </AnswerSection>
    );
  }
  /* Pass 6: the compare views are quiet underlined text tabs — the same
     cb-tabrow pattern as the evidence band and the sources sort — not
     letterspaced caps buttons with slash separators. */
  return (
    <AnswerSection quiet eyebrow="Compare" title="The receipts, in one place" P={P} accent={accent}
      right={(
        <div className="cb-tabrow" role="tablist" aria-label="Compare views"
          onKeyDown={tabListKeyDown}
          onClick={(e) => { const b = e.target.closest(".cb-tab"); if (b) b.scrollIntoView({ block: "nearest", inline: "nearest" }); }}>
          {tabs.map(([id, label], idx) => (
            <button key={id} type="button" role="tab" aria-selected={evOpen === id} className="cb-tab"
              id={tabUid + "-tab-" + id} aria-controls={tabUid + "-panel"}
              tabIndex={evOpen === id || (!evOpen && idx === 0) ? 0 : -1}
              data-active={evOpen === id ? "true" : undefined}
              onClick={() => setEvOpen(evOpen === id ? null : id)}>
              {label}
            </button>
          ))}
        </div>
      )}>
      {/* One panel element for the whole switch: its content (including
          the closed state copy) is labelled by whichever tab is open. */}
      <div role="tabpanel" id={tabUid + "-panel"} aria-labelledby={evOpen ? tabUid + "-tab-" + evOpen : undefined}>
        {!evOpen && (
          <div style={{ fontSize: FONT_SIZES.small, color: P.ink2, lineHeight: 1.7 }}>
            {sources.length} cited {sources.length === 1 ? "study" : "studies"} underpin this answer. Compare them as a table, a cocitation network, or the arc of the literature over time.
          </div>
        )}
        {evOpen === "table" && <EvidenceTableInline sources={sources} P={P} accent={accent} onOpenPaper={onOpenPaper} />}
        {evOpen === "network" && <NetworkGraphBody P={P} accent={accent} sources={sources} threadsData={t.evidenceStructure} onOpenPaper={onOpenPaper} compact />}
        {evOpen === "arc" && <AnswerArc turn={t} P={P} accent={accent} />}
      </div>
    </AnswerSection>
  );
}

/* ── Video explainers as a darkroom filmstrip: sprocket ticks along the
   top edge, numbered 16:9 frames in a scroll-snap row. Hover (fine
   pointer only) previews the video muted after a beat; click opens the
   player modal. No runtime badge — the backend's video objects carry no
   duration data, and we don't invent one. ── */
function SprocketRow({ color }) {
  return (
    <div aria-hidden="true" style={{ display: "flex", gap: 10, justifyContent: "space-between", padding: "8px 16px 0" }}>
      {Array.from({ length: 28 }).map((_, i) => (
        <span key={i} style={{ width: 14, height: 8, borderRadius: RADIUS.sm, background: color, flexShrink: 0, opacity: 0.5 }} />
      ))}
    </div>
  );
}

function VideoFrame({ v, n, P, accent, onOpen }) {
  const [preview, setPreview] = useState(false);
  const [loaded, setLoaded] = useState(false);
  const timer = useRef(null);
  const reduced = usePrefersReducedMotion();
  /* The in-product Motion toggle (Settings → Sound & motion → Off) joins
     the OS signal: either one parks the hover preview and the transitions.
     The literal usePrefersReducedMotion() line above stays verbatim —
     tests/answer-experience.mjs pins this call site — so `still` is the
     effective flag the component actually branches on. */
  /* useReducedMotion is itself a hook, so it is called on every
     render and only its result joins the flag (crash fix,
     2026-10-15): as the right operand of || it was skipped
     whenever the OS signal was already true, so this component's
     hook count changed with the OS reduced motion setting and
     React could throw error #300. */
  const appReduced = useReducedMotion();
  const still = reduced || appReduced;
  const finePointer = typeof window !== "undefined" && window.matchMedia && window.matchMedia("(pointer: fine)").matches;
  // Immediate poster: derive hqdefault from the YouTube id when the video
  // carries one (the backend already sends them) — the poster is on screen
  // from the first paint, never waiting on the backend's thumbnail field,
  // which has been blank before. v.thumbnail stays as the fallback.
  const ytId = getYouTubeId(v) || v.id;
  const poster = ytId ? `https://i.ytimg.com/vi/${ytId}/hqdefault.jpg` : (v.thumbnail || null);
  const startPreview = () => {
    if (!finePointer || still || !ytId) return;
    if (timer.current) clearTimeout(timer.current);
    timer.current = setTimeout(() => setPreview(true), 380);
  };
  const stopPreview = () => {
    if (timer.current) clearTimeout(timer.current);
    setPreview(false);
    setLoaded(false);
  };
  useEffect(() => () => { if (timer.current) clearTimeout(timer.current); }, []);
  return (
    <div style={{ flex: "0 0 auto", width: 240, scrollSnapAlign: "start" }}>
      <button type="button" onClick={() => onOpen(v)} aria-label={`Play: ${v.title || "video"}`}
        onMouseEnter={startPreview} onMouseLeave={stopPreview} onFocus={startPreview} onBlur={stopPreview}
        style={{ display: "block", width: "100%", padding: 0, background: "#0a0c10", border: `1px solid rgba(255,255,255,0.1)`, borderRadius: RADIUS.md, overflow: "hidden", cursor: "pointer", textAlign: "left", transition: still ? "none" : "border-color 280ms ease, transform 280ms ease" }}
        onMouseOver={(e) => { e.currentTarget.style.borderColor = withAlpha(accent, 0.6); }}
        onMouseOut={(e) => { e.currentTarget.style.borderColor = "rgba(255,255,255,0.1)"; }}>
        <div style={{ position: "relative", width: "100%", aspectRatio: "16/9", background: "#0a0c10", overflow: "hidden" }}>
          {/* The poster stays mounted under the iframe; the iframe fades in
              over it once loaded — the frame never shows a black flash
              while the embed spins up. */}
          {poster && (
            <img src={poster} alt="" loading="lazy" draggable={false}
              style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover", display: "block" }}
              onError={(e) => { e.currentTarget.style.display = "none"; }} />
          )}
          {preview && ytId && (
            <iframe src={`https://www.youtube.com/embed/${ytId}?autoplay=1&mute=1&controls=0&rel=0&playsinline=1`}
              title="" tabIndex={-1} aria-hidden="true"
              onLoad={() => setLoaded(true)}
              style={{ position: "absolute", inset: 0, width: "100%", height: "100%", border: "none", pointerEvents: "none", opacity: loaded ? 1 : 0, transition: still ? "none" : "opacity 280ms ease" }} />
          )}
          {!preview && (
            <div style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center", background: "rgba(0,0,0,0.18)" }}>
              <div style={{ width: 36, height: 36, borderRadius: "50%", background: "rgba(10,14,32,0.65)", border: "1px solid rgba(255,255,255,0.35)", display: "flex", alignItems: "center", justifyContent: "center", color: "#fff" }}>
                <Icon name="play" size={13} />
              </div>
            </div>
          )}
          <span style={{ position: "absolute", top: 8, left: 10, fontFamily: "var(--cb-font)", fontSize: FONT_SIZES.micro, fontWeight: 500, color: "rgba(255,255,255,0.65)", letterSpacing: TRACKING.eyebrow }}>
            {String(n).padStart(2, "0")}
          </span>
        </div>
      </button>
      <div style={{ padding: "8px 2px 0" }}>
        <div style={{ fontSize: FONT_SIZES.small, fontWeight: 500, lineHeight: 1.35, color: P.ink, display: "-webkit-box", WebkitLineClamp: 2, WebkitBoxOrient: "vertical", overflow: "hidden" }}>{v.title}</div>
        {v.author && <div style={{ fontSize: FONT_SIZES.caption, color: P.faint, fontFamily: "var(--cb-font)", marginTop: 3, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{v.author}</div>}
      </div>
    </div>
  );
}

/* bare: strip the outer AnswerSection chrome — the Evidence band supplies
   the section header and tabs, so a nested eyebrow would double it. */
function VideoFilmstrip({ videos, P, accent, onOpen, bare = false }) {
  const shown = (videos || []).slice(0, 8);
  const note = (
    <div style={{ fontSize: FONT_SIZES.caption, color: P.faint, margin: "-4px 0 12px", fontFamily: "var(--cb-font)" }}>
      Background viewing: these videos are not cited as evidence above.
    </div>
  );
  const strip = (
    <div style={{ background: "#0b0d11", borderRadius: RADIUS.lg, border: `1px solid ${P.line}`, overflow: "hidden" }} className="cb-fade">
      <SprocketRow color="rgba(255,255,255,0.16)" />
      <div style={{ display: "flex", gap: 14, overflowX: "auto", padding: "12px 16px 6px", scrollSnapType: "x proximity", scrollbarWidth: "thin" }}>
        {shown.map((v, i) => <VideoFrame key={v.id || i} v={v} n={i + 1} P={P} accent={accent} onOpen={onOpen} />)}
      </div>
      <SprocketRow color="rgba(255,255,255,0.16)" />
      <div style={{ height: 10 }} />
    </div>
  );
  if (bare) return <div>{note}{strip}</div>;
  if (!shown.length) return null;
  return (
    <AnswerSection eyebrow={`Video explainers · ${shown.length}`} P={P} accent={accent}>
      {note}
      {strip}
    </AnswerSection>
  );
}

/* ════════════════════════════════════════════════════════════════
   TRENDING IN SCIENCE — a live, full-page editorial feed, honestly
   labeled as a preview. functions/api/trending.js fetches real, live
   articles (title, summary, real photo, real outlet, real link) from the
   Spaceflight News API — a free, keyless, publicly documented science-
   journalism feed — never an invented headline or an AI-generated stand-in
   image. Deliberately carries no "Fact-Checked" badge: unlike a single
   search answer, nothing here has gone through Cerebrum's fact-check pass,
   and a green shield here would claim a verification step that didn't
   happen. "Preview" is the accurate word for what this is. Used to be a
   centered modal (TrendingModal); now a real full-page view, matched to
   the rest of the App Shell migration.
   ════════════════════════════════════════════════════════════════ */
// Hero treatment for the lead story — a full-bleed image with the
// headline set directly over it, the way science.org's front page and
// Nebula's featured-show rail both lead with one large cinematic card
// before dropping into a grid, rather than just a bigger version of the
// same image-on-top-text-below card every other story uses.
/* Commit 63 — generated cover art.
   Only the spaceflight source ships an image_url; journals and preprint
   servers don't publish thumbnails at all. So every biology, chemistry and
   preprint card rendered as a large empty grey rectangle with a broken-image
   glyph — the exact screenshot Dusty sent. Three quarters of the feed
   looked broken purely because it wasn't space news.

   This draws a cover instead of faking a photo: a deterministic gradient
   seeded by the title (so a given article always looks the same, and
   adjacent cards never collide), the discipline named, and the source's
   initials set large. It reads as a designed cover rather than a missing
   asset, and it never misrepresents a paper with an unrelated stock image —
   which is the thing a science tool must not do. */
/* Commit 81 — person avatars that look chosen rather than defaulted.
   ---------------------------------------------------------------------
   An initial on a flat accent-tinted circle is what every product does
   when it has no photograph, and it reads exactly that way: a fallback.
   Keeping the initial is right — it is genuinely how you pick a name out
   of a list — but the surface behind it does not have to be the same flat
   wash for everybody.

   This hashes the name to a stable hue and paints a two-stop gradient at
   an angle derived from the same hash. Deterministic, so a person looks
   the same everywhere in the app and on every device; no request, no
   third-party avatar service (this app removed its Dicebear dependency in
   Commit 54 for exactly that reason); and it makes a roster of people
   look like a roster rather than a column of identical discs. */
/* ══════════════════════════════════════════════════════════════════
   Commit 87 — the tonal palette.

   avatarSkin() and coverFor() both used to hash a string into a FREE hue:
   `const hue = h % 360`. That one line is responsible for most of what
   reads as amateur in this app. A free hue guarantees that some fraction
   of content comes out neon magenta, mustard, or — the one that actually
   got reported — blood red, and it does so inside a product whose entire
   identity is a single sage green. A 620px red gradient at the top of
   Trending is not a design decision anybody made; it is a hash landing on
   hue 0, and it looks like an error state.

   Replaced with a hand-authored set of twelve tones that all sit in the
   same cool/earthy register as the brand: moss, teal, slate, indigo,
   steel, plum, clay, sand, pine, denim, fern, stone. No pure reds, no
   neons, nothing above 44% saturation. The hash now picks an INDEX into
   that set rather than a point on the colour wheel, so every generated
   surface is still stable and distinct per item, but every possible
   outcome was chosen by a person and belongs to the same family.

   Chroma stays low on purpose. These are backdrops for white text and for
   photography; they are meant to sit behind content, never to compete with
   the accent, which remains the only saturated colour in the product.
   ══════════════════════════════════════════════════════════════════ */
/* Moved to src/appUtils.js: TONES, toneIndex, avatarSkin */

function coverFor(item) {
  // A solid tonal field. The gradient here was a craft-pass survivor —
  // decorative gradients have no place on cards. The hand-authored tone
  // set is unchanged (see Commit 87 above), so every item still gets its
  // stable, chosen color; it just sits flat now, the way the avatar skins
  // already did.
  const t = TONES[toneIndex(item && (item.title || item.url))];
  return {
    background: `hsl(${t.h} ${t.s}% 15%)`,
    tone: `hsl(${t.h} ${t.s}% 46%)`,
    initials: (item.source || item.category || "CB").replace(/[^A-Za-z ]/g, "").split(/\s+/).filter(Boolean).slice(0, 2).map((w) => w[0].toUpperCase()).join("") || "CB",
  };
}

/* A few upstream source strings are legitimate ISO-4 abbreviations that
   read as truncation bugs ("Magn Reson Lett"). The strings stay exactly as
   the feed sent them — provenance is not ours to rewrite — but a hover
   reveals the full journal name where one is verified. */
const SOURCE_FULL_NAMES = {
  "Magn Reson Lett": "Magnetic Resonance Letters",
};

/* Trending provenance: press reporting is labelled as press, scholarly
   records as papers or preprints, from the feed's own category field
   (Europe PMC / bioRxiv / arXiv are scholarly; the Space category is
   press reporting). Press items carry "not synthesized" because the
   digest never runs them through the answer engine — only papers behind
   answers get that. */
function trendKind(item) {
  // Type is its own field now (paper, preprint, press, review). Older
  // cached payloads without one fall back to the category guess.
  const t = String((item && item.type) || "").toLowerCase();
  if (t === "press") return "Press item";
  if (t === "preprint") return "Preprint";
  if (t === "review") return "Review";
  if (t === "paper") return "Paper";
  const cat = String((item && item.category) || "").toLowerCase();
  if (cat === "space") return "Press item";
  if (cat === "preprints") return "Preprint";
  return "Paper";
}
function trendImageCredit(item) {
  const m = trendingMediaOf(item);
  if (!m || !m.credit) return null;
  return m.license ? `${m.credit} · ${m.license}` : m.credit;
}
function trendProvenance(item, generatedAt) {
  const kind = trendKind(item);
  const parts = [kind];
  if (item.source) parts.push(item.source);
  // Publication time is the item's own. The old line presented the
  // whole edition's build time as this article's indexing time; an
  // indexed time is only shown when the source reports one per item.
  if (item.publishedAt) parts.push(`Published ${relativeTime(new Date(item.publishedAt).getTime())}`);
  if (item.indexedAt) parts.push(`Indexed ${relativeTime(new Date(item.indexedAt).getTime())}`);
  if (kind === "Press item") parts.push("not synthesized");
  if (item.citedByCount > 0) parts.push(`Cited by ${item.citedByCount}`);
  // A reported zero is a state of its own — the count was checked and
  // nobody has cited the work yet — so it is named, while a missing
  // count (null) stays silent: no data must never read as a verdict.
  else if (item.citedByCount === 0) parts.push("No citations yet");
  // Persistence rides the same quiet line: a story in the edition
  // several days running says so; a first day story says nothing,
  // because on a young archive every story would read the same.
  const persistence = trendPersistenceLabel(item);
  if (persistence) parts.push(persistence);
  return parts.join(" · ");
}
/* A document analysis payload → renderable media or null. The analysis
   JSON always carries the media key on the final response, so absent =
   not attempted → nothing. */
function docMediaOf(summary) {
  if (!summary || typeof summary !== "object") return null;
  return verifiedMediaOf(summary.media);
}

/* Verified media figure — the only sanctioned way to show a trending or
   document image/video. Renders ONLY resolved media; a failed load removes
   the whole figure so a broken frame can never appear. Credit + license
   ride under the frame, linked when the backend supplies a credit URL.
   The one unverified input is the trending fallback (the item's own
   article image via trendingMediaOf): it renders with an "Unverified
   image" caption line beside whatever credit the fallback carries, so
   an unchecked picture is never dressed as a checked one.
   - `still`: video renders as its poster with a play badge (for use inside
     buttons/links where a <video> with controls would nest interactives).
   - `linkCredit`: false inside elements (like the hero button) where a
     nested <a> would be invalid. */
function MediaFigure({ P, media, title, still = false, linkCredit = true, aspect = "16/9", rounded = 12 }) {
  const [failed, setFailed] = useState(false);
  const [ready, setReady] = useState(false);
  // The modal reuses this component across stories: a failed or loaded
  // state from the previous story must never suppress or pre reveal
  // the next story's figure.
  useEffect(() => { setFailed(false); setReady(false); }, [media && media.url, media && media.poster]);
  if (!media || failed) return null;
  const creditHref = media.creditUrl && safeHref(media.creditUrl) !== "#" ? safeHref(media.creditUrl) : null;
  const showVideo = media.kind === "video" && !still;
  const stillSrc = media.kind === "video" ? media.poster || null : media.url;
  return (
    <figure style={{ margin: 0 }}>
      <div style={{
        position: "relative", aspectRatio: aspect, borderRadius: rounded, overflow: "hidden",
        background: P.dark ? "rgba(255,255,255,0.04)" : "rgba(0,0,0,0.04)",
        border: `1px solid ${P.line}`,
      }}>
        {showVideo ? (
          /* Verified NASA/Commons clip. Controls, no autoplay — a video
             that starts talking the moment it appears is hostile. */
          <video src={safeHref(media.url)} poster={media.poster ? safeHref(media.poster) : undefined}
            controls preload="metadata" playsInline
            onError={() => setFailed(true)}
            style={{ width: "100%", height: "100%", display: "block", background: "#000" }} />
        ) : stillSrc ? (
          <img src={safeHref(stillSrc)}
            alt={title ? `Illustration related to: ${title}` : "Related illustration"}
            loading="lazy" referrerPolicy="no-referrer"
            onLoad={() => setReady(true)} onError={() => setFailed(true)}
            style={{ width: "100%", height: "100%", objectFit: "cover", display: "block", opacity: ready ? 1 : 0, transition: "opacity 280ms ease" }} />
        ) : (
          /* Video with no poster in still mode: an honest play affordance,
             not a fabricated frame. */
          <div aria-hidden="true" style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center", background: "#0a0c10" }}>
            <span style={{ width: 44, height: 44, borderRadius: "50%", background: "rgba(255,255,255,0.14)", display: "flex", alignItems: "center", justifyContent: "center" }}>
              <svg width="16" height="16" viewBox="0 0 16 16" fill="#fff" aria-hidden="true"><path d="M4 2.5v11l9-5.5z" /></svg>
            </span>
          </div>
        )}
        {media.kind === "video" && !showVideo && stillSrc && (
          <span aria-hidden="true" style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center", pointerEvents: "none" }}>
            <span style={{ width: 44, height: 44, borderRadius: "50%", background: "rgba(0,0,0,0.55)", display: "flex", alignItems: "center", justifyContent: "center" }}>
              <svg width="16" height="16" viewBox="0 0 16 16" fill="#fff" aria-hidden="true"><path d="M4 2.5v11l9-5.5z" /></svg>
            </span>
          </span>
        )}
      </div>
      {(media.credit || media.license || media.verified === false) && (
        <figcaption style={{ display: "flex", flexWrap: "wrap", gap: 4, alignItems: "baseline", fontSize: FONT_SIZES.caption, color: P.faint, fontFamily: "var(--cb-font)", marginTop: 8 }}>
          {media.credit && (creditHref && linkCredit ? (
            <a href={creditHref} target="_blank" rel="noreferrer" style={{ color: P.faint, textDecoration: "underline", textUnderlineOffset: 2 }}>{media.credit}</a>
          ) : (
            <span>{media.credit}</span>
          ))}
          {media.credit && media.license && <span aria-hidden="true"> · </span>}
          {media.license && <span>{media.license}</span>}
          {/* The unverified fallback (a trending item's own article
              image, trendingMediaOf) renders MARKED: the caption line
              is the reader's only way to tell a checked picture from
              an unchecked one, so the marking prints whenever the
              media object carries verified: false, with or without a
              credit beside it. Verified media (verified: true) never
              shows it. */}
          {media.verified === false && (media.credit || media.license) && <span aria-hidden="true"> · </span>}
          {media.verified === false && <span>Unverified image</span>}
        </figcaption>
      )}
    </figure>
  );
}

/* Small thumbnail for trending digest rows. A failed load removes the
   thumb; the row reads fine without it. An unverified thumb (the item's
   own article image, the trendingMediaOf fallback) carries the same
   "Unverified image" marking MediaFigure prints, in the row's credit
   typography under the thumb: the digest surface must not let an
   unchecked photo pass as a checked one by staying silent. Verified
   media is never marked. */
function TrendThumb({ P, media, title }) {
  const [failed, setFailed] = useState(false);
  useEffect(() => { setFailed(false); }, [media && media.url, media && media.poster]);
  if (!media || failed) return null;
  const src = media.kind === "video" ? media.poster || null : media.url;
  if (!src) return null;
  return (
    <span style={{ display: "inline-flex", flexDirection: "column", gap: 4, flexShrink: 0, width: 88 }}>
      <span aria-hidden="true" style={{
        position: "relative", width: 88, height: 66, flexShrink: 0, borderRadius: RADIUS.md,
        overflow: "hidden", border: `1px solid ${P.line}`,
        background: P.dark ? "rgba(255,255,255,0.04)" : "rgba(0,0,0,0.04)",
      }}>
        <img src={safeHref(src)} alt="" loading="lazy" referrerPolicy="no-referrer"
          onError={() => setFailed(true)}
          style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }} />
        {media.kind === "video" && (
          <span style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center" }}>
            <span style={{ width: 26, height: 26, borderRadius: "50%", background: "rgba(0,0,0,0.55)", display: "flex", alignItems: "center", justifyContent: "center" }}>
              <svg width="10" height="10" viewBox="0 0 16 16" fill="#fff" aria-hidden="true"><path d="M4 2.5v11l9-5.5z" /></svg>
            </span>
          </span>
        )}
      </span>
      {media.verified === false && (
        <span style={{ fontSize: FONT_SIZES.caption, color: P.faint, fontFamily: "var(--cb-font)", lineHeight: 1.3 }}>Unverified image</span>
      )}
    </span>
  );
}

function TrendingHero({ P, accent, at, item, onExpand, generatedAt, isMobile = false, heroLabel = "First in the edition" }) {
  // The lead story is a briefing card: the words on one side, the
  // verified lead media in its own frame on the other, never a scrim
  // behind text. Text over bright footage drowned. No media, and the
  // card is words alone at full width.
  const media = trendingMediaOf(item);
  return (
    <button
      type="button" onClick={() => onExpand(item)} className="cb-row"
      style={{
        display: "grid", gridTemplateColumns: isMobile || !media ? "1fr" : "minmax(0, 1.05fr) minmax(0, 0.95fr)",
        gap: 24, alignItems: "start", width: "100%", textAlign: "left",
        background: P.surface, border: `1px solid ${P.line}`, borderRadius: RADIUS.xl,
        padding: isMobile ? 18 : 24, boxShadow: SHADOW.sm(P),
        font: "inherit", cursor: "pointer",
      }}
    >
      <div style={{ minWidth: 0 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap", marginBottom: 12 }}>
          <span style={{ fontSize: FONT_SIZES.micro, fontWeight: 500, color: at, background: accent, borderRadius: RADIUS.pill, padding: "4px 11px", fontFamily: "var(--cb-font)" }}>{heroLabel}</span>
          <span style={{ fontSize: FONT_SIZES.micro, fontWeight: 500, color: P.faint, fontFamily: "var(--cb-font)" }}>{trendKind(item)}{item.category ? ` · ${item.category}` : ""}</span>
        </div>
        <div style={{ fontSize: "clamp(24px, 3.2vw, 36px)", fontWeight: 500, color: P.ink, lineHeight: 1.16, letterSpacing: "-0.02em" }}>
          {renderInlineMdLite(item.title, P)}
        </div>
        {item.summary ? (
          <div style={{ fontSize: FONT_SIZES.body, color: P.ink2, lineHeight: 1.65, marginTop: 12, display: "-webkit-box", WebkitLineClamp: 4, WebkitBoxOrient: "vertical", overflow: "hidden" }}>
            {renderInlineMdLite(item.summary, P)}
          </div>
        ) : (
          <div style={{ fontSize: FONT_SIZES.body, color: P.faint, lineHeight: 1.65, marginTop: 12, fontStyle: "italic" }}>
            No summary was published with this record.
          </div>
        )}
        <div style={{ fontSize: FONT_SIZES.caption, color: P.faint, fontFamily: "var(--cb-font)", marginTop: 14 }}>
          {trendProvenance(item, generatedAt)}
        </div>
        {item.coverageCount > 1 && (
          <div style={{ fontSize: FONT_SIZES.caption, color: P.faint, fontFamily: "var(--cb-font)", marginTop: 6 }}>
            Covered by {item.coverageCount} reports in this edition
          </div>
        )}
        <div style={{ fontSize: FONT_SIZES.small, fontWeight: 500, color: accent, fontFamily: "var(--cb-font)", marginTop: 14 }}>
          Read the story brief
        </div>
      </div>
      {media && (
        <div style={{ minWidth: 0 }}>
          {/* Inside a button: still mode (poster + play badge for video)
              and an unlinked credit, since nested interactives would be invalid. */}
          <MediaFigure P={P} media={media} title={(item.title || "").replace(/\*/g, "")} still linkCredit={false} aspect="4/3" />
        </div>
      )}
    </button>
  );
}

/* One rail of the briefing band: a short ranked list (most cited,
   newest) drawn from the same edition the digest shows, so a reader
   in a hurry gets the shape of the day without scanning every row.
   A single entry is not a ranking, so a rail needs at least two. */
function TrendRailList({ P, title, items, onExpand, generatedAt, mode }) {
  if (!items || items.length < 2) return null;
  return (
    <section aria-label={title} style={{ background: P.surface, border: `1px solid ${P.line}`, borderRadius: RADIUS.xl, padding: "16px 18px 8px" }}>
      <div style={{ fontSize: FONT_SIZES.caption, fontWeight: 500, color: P.ink, fontFamily: "var(--cb-font)", letterSpacing: TRACKING.tight, marginBottom: 4 }}>{title}</div>
      {items.map((x, i) => (
        <button key={x.url || x.title || i} type="button" onClick={() => onExpand(x)} className="cb-row"
          style={{ display: "flex", gap: 10, width: "100%", textAlign: "left", background: "transparent", border: "none", borderBottom: i === items.length - 1 ? "none" : `1px solid ${P.line}`, padding: "10px 2px", cursor: "pointer", fontFamily: "var(--cb-font)", alignItems: "baseline" }}>
          <span style={{ flex: 1, minWidth: 0 }}>
            <span style={{ display: "block", fontSize: FONT_SIZES.small, fontWeight: 500, color: P.ink, lineHeight: 1.45 }}>{renderInlineMdLite(x.title, P)}</span>
            <span style={{ display: "block", fontSize: FONT_SIZES.caption, color: P.faint, marginTop: 3 }}>
              {mode === "cited" ? `Cited by ${x.citedByCount}` : trendProvenance(x, generatedAt)}
            </span>
          </span>
        </button>
      ))}
    </section>
  );
}


// Article detail — opened by clicking a story instead of leaving the app
// immediately. Same dialog pattern as InstitutionModal/
// InboxModal (backdrop click + Escape both close, focus trapped inside):
// full title, full untruncated summary, source, published date, and the
// actual outbound link to the original article, which lives here now
// instead of on the card itself.
function TrendingArticleModal({ P, accent, at, item, close, onAsk, upNext = [], onOpenItem }) {
  // Commit 63 — the modal used to be a summary and a link straight off the
  // site. Every one of those clicks was someone leaving. It now carries the
  // three things that make staying the better option: explainer videos
  // playing inline, a one-tap route into Cerebrum's own literature search on
  // the same subject, and what to read next.
  const [videos, setVideos] = useState([]);
  const bodyRef = useRef(null);
  useEffect(() => {
    // Switching stories starts clean: the previous story's videos clear
    // immediately, and the reader lands at the top of the new story.
    setVideos([]);
    if (bodyRef.current) bodyRef.current.scrollTop = 0;
    let cancelled = false;
    const q = (item.title || "").slice(0, 120);
    if (!q) return;
    fetch(`/api/videos?q=${encodeURIComponent(q)}`)
      .then((r) => (r.ok ? r.json() : null))
      .then((d) => { if (!cancelled) setVideos(d && Array.isArray(d.videos) ? d.videos.slice(0, 2) : []); })
      .catch(() => { if (!cancelled) setVideos([]); });
    return () => { cancelled = true; };
  }, [item.title]);
  /* Lead media via the verified contract: media.image.url → legacy
     image_url. A resolved {null, null} or an absent media object renders
     nothing — the modal simply opens without a lead figure. */
  const leadMedia = trendingMediaOf(item);
  const publishedLabel = item.publishedAt
    ? new Date(item.publishedAt).toLocaleDateString(undefined, { year: "numeric", month: "long", day: "numeric" })
    : "";
  const persistenceLabel = trendPersistenceLabel(item);
  return (
    <Dialog label={(item.title || "Article").replace(/\*/g, "")} onClose={close} zIndex={217} width={640}
      panelStyle={{
        background: P.dark ? "#0f111a" : "#ffffff",
        border: `1px solid ${P.line}`,
        borderRadius: RADIUS.lg, maxHeight: "88dvh", display: "flex", flexDirection: "column",
        boxShadow: "none", overflow: "hidden", outline: "none",
      }}
    >
        <div style={{ position: "relative", flexShrink: 0 }}>
          {leadMedia && (
            <div style={{ padding: "16px 16px 0" }}>
              <MediaFigure P={P} media={leadMedia} title={(item.title || "").replace(/\*/g, "")} />
            </div>
          )}
          <button onClick={close} aria-label="Close" style={{ minWidth: 44, minHeight: 44, position: "absolute", top: 8, right: 8, width: 44, height: 44, display: "flex", alignItems: "center", justifyContent: "center", background: "none", border: "none", cursor: "pointer", padding: 0 }}><span style={{ width: 32, height: 32, borderRadius: "50%", display: "flex", alignItems: "center", justifyContent: "center", background: "rgba(0,0,0,0.45)", color: "#fff" }}><Icon name="close" size={16} /></span></button>
        </div>
        <div ref={bodyRef} style={{ flex: 1, overflowY: "auto", padding: 26 }}>
          {item.source && (
            <span style={{ display: "inline-flex", alignItems: "center", gap: 6, fontSize: FONT_SIZES.micro, fontWeight: 500, letterSpacing: TRACKING.tight, color: accentInk(P, accent), fontFamily: "var(--cb-font)" }}>
              <span style={{ width: 6, height: 6, borderRadius: "50%", background: accent }} />
              {item.source}
            </span>
          )}
          <div style={{ fontSize: FONT_SIZES.display, fontWeight: 500, color: P.ink, lineHeight: 1.25, letterSpacing: TYPE.heading.letterSpacing, fontFamily: "var(--cb-font)", marginTop: 10 }}>{renderInlineMdLite(item.title, P)}</div>
          {(publishedLabel || persistenceLabel || typeof item.citedByCount === "number") && <div style={{ fontSize: FONT_SIZES.caption, color: P.faint, fontFamily: "var(--cb-font)", marginTop: 8 }}>{[publishedLabel ? `Published ${publishedLabel}` : null, item.citedByCount > 0 ? `Cited by ${item.citedByCount}` : item.citedByCount === 0 ? "No citations yet" : null, persistenceLabel].filter(Boolean).join(" · ")}</div>}
          {item.summary
            ? <div style={{ fontSize: FONT_SIZES.body, color: P.ink2, lineHeight: 1.7, marginTop: 18 }}>{renderInlineMdLite(item.summary, P)}</div>
            : <div style={{ fontSize: FONT_SIZES.body, color: P.faint, lineHeight: 1.7, marginTop: 18, fontStyle: "italic" }}>No summary was published with this record. The full text is at the source.</div>}
          {Array.isArray(item.coverage) && item.coverage.length > 1 && (
            <div style={{ marginTop: 22 }}>
              <div style={{ fontSize: FONT_SIZES.micro, fontWeight: 500, letterSpacing: TRACKING.eyebrow, color: P.faint, fontFamily: "var(--cb-font)", marginBottom: 8 }}>More coverage of this story · {item.coverage.length} reports</div>
              {item.coverage.filter((c) => c.url !== item.url).map((c, i) => (
                <a key={c.url || i} href={safeHref(c.url)} target="_blank" rel="noreferrer" style={{ display: "block", padding: "9px 0", borderBottom: `1px solid ${P.line}`, textDecoration: "none" }}>
                  <span style={{ display: "block", fontSize: FONT_SIZES.small, fontWeight: 500, color: P.ink, lineHeight: 1.4 }}>{renderInlineMdLite(c.title, P)}</span>
                  <span style={{ display: "block", fontSize: FONT_SIZES.caption, color: P.faint, marginTop: 3 }}>{c.source || c.category}</span>
                </a>
              ))}
            </div>
          )}
          {/* The primary action is now the one that keeps someone here and
              is genuinely more useful than the source page: Cerebrum can
              answer what the science actually says, with citations. Reading
              the original is still one tap away, just no longer the only
              thing on offer. */}
          <div style={{ alignItems: "center", display: "flex", flexWrap: "wrap", gap: 10, marginTop: 24 }}>
            <UIButton P={P} variant="ghost"
              onClick={() => { if (onAsk) { const doi = trendingDoiOf(item); onAsk(`What does the research actually show about this: ${item.title}${doi ? ` (DOI: ${doi})` : ""}${item.source ? `, reported by ${item.source}` : ""}`); close(); } }}
              style={{ minHeight: 44,
                display: "inline-flex", alignItems: "center", gap: 8, padding: "12px 16px",
                fontSize: FONT_SIZES.small, fontWeight: 500, color: at, background: accent,
                borderRadius: RADIUS.viewport, border: "none", cursor: "pointer", fontFamily: "var(--cb-font)",
              }}
            ><Icon name="bookOpen" size={14} /> Explain with papers</UIButton>
            <a href={safeHref(item.url)} target="_blank" rel="noreferrer" style={{
              display: "inline-flex", alignItems: "center", gap: 8, padding: "12px 16px",
              fontSize: FONT_SIZES.small, fontWeight: 500, color: P.ink2, background: "transparent",
              border: `1px solid ${P.line2}`, borderRadius: RADIUS.viewport, textDecoration: "none",
            }}>
              Read at source <Icon name="external" size={13} />
            </a>
          </div>

          {videos.length > 0 && (
            <div style={{ marginTop: 28 }}>
              <div style={{ fontSize: FONT_SIZES.micro, fontWeight: 500, letterSpacing: TRACKING.eyebrow, color: P.faint, fontFamily: "var(--cb-font)", marginBottom: 10 }}>Watch</div>
              {videos.map((v) => {
                const id = getYouTubeId(v);
                if (!id) return null;
                return (
                  <div key={id} style={{ marginBottom: 14 }}>
                    <div style={{ position: "relative", aspectRatio: "16/9", borderRadius: RADIUS.lg, overflow: "hidden", border: `1px solid ${P.line}` }}>
                      {/* youtube-nocookie, and no autoplay: a video that starts
                          talking the moment a card opens is the fastest way to
                          make someone close the tab. */}
                      <iframe
                        src={`https://www.youtube-nocookie.com/embed/${id}`}
                        title={v.title || "Related video"}
                        allow="accelerometer; encrypted-media; picture-in-picture"
                        allowFullScreen
                        loading="lazy"
                        style={{ position: "absolute", inset: 0, width: "100%", height: "100%", border: "none" }}
                      />
                    </div>
                    {/* Provenance under the frame, like everything else on
                        this surface: what the video is and whose it is,
                        instead of a bare embed. */}
                    {(v.title || v.author) && (
                      <div style={{ marginTop: 6, fontSize: FONT_SIZES.caption, color: P.faint, fontFamily: "var(--cb-font)", lineHeight: 1.45 }}>
                        {v.title ? <span style={{ color: P.ink2 }}>{v.title}</span> : null}
                        {v.title && v.author ? " · " : null}
                        {v.author ? <span>{v.author} on YouTube</span> : null}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          )}

          {upNext.length > 0 && (
            <div style={{ marginTop: 26 }}>
              <div style={{ fontSize: FONT_SIZES.micro, fontWeight: 500, letterSpacing: TRACKING.eyebrow, color: P.faint, fontFamily: "var(--cb-font)", marginBottom: 8 }}>Up next</div>
              {upNext.map((nx, i) => (
                <button key={nx.url || i} onClick={() => onOpenItem && onOpenItem(nx)}
                  style={{ minHeight: 44,
                    display: "block", width: "100%", textAlign: "left", padding: "11px 0",
                    background: "transparent", border: "none", borderBottom: `1px solid ${P.line}`,
                    cursor: "pointer", fontFamily: "var(--cb-font)",
                  }}>
                  <span style={{ display: "block", fontSize: FONT_SIZES.small, fontWeight: 500, color: P.ink, lineHeight: 1.4 }}>{renderInlineMdLite(nx.title, P)}</span>
                  <span style={{ display: "block", fontSize: FONT_SIZES.caption, color: P.faint, marginTop: 3 }}>{[nx.category, nx.source, trendPersistenceLabel(nx)].filter(Boolean).join(" · ")}</span>
                </button>
              ))}
            </div>
          )}
        </div>
    </Dialog>
  );
}


// How often an open Trending tab re-polls its own endpoint. The feed
// itself only actually changes once an hour (trending-refresh.js's own
// job) — this isn't trying to beat that clock, it's just making sure
// someone who leaves the tab open for a while sees the next hourly
// refresh land without having to manually reload.
const TRENDING_POLL_MS = 5 * 60 * 1000;

/* ══════════════════════════════════════════════════════════════════
   Commit 88 — WorkspacePage.

   Cerebrum had two kinds of destination wearing one kind of sidebar row.
   Trending, Inbox, Settings and Profile were pages. Investigations, Saved,
   Collections and Find People were centred modal dialogs floating over
   whatever search happened to be underneath, dismissed by Escape or a
   click on the backdrop.

   That split is most of why the product read as a chatbot with features
   bolted on rather than an instrument. A modal is a thing that interrupts
   you; a page is a place you go. Your library of saved papers, your
   investigations, your collections and the people you follow are not
   interruptions — they are the work, and half the app's actual content
   lived in dialogs you could lose by pressing the wrong key. They were
   also capped at 520-560px wide with an internal 56vh scroll, so a
   forty-paper library was read through a letterbox on a 1440px screen.

   This is the shell all four now use, and it deliberately matches
   TrendingView's proportions so that every destination in the rail has the
   same margins, the same title size and the same rhythm. One page shape,
   used everywhere.
   ══════════════════════════════════════════════════════════════════ */
function WorkspacePage({ P, accent, isMobile, title, count, description, actions, children, wide = false }) {
  return (
    /* minHeight 100%, or the reading floor below stops where the content
       stops and leaves a hard horizontal seam across the page — the scrim
       is absolutely positioned inside this box, so the box has to be as
       tall as the view. */
    <div style={{ flex: 1, minHeight: "100%", position: "relative" }}>
      <div style={{
        position: "relative",
        /* 820 is the measure the composer and the Home Deck use. These
           pages sat at 900 with a title 44px from the top edge while the
           home screen gave its content a third of the viewport, so moving
           between them felt like moving between two apps. */
        maxWidth: wide ? 1180 : 820, width: "100%", margin: "0 auto",
        // Commit 88 — the mobile menu button is fixed at top:14 left:14 and
        // is 38px square, so a page title starting at 24px from the top ran
        // straight underneath it. TrendingView already carried this offset;
        // every new page needs it too.
        // Pass 1 (2026-09-17): vertical padding cut ~25% — the film scrim
        // this page used to veil is gone, and the page is now a quiet
        // opaque surface; it no longer needs the extra air.
        padding: isMobile ? "52px 18px 56px" : "58px 32px 70px",
      }}>
        <div style={{ marginBottom: 26 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 12, flexWrap: "wrap" }}>
            {/* The resident header Nova (2026-10-15): the same
                NovaLive the learning home runs, one per screen, at
                the same 66px class, left of the page title. Every
                WorkspacePage destination (Library, Investigations,
                Collections, Find people) gets her from this one
                mount; her brain runs idle here and hears the same
                nova-activity events as everywhere else. */}
            <span aria-hidden="true" style={{ flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center" }}>
              <NovaLive size={66} />
            </span>
            <h1 style={{
              margin: 0, fontSize: isMobile ? 28 : FONT_SIZES.hero, fontWeight: 500,
              letterSpacing: TYPE.display.letterSpacing, color: P.ink, fontFamily: "var(--cb-font)", lineHeight: 1.1,
            }}>{title}</h1>
            {count != null && count > 0 && (
              <span style={{
                fontSize: FONT_SIZES.caption, fontWeight: 500, fontFamily: "var(--cb-font)",
                color: P.ink2, background: P.dark ? "rgba(255,255,255,0.07)" : "rgba(0,0,0,0.05)",
                border: `1px solid ${P.line}`,
                boxShadow: P.dark ? "none" : "none",
                padding: "4px 11px", borderRadius: RADIUS.pill, fontVariantNumeric: "tabular-nums",
              }}>{count}</span>
            )}
            {actions && <div style={{ alignItems: "center", marginLeft: isMobile ? 0 : "auto", display: "flex", gap: 8, flexWrap: "wrap" }}>{actions}</div>}
          </div>
          {description && (
            <p style={{
              margin: "10px 0 0", maxWidth: 620, fontSize: FONT_SIZES.small,
              color: P.ink2, lineHeight: 1.6, fontFamily: "var(--cb-font)",
            }}>{description}</p>
          )}
        </div>
        {children}
      </div>
    </div>
  );
}

/* One empty state for the whole workspace, so Library, Investigations and
   Collections agree with each other and with the profile tabs. */
function WorkspaceEmpty({ P, accent, icon, title, body, action, isMobile = false }) {
  return (
    <div style={{
      display: "flex", flexDirection: "column", alignItems: "center", textAlign: "center",
      /* A real surface, not a dashed dropzone. Opaque shell (2026-09-17
         redesign pass 1): the ambient film is gone, so the glass recipe
         this used to share with every other panel is now a solid surface
         with one hairline border and no shadow — never a pure-black void. */
      padding: isMobile ? "48px 22px" : "64px 28px", borderRadius: RADIUS.lg,
      position: "relative", overflow: "hidden",
      border: P.dark ? "1px solid rgba(255,255,255,0.09)" : `1px solid ${P.line2}`,
      background: P.surface,
    }}>
      <span aria-hidden="true" style={{
        display: "inline-flex", alignItems: "center", justifyContent: "center",
        width: 46, height: 46, borderRadius: RADIUS.md, marginBottom: 15,
        color: accent, background: withAlpha(accent, 0.1),
        border: `1px solid ${withAlpha(accent, 0.22)}`,
      }}><Icon name={icon} size={20} /></span>
      <div style={{ position: "relative", fontSize: isMobile ? FONT_SIZES.title : 19, fontWeight: 500, color: P.ink, fontFamily: "var(--cb-font)", letterSpacing: TYPE.heading.letterSpacing }}>{title}</div>
      <div style={{ fontSize: FONT_SIZES.small, color: P.faint, lineHeight: 1.6, marginTop: 8, maxWidth: 400, fontFamily: "var(--cb-font)" }}>{body}</div>
      {action && <div style={{ marginTop: 18 }}>{action}</div>}
    </div>
  );
}

// ── Usage view ────────────────────────────────────────────────────────────
// Signed-in metered tiers (Free / Lite) get an instrument readout: used,
// remaining, cap, and the exact refill moment for each bucket, with
// near-limit and exhausted states. Pro sees its unlimited state. The tier
// comparison and the Pro pitch sit below the gauges — promotion without
// obstruction. Deliberately not a card grid: three gauge rails, one spec
// table, one editorial banner.
/* ── Quota grid (client mirror of functions/lib/proEntitlement.js) ──
 * The backend anchors quota periods to the epoch, not to signup:
 * FREE_QUOTA_PERIOD_DAYS = 5, QUOTA_PERIOD_MS = 5·24·3600·1000,
 * periodKey(now) = "p" + floor(now / QUOTA_PERIOD_MS). So the reset is
 * always the next grid boundary — computable exactly, client-side, with
 * no fetch. The server's resetsInMs is kept as validation/fallback: if
 * it disagrees with the grid by more than five minutes, the server wins
 * (its clock is authoritative) — otherwise the grid does. */
const QUOTA_PERIOD_MS = 5 * 24 * 3600 * 1000;
function cbQuotaResetsAt(now = Date.now()) {
  return (Math.floor(now / QUOTA_PERIOD_MS) + 1) * QUOTA_PERIOD_MS;
}
function quotaRefillSentence(now = Date.now()) {
  const resetsAt = cbQuotaResetsAt(now);
  const date = new Date(resetsAt).toLocaleDateString(undefined, { weekday: "long", month: "long", day: "numeric" });
  const time = new Date(resetsAt).toLocaleTimeString(undefined, { hour: "numeric", minute: "2-digit" });
  return `Your allowance refills ${date} at ${time}.`;
}

function UsageView({ P, accent, at, user, proStatus, proStatusFailed = false, onRetryPro = null, onOpenPro, onOpenAuth, isMobile = false }) {
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => {
    const id = setInterval(() => setNow(Date.now()), 30000);
    return () => clearInterval(id);
  }, []);
  /* Above every early return: hooks can't be conditional. */
  const motionOff = useReducedMotion();
  // The refill countdown follows the backend's fixed 5-day epoch grid —
  // the boundary is computable exactly, so the ticking clock can't drift
  // as the component re-renders. The server's own resetsInMs (anchored to
  // the moment this snapshot arrived) stays as validation: if it
  // disagrees with the grid by more than five minutes, the server is
  // authoritative and wins.
  const fetchedAtRef = useRef(Date.now());
  const prevStatusRef = useRef(proStatus);
  if (prevStatusRef.current !== proStatus) {
    prevStatusRef.current = proStatus;
    fetchedAtRef.current = Date.now();
  }
  const gridResetsAt = cbQuotaResetsAt(now);
  const serverResetsInMs = proStatus?.quotaPeriod?.resetsInMs;
  const serverResetsAt = serverResetsInMs != null ? fetchedAtRef.current + serverResetsInMs : null;
  const resetsAt = serverResetsAt != null && Math.abs(serverResetsAt - gridResetsAt) > 5 * 60 * 1000
    ? serverResetsAt
    : gridResetsAt;
  const remainingMs = Math.max(0, resetsAt - now);

  const fmtRemaining = (ms) => {
    if (ms == null) return "Not reported";
    if (ms <= 0) return "refilling…";
    const m = Math.floor(ms / 60000);
    const d = Math.floor(m / 1440);
    const h = Math.floor((m % 1440) / 60);
    const mm = m % 60;
    if (d > 0) return `${d}d ${h}h`;
    if (h > 0) return `${h}h ${mm}m`;
    return `${mm}m`;
  };
  const refillDate = new Date(resetsAt).toLocaleDateString(undefined, { weekday: "long", month: "long", day: "numeric" });
  const refillTime = new Date(resetsAt).toLocaleTimeString(undefined, { hour: "numeric", minute: "2-digit" });

  if (!user) {
    return (
      <div style={{ maxWidth: 640, margin: "0 auto", padding: isMobile ? "64px 24px" : "48px 24px", textAlign: "center" }}>
        <div style={{ fontSize: FONT_SIZES.title, fontWeight: 500, color: P.ink, fontFamily: "var(--cb-font)", letterSpacing: TYPE.heading.letterSpacing }}>Usage</div>
        <div style={{ fontSize: FONT_SIZES.small, color: P.ink2, marginTop: 10, fontFamily: "var(--cb-font)" }}>
          Sign in to see your meters: AI answers, document reads, and flowcharts, with exact refill times.
        </div>
        <UIButton P={P} variant="ghost" onClick={() => onOpenAuth && onOpenAuth("signin")} style={{ marginTop: 20, padding: "12px 28px", minHeight: 44, fontSize: FONT_SIZES.label, fontWeight: 500, color: at, background: accent, border: "none", borderRadius: RADIUS.lg, cursor: "pointer", fontFamily: "var(--cb-font)" }}>
          Sign in
        </UIButton>
      </div>
    );
  }

  /* 2026-10-16 (audit finding 19): proStatus is null until the first
     fetch lands, and refreshPro stores null again when a fetch throws.
     Rendering the gauges in that state read every absent bucket cap as
     unlimited while the header said Free. Show a loading state instead;
     no tier, cap, or refill claim is made until the status arrives. */
  if (!proStatus && proStatusFailed) {
    return (
      <div style={{ maxWidth: 640, margin: "0 auto", padding: isMobile ? "64px 24px" : "48px 24px", textAlign: "center" }}>
        <div style={{ fontSize: FONT_SIZES.title, fontWeight: 500, color: P.ink, fontFamily: "var(--cb-font)", letterSpacing: TYPE.heading.letterSpacing }}>Usage</div>
        <div role="alert" style={{ fontSize: FONT_SIZES.small, color: P.ink2, marginTop: 10, fontFamily: "var(--cb-font)", lineHeight: 1.55 }}>
          Your plan status could not be loaded, so your meters are not shown. Nothing about your plan has changed.
        </div>
        {onRetryPro && (
          <UIButton P={P} variant="ghost" onClick={onRetryPro} style={{ marginTop: 20, padding: "12px 28px", minHeight: 44, fontSize: FONT_SIZES.label, fontWeight: 500, color: at, background: accent, border: "none", borderRadius: RADIUS.lg, cursor: "pointer", fontFamily: "var(--cb-font)" }}>
            Retry
          </UIButton>
        )}
      </div>
    );
  }

  if (!proStatus) {
    return (
      <div style={{ maxWidth: 640, margin: "0 auto", padding: isMobile ? "64px 24px" : "48px 24px", textAlign: "center" }}>
        <div style={{ fontSize: FONT_SIZES.title, fontWeight: 500, color: P.ink, fontFamily: "var(--cb-font)", letterSpacing: TYPE.heading.letterSpacing }}>Usage</div>
        <div style={{ fontSize: FONT_SIZES.small, color: P.ink2, marginTop: 10, fontFamily: "var(--cb-font)" }}>
          Loading your plan details. Your meters appear here as soon as your plan status arrives.
        </div>
      </div>
    );
  }

  const tier = proStatus?.tier || "free";
  /* 2026-10-16 (audit finding 19): Pro derives the way Profile and the
     account menu derive it, with the user Pro flag as a backstop, so a
     proStatus payload that lags a grant cannot demote a Pro user. */
  const isPro = tier === "pro" || !!user?.isPro;
  const isLite = !isPro && (tier === "lite" || !!proStatus?.isLite);
  const plans = proStatus?.plans || {};
  const q = proStatus?.quota;
  const dq = proStatus?.docReads;
  const fq = proStatus?.flowcharts;
  const liteMonthly = plans["lite-monthly"]?.usd != null ? `$${plans["lite-monthly"].usd}` : "$3.99";

  const Gauge = ({ label, used, cap, sub, upgrade, upgradePlan }) => {
    const unlimited = cap == null;
    const pct = unlimited ? 100 : cap > 0 ? Math.min(100, Math.round((used / cap) * 100)) : 0;
    const left = unlimited ? null : Math.max(0, cap - used);
    const state = unlimited ? "unlimited" : left === 0 ? "empty" : pct >= 80 ? "low" : "ok";
    const fill = state === "empty" ? "#e5484d" : state === "low" ? "#e8a13c" : accent;
    const stateLine = state === "unlimited" ? `${used} this period. No cap.`
      : state === "empty" ? `Empty. Refills in ${fmtRemaining(remainingMs)}`
      : state === "low" ? `${left} remaining. Running low.`
      : `${left} remaining`;
    /* The three permitted upgrade moments: the Usage tab itself (the
       concrete-gain line below), the ~80% threshold, and the exhaustion
       moment. Nothing here nags — the meter is the message, the button
       is the door. */
    const showUpgrade = (state === "low" || state === "empty") && upgrade && !unlimited;
    return (
      <div style={{ padding: "16px 0", borderBottom: `1px solid ${P.line}` }}>
        <div style={{ display: "flex", alignItems: "baseline", justifyContent: "space-between", gap: 12, flexWrap: "wrap" }}>
          <span style={{ fontSize: FONT_SIZES.micro, fontWeight: 500, letterSpacing: TRACKING.eyebrow, color: P.faint, fontFamily: "var(--cb-font)" }}>{label}</span>
          <span style={{ fontSize: FONT_SIZES.title, fontWeight: 500, color: P.ink, fontFamily: "var(--cb-font)", letterSpacing: TYPE.heading.letterSpacing, fontVariantNumeric: "tabular-nums" }}>
            {unlimited ? <>{used}</> : <>{used}<span style={{ color: P.faint, fontWeight: 500 }}> / {cap}</span></>}
          </span>
        </div>
        <div style={{ position: "relative", marginTop: 12, height: 8, borderRadius: RADIUS.viewport, background: P.raised, overflow: "hidden" }} role="progressbar" aria-valuenow={unlimited ? undefined : used} aria-valuemax={unlimited ? undefined : cap} aria-label={`${label} usage`}>
          {!unlimited && (
            <div style={{ position: "absolute", inset: 0, width: `${pct}%`, borderRadius: RADIUS.viewport, background: fill, transition: motionOff ? "none" : "width 400ms ease" }} />
          )}
          {unlimited && (
            <div style={{ position: "absolute", inset: 0, borderRadius: RADIUS.viewport, background: accent }} />
          )}
        </div>
        <div style={{ display: "flex", justifyContent: "space-between", gap: 8, marginTop: 8, flexWrap: "wrap" }}>
          <span style={{ fontSize: FONT_SIZES.caption, fontWeight: state === "ok" || state === "unlimited" ? 500 : 500, color: state === "empty" ? statusBad(P) : state === "low" ? statusWarn(P) : P.faint, fontFamily: "var(--cb-font)" }}>{stateLine}</span>
          {sub && <span style={{ fontSize: FONT_SIZES.caption, color: P.faint, fontFamily: "var(--cb-font)" }}>{sub}</span>}
        </div>
        {showUpgrade && (
          <UIButton P={P} variant="ghost" onClick={() => onOpenPro(upgradePlan)} style={{
            marginTop: 10, minHeight: 44, padding: "12px 24px", borderRadius: RADIUS.sm,
            border: state === "empty" ? "none" : `1px solid ${withAlpha("#d4a437", 0.55)}`,
            background: state === "empty" ? "#e5484d" : "transparent",
            color: state === "empty" ? "#fff" : P.ink,
            fontSize: FONT_SIZES.label, fontWeight: 500, fontFamily: "var(--cb-font)", cursor: "pointer",
          }}>{upgrade}</UIButton>
        )}
      </div>
    );
  };

  /* Sacred tier facts — the numbers below are the product's own:
     Free 50 / 3 / 1, Lite 500 / 30 / 10, Pro unlimited.
     Prices: Lite $3.99/mo · $39/yr, Pro $20/mo · $144/yr.
     Pro Student is full Pro at $7.99/mo for the first 12 months for
     verified college students, then the standard $20/mo. */
  const tiers = [
    { id: "free", name: "Free", ai: "50", docs: "3", flow: "1", price: "$0" },
    { id: "lite", name: "Lite", ai: "500", docs: "30", flow: "10", price: "$3.99/mo · $39/yr" },
    { id: "pro", name: "Pro", ai: "Unlimited", docs: "Unlimited", flow: "Unlimited", price: "$20/mo · $144/yr" },
    { id: "student", name: "Pro Student", ai: "Unlimited", docs: "Unlimited", flow: "Unlimited", price: "$7.99/mo for 12 months, then $20/mo" },
  ];
  const tierAction = (id) => {
    if (id === tier) return <span style={{ fontSize: FONT_SIZES.caption, fontWeight: 500, color: P.faint, fontFamily: "var(--cb-font)" }}>Current plan</span>;
    /* 2026-10-08: "Get Lite" must open the Pro dialog with the Lite plan
       preselected — opening on Pro Annual ($144) after clicking "Get Lite"
       is a money-path bug. Same rule for Pro Student: it preselects the
       Student plan, which gates checkout on college email verification. */
    const proLike = id === "pro" || id === "student";
    return (
      <UIButton P={P} variant="ghost" onClick={() => onOpenPro(id === "lite" ? "lite-monthly" : id === "student" ? "student" : undefined)} style={{ padding: "12px 16px", minHeight: 44, fontSize: FONT_SIZES.label, fontWeight: 500, background: proLike ? "#d4a437" : "transparent", color: proLike ? "#1a1405" : P.ink, border: proLike ? "none" : `1px solid ${P.line2}`, borderRadius: RADIUS.md, cursor: "pointer", fontFamily: "var(--cb-font)", whiteSpace: "nowrap" }}>
        {id === "lite" ? "Get Lite" : id === "pro" ? "Go Pro" : id === "student" ? "Get Student" : "Switch to Free"}
      </UIButton>
    );
  };

  /* 2026-10-16 layout fix (finding 16): mobile top padding is 64px in
     every Usage state, signed in, signed out, and loading. The old 32px
     and 48px tops put the header row under the fixed 56px top bar. */
  return (
    <div style={{ maxWidth: 720, margin: "0 auto", padding: isMobile ? "64px 24px 64px" : "32px 24px 64px" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 14, flexWrap: "wrap" }}>
        {/* The resident header Nova (2026-10-15), same mount as
            every other tab: 66px, left of the title, idle brain. */}
        <span aria-hidden="true" style={{ flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center" }}>
          <NovaLive size={66} />
        </span>
        <h1 style={{ margin: 0, fontSize: FONT_SIZES.display, fontWeight: 500, color: P.ink, fontFamily: "var(--cb-font)", letterSpacing: TYPE.heading.letterSpacing }}>Usage</h1>
        <span style={{ marginLeft: "auto", fontSize: FONT_SIZES.small, fontWeight: 500, color: isPro ? "#d4a437" : P.ink2, fontFamily: "var(--cb-font)", display: "inline-flex", alignItems: "center", gap: 8 }}>
          {isPro && <ProBadge />}
          {isPro ? "Pro" : isLite ? "Pro Lite" : "Free"}
        </span>
      </div>
      <div style={{ fontSize: FONT_SIZES.small, color: P.ink2, marginTop: 8, fontFamily: "var(--cb-font)" }}>
        {isPro
          ? "Your plan has no limits."
          : <>Everything below refills <strong style={{ color: P.ink }}>{refillDate}{refillTime ? ` at ${refillTime}` : ""}</strong> ({fmtRemaining(remainingMs)} left in this period).</>}
      </div>

      <div style={{ marginTop: 12 }}>
        {/* 2026-10-16 (audit finding 19): a metered tier whose bucket is
            absent falls back to that tier's known cap (Free 50 / 3 / 1,
            Lite 500 / 30 / 10, per the tier table below) instead of
            passing undefined into the Gauge, which reads it as
            unlimited. Only Pro passes null. */}
        <Gauge label="AI ANSWERS" used={q?.used || 0} cap={isPro ? null : (q?.cap ?? (isLite ? 500 : 50))}
          sub={isPro ? null : isLite ? "Pro removes this limit." : "Lite gives 500 answers per 5 days."}
          upgrade={isLite ? "Go Pro: unlimited answers" : "Get Lite: 500 answers per 5 days"}
          upgradePlan={isLite ? "annual" : "lite-monthly"} />
        <Gauge label="DOCUMENT READS" used={dq?.used || 0} cap={isPro ? null : (dq?.cap ?? (isLite ? 30 : 3))}
          sub={isPro ? null : isLite ? "Pro removes this limit." : "Lite gives 30 reads per 5 days."}
          upgrade={isLite ? "Go Pro: unlimited reads" : "Get Lite: 30 reads per 5 days"}
          upgradePlan={isLite ? "annual" : "lite-monthly"} />
        <Gauge label="FLOWCHARTS" used={fq?.used || 0} cap={isPro ? null : (fq?.cap ?? (isLite ? 10 : 1))}
          sub={isPro ? null : isLite ? "Pro removes this limit." : "Lite gives 10 flowcharts per 5 days."}
          upgrade={isLite ? "Go Pro: unlimited flowcharts" : "Get Lite: 10 flowcharts per 5 days"}
          upgradePlan={isLite ? "annual" : "lite-monthly"} />
      </div>

      {(() => {
        const tok = proStatus?.tokens;
        if (!tok || !(tok.calls > 0)) return null;
        const fmtT = (n) => {
          n = Number(n) || 0;
          if (n >= 1e9) return (n / 1e9).toFixed(2) + "B";
          if (n >= 1e6) return (n / 1e6).toFixed(2) + "M";
          if (n >= 1e3) return (n / 1e3).toFixed(1) + "K";
          return String(Math.round(n));
        };
        const total = (tok.promptTokens || 0) + (tok.completionTokens || 0);
        return (
          <div style={{ padding: "16px 0", borderBottom: `1px solid ${P.line}` }}>
            <div style={{ display: "flex", alignItems: "baseline", justifyContent: "space-between", gap: 12, flexWrap: "wrap" }}>
              <span style={{ fontSize: FONT_SIZES.micro, fontWeight: 500, letterSpacing: TRACKING.eyebrow, color: P.faint, fontFamily: "var(--cb-font)" }}>AI TOKENS</span>
              <span style={{ fontSize: FONT_SIZES.title, fontWeight: 500, color: P.ink, fontFamily: "var(--cb-font)", letterSpacing: TYPE.heading.letterSpacing, fontVariantNumeric: "tabular-nums" }}>
                {fmtT(total)}
              </span>
            </div>
            <div style={{ display: "flex", justifyContent: "space-between", gap: 8, marginTop: 8, flexWrap: "wrap" }}>
              <span style={{ fontSize: FONT_SIZES.caption, color: P.faint, fontFamily: "var(--cb-font)" }}>
                {tok.calls} AI {tok.calls === 1 ? "call" : "calls"} this month · {fmtT(tok.promptTokens)} in · {fmtT(tok.completionTokens)} out
              </span>
            </div>
            <div style={{ fontSize: FONT_SIZES.caption, color: P.faint, fontFamily: "var(--cb-font)", marginTop: 4, opacity: 0.75 }}>
              Token counts are estimated from provider reports and character counts.
            </div>
          </div>
        );
      })()}

      <h2 style={{ margin: "40px 0 4px", fontSize: FONT_SIZES.body, fontWeight: 500, color: P.ink, fontFamily: "var(--cb-font)", letterSpacing: TYPE.heading.letterSpacing }}>Compare plans</h2>
      <div style={{ fontSize: FONT_SIZES.caption, color: P.faint, fontFamily: "var(--cb-font)", marginBottom: 12 }}>
        Lite raises your limits. Pro removes them.
      </div>
      <div className="cb-usage-table-desktop" style={{ border: `1px solid ${P.line}`, borderRadius: RADIUS.lg, overflow: "hidden" }}>
        <table style={{ width: "100%", borderCollapse: "collapse", fontFamily: "var(--cb-font)" }}>
          <thead>
            <tr>
              <th style={{ textAlign: "left", padding: "12px 16px", fontSize: FONT_SIZES.micro, fontWeight: 500, letterSpacing: TRACKING.eyebrow, color: P.faint, borderBottom: `1px solid ${P.line}` }}></th>
              {tiers.map((t) => (
                <th key={t.id} style={{ textAlign: "center", padding: "12px 8px", fontSize: FONT_SIZES.small, fontWeight: 500, color: t.id === tier ? P.ink : P.ink2, borderBottom: `1px solid ${P.line}`, background: t.id === tier ? withAlpha("#d4af37", 0.06) : "transparent" }}>
                  <span style={{ display: "inline-flex", alignItems: "center", gap: 6 }}>{(t.id === "pro" || t.id === "student") && <ProBadge />}{t.name}</span>
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {[["AI answers", "ai"], ["Document reads", "docs"], ["Flowcharts", "flow"]].map(([label, key]) => (
              <tr key={key}>
                <td style={{ padding: "12px 16px", fontSize: FONT_SIZES.small, color: P.ink2, borderBottom: `1px solid ${P.line}` }}>{label}</td>
                {tiers.map((t) => (
                  <td key={t.id} style={{ padding: "12px 8px", fontSize: FONT_SIZES.small, fontWeight: t.id === tier ? 500 : 400, color: P.ink, textAlign: "center", borderBottom: `1px solid ${P.line}`, background: t.id === tier ? withAlpha("#d4af37", 0.06) : "transparent" }}>{t[key]}</td>
                ))}
              </tr>
            ))}
            <tr>
              <td style={{ padding: "12px 16px", fontSize: FONT_SIZES.small, color: P.ink2 }}>Price</td>
              {tiers.map((t) => (
                <td key={t.id} style={{ padding: "12px 8px", textAlign: "center", background: t.id === tier ? withAlpha("#d4af37", 0.06) : "transparent" }}>
                  <div style={{ fontSize: FONT_SIZES.small, fontWeight: 500, color: P.ink, marginBottom: 8 }}>{t.price}</div>
                  {tierAction(t.id)}
                </td>
              ))}
            </tr>
          </tbody>
        </table>
      </div>
      {/* 360px: the table becomes four stacked tier cards —
         nothing clips, no sideways scroll, every control keeps its
         44px target. Desktop never sees this. */}
      <div className="cb-usage-cards">
        {tiers.map((t) => {
          const current = t.id === tier;
          return (
            <div key={t.id} style={{
              border: current ? "1px solid rgba(212,175,55,0.6)" : `1px solid ${P.line}`,
              borderRadius: RADIUS.lg, padding: "16px 16px 16px",
              background: current ? withAlpha("#d4af37", 0.05) : "transparent",
            }}>
              <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8 }}>
                <span style={{ display: "inline-flex", alignItems: "center", gap: 6, fontSize: FONT_SIZES.body, fontWeight: 500, color: P.ink, fontFamily: "var(--cb-font)" }}>
                  {(t.id === "pro" || t.id === "student") && <ProBadge />}{t.name}
                </span>
                {current && <span style={{ fontSize: FONT_SIZES.caption, fontWeight: 500, color: P.faint, fontFamily: "var(--cb-font)" }}>Current plan</span>}
              </div>
              <div style={{ marginTop: 10, display: "flex", flexDirection: "column", gap: 4, fontSize: FONT_SIZES.small, color: P.ink2, fontFamily: "var(--cb-font)" }}>
                <span>AI answers: <strong style={{ color: P.ink, fontWeight: 500 }}>{t.ai}</strong></span>
                <span>Document reads: <strong style={{ color: P.ink, fontWeight: 500 }}>{t.docs}</strong></span>
                <span>Flowcharts: <strong style={{ color: P.ink, fontWeight: 500 }}>{t.flow}</strong></span>
              </div>
              <div style={{ marginTop: 10, fontSize: FONT_SIZES.small, fontWeight: 500, color: P.ink, fontFamily: "var(--cb-font)" }}>{t.price}</div>
              <div style={{ marginTop: 10 }}>{tierAction(t.id)}</div>
            </div>
          );
        })}
      </div>

      {!isPro && (
        <div style={{ marginTop: 32, border: "1px solid rgba(212,175,55,0.35)", borderRadius: RADIUS.lg, padding: "24px 22px", background: P.dark ? "rgba(212,175,55,0.05)" : "rgba(212,175,55,0.08)" }}>
          <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 8 }}>
            <span style={{ fontSize: FONT_SIZES.body, fontWeight: 500, color: P.ink, fontFamily: "var(--cb-font)", letterSpacing: TYPE.heading.letterSpacing }}>Pro</span>
            <ProBadge />
          </div>
          <div style={{ fontSize: FONT_SIZES.small, color: P.ink2, fontFamily: "var(--cb-font)", lineHeight: 1.6 }}>
            Pro gives you unlimited AI answers, document reads, and flowcharts, plus the gold badge and the black and bronze theme.
          </div>
          <div style={{ display: "flex", gap: 10, marginTop: 18, flexWrap: "wrap", alignItems: "center" }}>
            <button onClick={onOpenPro} style={{ padding: "12px 26px", minHeight: 44, fontSize: FONT_SIZES.label, fontWeight: 500, color: PRO.emeraldInk, background: PRO.emerald, border: "none", borderRadius: RADIUS.lg, cursor: "pointer", fontFamily: "var(--cb-font)" }}>
              Go Pro: $20/mo or $144/yr
            </button>
            {!isLite && (
              <UIButton P={P} variant="ghost" onClick={onOpenPro} style={{ padding: "12px 24px", minHeight: 44, fontSize: FONT_SIZES.label, fontWeight: 500, background: "transparent", color: P.ink, border: `1px solid ${P.line2}`, borderRadius: RADIUS.lg, cursor: "pointer", fontFamily: "var(--cb-font)" }}>
                Or start with Lite: {liteMonthly}/mo or $39/yr
              </UIButton>
            )}
            {isLite && (
              <span style={{ fontSize: FONT_SIZES.caption, color: P.faint, fontFamily: "var(--cb-font)" }}>
                You're on Pro Lite. Pro removes all limits.
              </span>
            )}
            <UIButton P={P} variant="ghost" onClick={() => onOpenPro("student")} style={{ padding: "12px 24px", minHeight: 44, fontSize: FONT_SIZES.label, fontWeight: 500, background: "transparent", color: P.ink, border: `1px solid ${P.line2}`, borderRadius: RADIUS.lg, cursor: "pointer", fontFamily: "var(--cb-font)" }}>
              Students: full Pro for $7.99/mo
            </UIButton>
          </div>
        </div>
      )}
      {isPro && (
        <div style={{ marginTop: 32, fontSize: FONT_SIZES.small, color: P.faint, fontFamily: "var(--cb-font)", textAlign: "center" }}>
          Pro includes unlimited AI answers, document reads, and flowcharts.
        </div>
      )}
    </div>
  );
}

function TrendingView({ P, accent, at, isMobile, onAsk }) {
  const [status, setStatus] = useState("loading"); // "loading" | "ready" | "error"
  const [items, setItems] = useState([]);
  const [generatedAt, setGeneratedAt] = useState(0);
  const [expanded, setExpanded] = useState(null);
  // Forces the "Updated Xm ago" line to keep counting up between polls,
  // not just re-render whenever a fetch happens to land.
  const [, forceTick] = useState(0);
  // Bumped by the error state's "Try again" button below. The fetch lives
  // inside the effect (it owns the polling interval and the cancelled
  // flag), so a retry is expressed as a dependency change rather than by
  // hoisting load() out and losing that ownership.
  const [reloadTick, setReloadTick] = useState(0);
  // The feed now spans disciplines (see functions/lib/trendingSource.js),
  // so it needs a way to narrow to one. Built from the categories actually
  // present rather than a hardcoded list, so a source going down removes
  // its section instead of leaving a filter that finds nothing.
  const [trendCat, setTrendCat] = useState("All");
  // The endpoint reports feed health on every response (stale,
  // degraded). The view used to drop both on the floor, so a reader
  // could not tell a fresh edition from yesterday's leftovers.
  const [feedMeta, setFeedMeta] = useState({ stale: false, degraded: false });
  // Past editions: the endpoint archives one edition per day and the
  // masthead offers the recent ones. Viewing one is read only; the
  // poll guard below keeps background refreshes of the current
  // edition from clobbering the archive on screen.
  const [editions, setEditions] = useState([]);
  const [viewingEdition, setViewingEdition] = useState(null);
  const viewingEditionRef = useRef(null);
  const [newEdition, setNewEdition] = useState(false);
  const [missingSources, setMissingSources] = useState([]);
  // The citation completion leg reports itself in sourceHealth under
  // its own name ("Citation counts"). It is not a section of the
  // edition, so it never joins missingSources — a failed completion
  // leg is citation health, rendered as such below, not a missing
  // section that "did not answer".
  const [citationHealth, setCitationHealth] = useState(null);
  const [trendQuery, setTrendQuery] = useState("");
  const [trendSort, setTrendSort] = useState("edition");
  /* Viewport width from the shared hook: this view used to keep its
     own width state and resize listener, the same subscription
     useWindowWidth now owns for the whole app. */
  const winW = useWindowWidth();
  const narrow = winW < 560;

  useEffect(() => {
    let cancelled = false;
    let timer = null;

    const load = (isBackground) => {
      if (viewingEditionRef.current) return;
      if (!isBackground) {
        setStatus((s) => (s === "ready" ? s : "loading"));
        /* Her context on this tab, in the same nova-activity
           vocabulary the ask lifecycle uses: a foreground load is
           work starting, so the masthead Nova thinks while the
           edition is gathered and lands pleased or deadpan with
           the outcome below. Background polls stay silent. */
        emitNovaActivity("search", "start");
      }
      fetch("/api/trending")
        .then((res) => res.json().then((data) => ({ ok: res.ok, data })))
        .then(({ ok, data }) => {
          if (cancelled) return;
          if (!ok || !data || !Array.isArray(data.items) || data.items.length === 0) {
            // A background poll that comes back empty shouldn't nuke a
            // feed that's already on screen — only a genuine first-load
            // failure shows the error state. But the reader should be
            // told the edition on screen is aging: health reporting
            // used to vanish entirely after a successful first load.
            if (!isBackground) { setStatus("error"); emitNovaActivity("search", "failed"); }
            else setFeedMeta((prev) => ({ ...prev, stale: true }));
            return;
          }
          setItems(data.items);
          setGeneratedAt(data.generatedAt || Date.now());
          setFeedMeta({ stale: !!data.stale, degraded: !!data.degraded });
          if (Array.isArray(data.editions)) setEditions(data.editions);
          if (data.edition) {
            try {
              const lastSeen = window.localStorage.getItem("cb_trending_last_edition_v1");
              if (lastSeen && lastSeen !== data.edition) setNewEdition(true);
              window.localStorage.setItem("cb_trending_last_edition_v1", data.edition);
            } catch { /* private mode: the marker is a nicety */ }
          }
          if (Array.isArray(data.sourceHealth)) {
            setMissingSources(data.sourceHealth.filter((s) => s && s.source !== "Citation counts" && !s.ok).map((s) => s.source));
            setCitationHealth(data.sourceHealth.find((s) => s && s.source === "Citation counts") || null);
          }
          if (!isBackground) emitNovaActivity("search", "success");
          setStatus("ready");
        })
        .catch(() => {
          if (cancelled) return;
          if (!isBackground) { setStatus("error"); emitNovaActivity("search", "failed"); }
          else setFeedMeta((prev) => ({ ...prev, stale: true }));
        });
    };

    load(false);
    timer = setInterval(() => load(true), TRENDING_POLL_MS);
    const tickTimer = setInterval(() => forceTick((n) => n + 1), 30000);
    return () => { cancelled = true; clearInterval(timer); clearInterval(tickTimer); };
  }, [reloadTick]);

  const openEdition = (id) => {
    if (!id) return;
    setStatus("loading");
    fetch(`/api/trending?edition=${encodeURIComponent(id)}`)
      .then((res) => res.json().then((data) => ({ ok: res.ok, data })))
      .then(({ ok, data }) => {
        if (!ok || !data || !Array.isArray(data.items) || data.items.length === 0) { setStatus("error"); return; }
        viewingEditionRef.current = id;
        setViewingEdition(id);
        setItems(data.items);
        setGeneratedAt(data.generatedAt || 0);
        setFeedMeta({ stale: false, degraded: false });
        if (Array.isArray(data.editions)) setEditions(data.editions);
        if (Array.isArray(data.sourceHealth)) {
          setMissingSources(data.sourceHealth.filter((s) => s && s.source !== "Citation counts" && !s.ok).map((s) => s.source));
          setCitationHealth(data.sourceHealth.find((s) => s && s.source === "Citation counts") || null);
        }
        setExpanded(null);
        setStatus("ready");
      })
      .catch(() => setStatus("error"));
  };
  const backToCurrent = () => {
    viewingEditionRef.current = null;
    setViewingEdition(null);
    setReloadTick((n) => n + 1);
  };
  const fmtEditionDay = (ts) => new Date(ts).toLocaleDateString(undefined, { weekday: "short", month: "short", day: "numeric" });

  // Deduped here regardless of what the backend already did (see
  // dedupeTrendingItems above) — a safety net against a stale cache row or
  // a future source change, never a substitute for the server-side dedup.
  const deduped = useMemo(() => dedupeTrendingItems(items), [items]);
  // Reports of the same event group into one story with coverage.
  const stories = useMemo(() => clusterTrendingItems(deduped), [deduped]);
  // Citation counts: null means the source reported no count at all,
  // which is not a zero. Sorting and the rail only exist when at least
  // two stories carry a real positive count.
  const citedOf = (x) => (typeof x.citedByCount === "number" ? x.citedByCount : -1);
  const hasCitedData = stories.filter((x) => citedOf(x) > 0).length >= 2;
  // Citation health from the stories themselves: how many carry any
  // reported count at all (a reported zero counts as known). The
  // masthead states it, so the health the API computes is on screen,
  // not only in the payload.
  const citedKnownCount = stories.filter((x) => typeof x.citedByCount === "number").length;
  const effectiveSort = trendSort === "cited" && !hasCitedData ? "edition" : trendSort;
  // The category filter is applied once, here, so every view below is fed
  // the same already-narrowed list and no future view can forget it.
  const query = trendQuery.trim().toLowerCase();
  const filteredItems = stories.filter((x) => {
    if (trendCat !== "All" && x.category !== trendCat) return false;
    if (!query) return true;
    const hay = [x, ...((x && x.coverage) || [])].map((c) => `${c.title || ""} ${c.summary || ""} ${c.source || ""} ${c.category || ""}`).join(" ").toLowerCase();
    return hay.includes(query);
  });
  // The Most cited ordering ranks only the positive subset of the
  // view on screen; the disclosure under the sort states this count
  // against the view's size, so a two story ranking over a forty
  // story edition can never present itself as a ranking of forty.
  const citedRankedCount = filteredItems.filter((x) => citedOf(x) > 0).length;
  const visibleItems = effectiveSort === "edition"
    ? filteredItems
    : [...filteredItems].sort((a, b) => effectiveSort === "cited"
      ? citedOf(b) - citedOf(a)
      : effectiveSort === "trend"
        ? compareByTrend(a, b)
        : new Date(b.publishedAt || 0).getTime() - new Date(a.publishedAt || 0).getTime());
  const [hero, ...rest] = visibleItems;
  const categories = ["All", ...Array.from(new Set(stories.map((x) => x.category).filter(Boolean)))];
  const categoryCount = (cat) => (cat === "All" ? stories.length : stories.filter((x) => x.category === cat).length);
  const paperCount = stories.filter((x) => trendKind(x) !== "Press item").length;
  const pressCount = stories.length - paperCount;
  // The Newest rail belongs to the view on screen, not the unfiltered
  // edition: filtering used to pull unrelated stories back in through it.
  const newest = [...visibleItems].filter((x) => x.publishedAt).sort((a, b) => new Date(b.publishedAt).getTime() - new Date(a.publishedAt).getTime()).slice(0, 4);
  const isDefaultView = !query && trendCat === "All" && effectiveSort === "edition";
  const heroLabel = isDefaultView ? "First in the edition" : query ? "First match" : "First in this view";
  const pubTimes = stories.map((x) => new Date(x.publishedAt || 0).getTime()).filter((t) => t > 0);
  const fmtDay = (ts) => new Date(ts).toLocaleDateString(undefined, { month: "short", day: "numeric" });
  const pubRange = pubTimes.length > 1 && Math.max(...pubTimes) - Math.min(...pubTimes) > 86400000
    ? `Published ${fmtDay(Math.min(...pubTimes))} to ${fmtDay(Math.max(...pubTimes))}`
    : "";
  // Stories are addressable: opening one writes its key into the hash,
  // a shared or reloaded link reopens the same story, a link pasted
  // while the page is already open works too, and the back button
  // closes a story it opened. The first version restored once on load
  // and replaced state, so neither of those last two ever happened.
  const syncFromHash = useCallback(() => {
    try {
      const m = String(window.location.hash || "").match(/story=([^&]+)/);
      if (m) {
        const found = stories.find((x) => trendStoryKey(x) === decodeURIComponent(m[1]));
        if (found) { setExpanded(found); return; }
      }
      setExpanded((cur) => (cur ? null : cur));
    } catch { /* a malformed hash is not worth an error state */ }
  }, [stories]);
  useEffect(() => {
    if (status !== "ready") return;
    syncFromHash();
    window.addEventListener("hashchange", syncFromHash);
    window.addEventListener("popstate", syncFromHash);
    return () => {
      window.removeEventListener("hashchange", syncFromHash);
      window.removeEventListener("popstate", syncFromHash);
    };
  }, [status, syncFromHash]);
  const prevExpandedRef = useRef(null);
  useEffect(() => {
    try {
      const base = window.location.pathname + window.location.search;
      const prev = prevExpandedRef.current;
      if (expanded) {
        const hash = `#story=${encodeURIComponent(trendStoryKey(expanded))}`;
        if (window.location.hash !== hash) {
          if (!prev) window.history.pushState(null, "", `${base}${hash}`);
          else window.history.replaceState(null, "", `${base}${hash}`);
        }
      } else if (String(window.location.hash || "").includes("story=")) {
        window.history.replaceState(null, "", base);
      }
      prevExpandedRef.current = expanded;
    } catch { /* history is a nicety, not a dependency */ }
  }, [expanded]);

  // A newspaper dateline, not a "Live" badge. The feed refreshes on a real
  // hourly clock; the honest signal is when this edition was printed.
  const dateline = generatedAt
    ? new Date(generatedAt).toLocaleDateString(undefined, { weekday: "long", month: "long", day: "numeric" })
    : "";

  return (
    <div style={{ flex: 1, minHeight: 0 }}>
      <div style={{ maxWidth: 1180, width: "100%", margin: "0 auto", padding: isMobile ? "72px 18px 48px" : "34px 32px 68px" }}>
        {/* ══════════════════════════════════════════════════════
            The masthead. Trending is a daily edition, not a dashboard:
            nameplate, dateline, and the one honest disclaimer, ruled off
            from the stories like a front page. No pulse dot, no "Live"
            badge — the feed refreshes hourly and says so in words.
            ══════════════════════════════════════════════════════ */}
        <div style={{ marginBottom: 26, borderBottom: `2px solid ${P.ink}`, paddingBottom: 18 }}>
          {/* The resident header Nova (2026-10-15), left of the
              nameplate at the learning home's 66px class. The
              masthead block below her stays a newspaper block;
              she is the screen's one resident figure. */}
          <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
            <span aria-hidden="true" style={{ flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center" }}>
              <NovaLive size={66} />
            </span>
            <h1 style={{ margin: 0, fontSize: FONT_SIZES.hero * 0.7, fontWeight: 500, letterSpacing: TYPE.heading.letterSpacing, color: P.ink, fontFamily: "var(--cb-font)", lineHeight: 1.1 }}>Trending in Science</h1>
          </div>
          <div style={{ display: "flex", alignItems: "baseline", gap: 8, marginTop: 10, flexWrap: "wrap" }}>
            <span style={{ fontSize: FONT_SIZES.caption, fontWeight: 500, color: P.ink2, fontFamily: "var(--cb-font)", letterSpacing: TRACKING.tight }}>
              {dateline}{dateline ? "  ·  " : ""}Refreshed hourly from real science press
            </span>
          </div>
          <div style={{ fontSize: FONT_SIZES.small, color: P.faint, marginTop: 8, maxWidth: 640, lineHeight: 1.6 }}>
            Not curated by us, not fact checked like an answer. Read the source before you cite it.
          </div>
          <div style={{ fontSize: FONT_SIZES.caption, color: P.faint, marginTop: 6, maxWidth: 640, lineHeight: 1.6 }}>
            How this edition is built: recent stories from four sources, balanced across sections in source order. It is not ranked by clicks, shares, or citation speed.
          </div>
          {status === "ready" && stories.length > 0 && (
            <div style={{ display: "flex", flexWrap: "wrap", gap: "8px 22px", marginTop: 14, fontSize: FONT_SIZES.caption, color: P.faint, fontFamily: "var(--cb-font)" }}>
              <span><strong style={{ color: P.ink, fontVariantNumeric: "tabular-nums" }}>{stories.length}</strong> stories in this edition</span>
              <span><strong style={{ color: P.ink, fontVariantNumeric: "tabular-nums" }}>{paperCount}</strong> papers and preprints</span>
              <span><strong style={{ color: P.ink, fontVariantNumeric: "tabular-nums" }}>{pressCount}</strong> press reports</span>
              <span><strong style={{ color: P.ink, fontVariantNumeric: "tabular-nums" }}>{citedKnownCount}</strong> of {stories.length} stories carry a citation count</span>
              {pubRange && <span>{pubRange}</span>}
              {generatedAt > 0 && <span>Updated {relativeTime(generatedAt)}</span>}
            </div>
          )}
          {status === "ready" && editions.length > 1 && (
            <div style={{ display: "flex", alignItems: "center", gap: 12, flexWrap: "wrap", marginTop: 14, fontSize: FONT_SIZES.caption, color: P.faint, fontFamily: "var(--cb-font)" }}>
              <label style={{ display: "inline-flex", alignItems: "center", gap: 8 }}>
                Edition
                <select aria-label="Choose an edition" value={viewingEdition || ""}
                  onChange={(e) => { const v = e.target.value; if (v) openEdition(v); else backToCurrent(); }}
                  style={{ minHeight: 44, padding: "6px 10px", borderRadius: RADIUS.md, border: `1px solid ${P.line}`, background: P.bg, color: P.ink, fontFamily: "var(--cb-font)", fontSize: 16, cursor: "pointer" }}>
                  <option value="">Current edition</option>
                  {editions.slice(1).map((e) => (
                    <option key={e.id} value={e.id}>{fmtEditionDay(e.generatedAt)}</option>
                  ))}
                </select>
              </label>
              {newEdition && !viewingEdition && <span style={{ color: P.ink2, fontWeight: 500 }}>New edition since your last visit</span>}
            </div>
          )}
          {status === "ready" && viewingEdition && (
            <div role="status" style={{ marginTop: 12, fontSize: FONT_SIZES.caption, color: P.ink2, background: withAlpha(accent, 0.08), border: `1px solid ${withAlpha(accent, 0.3)}`, borderRadius: RADIUS.md, padding: "9px 13px", maxWidth: 640, lineHeight: 1.55, display: "flex", alignItems: "center", gap: 12, flexWrap: "wrap" }}>
              <span>You are reading a past edition, as it was gathered on {fmtEditionDay(generatedAt)}. It does not update.</span>
              <button type="button" onClick={backToCurrent}
                style={{ minHeight: 44, padding: "6px 12px", borderRadius: RADIUS.pill, border: `1px solid ${P.line}`, background: P.bg, color: P.ink, fontFamily: "var(--cb-font)", fontSize: FONT_SIZES.caption, fontWeight: 500, cursor: "pointer" }}>
                Back to the current edition
              </button>
            </div>
          )}
          {status === "ready" && missingSources.length > 0 && (
            <div role="status" style={{ marginTop: 12, fontSize: FONT_SIZES.caption, color: P.ink2, background: withAlpha(STATUS.warn, 0.1), border: `1px solid ${withAlpha(STATUS.warn, 0.3)}`, borderRadius: RADIUS.md, padding: "9px 13px", maxWidth: 640, lineHeight: 1.55 }}>
              Missing this round: {missingSources.join(", ")}. That section is absent because its source did not answer, not because nothing was published.
            </div>
          )}
          {status === "ready" && citationHealth && !citationHealth.ok && citationHealth.attempted > 0 && (
            <div role="status" style={{ marginTop: 12, fontSize: FONT_SIZES.caption, color: P.ink2, background: withAlpha(STATUS.warn, 0.1), border: `1px solid ${withAlpha(STATUS.warn, 0.3)}`, borderRadius: RADIUS.md, padding: "9px 13px", maxWidth: 640, lineHeight: 1.55 }}>
              {citationHealth.resolved > 0 ? (
                <>Citation counts are partial this round: {citationHealth.resolved} of {citationHealth.attempted} counts resolved{citationHealth.error ? ` (${citationHealth.error})` : ""}{/429/.test(citationHealth.error || "") ? ". A provider was rate limited, so the rest could not be checked" : ""}. Stories without a count below are ones their own sources did not report either.</>
              ) : (
                <>Citation counts could not be completed this round{citationHealth.error ? `: ${citationHealth.error}` : ""}. The counts on the stories below are the ones their own sources reported.</>
              )}
            </div>
          )}
          {status === "ready" && (feedMeta.degraded || feedMeta.stale) && (
            <div role="status" style={{ marginTop: 12, fontSize: FONT_SIZES.caption, color: P.ink2, background: withAlpha(STATUS.warn, 0.1), border: `1px solid ${withAlpha(STATUS.warn, 0.3)}`, borderRadius: RADIUS.md, padding: "9px 13px", maxWidth: 640, lineHeight: 1.55 }}>
              {feedMeta.degraded
                ? "The live feed did not answer, so this is the last good edition. Stories stay readable while it recovers."
                : "A fresher edition is being gathered in the background. This one stays up until it lands."}
            </div>
          )}
        </div>

        {/* ══════════════════════════════════════════════════════
            Sections. A newspaper's section index as filter pills,
            matching the search mode-plate recipe: the active section
            sits in an accent wash, the rest in quiet ink tint. Same
            filtering behavior — the middot separators are retired.
            ══════════════════════════════════════════════════════ */}
        {status === "ready" && categories.length > 1 && (
          <nav aria-label="Filter by section" style={{ display: "flex", flexWrap: "wrap", gap: 7, marginBottom: 22 }}>
            {categories.map((cat) => {
              const on = trendCat === cat;
              return (
                <UIButton P={P} variant="ghost"
                  key={cat}
                  type="button"
                  onClick={() => setTrendCat(cat)}
                  aria-pressed={on}
                  style={{
                    minHeight: 44, padding: "9px 16px", borderRadius: RADIUS.viewport, cursor: "pointer",
                    fontSize: FONT_SIZES.caption, fontFamily: "var(--cb-font)", letterSpacing: "0",
                    fontWeight: on ? 500 : 500,
                    background: on ? withAlpha(accent, 0.24) : withAlpha(P.ink, 0.06),
                    color: on ? P.ink : P.ink2,
                    border: `1px solid ${on ? withAlpha(accent, 0.42) : P.line}`,
                  }}
                >{cat}<span style={{ opacity: 0.6, marginLeft: 6, fontVariantNumeric: "tabular-nums" }}>{categoryCount(cat)}</span></UIButton>
              );
            })}
          </nav>
        )}

        {status === "ready" && (
          <div style={{ display: "flex", flexWrap: "wrap", gap: 14, alignItems: "center", justifyContent: "space-between", marginBottom: 22 }}>
            <div style={{ flex: "1 1 260px", maxWidth: 420 }}>
              <input value={trendQuery} onChange={(e) => setTrendQuery(e.target.value)} placeholder="Search this edition" aria-label="Search this edition"
                style={{ width: "100%", boxSizing: "border-box", padding: "11px 14px", borderRadius: RADIUS.lg, border: `1px solid ${P.line}`, background: P.surface, color: P.ink, fontFamily: "var(--cb-font)", fontSize: 16 }} />
            </div>
            <div role="group" aria-label="Sort stories" style={{ display: "inline-flex", flexWrap: "wrap", gap: 4 }}>
              {[{ id: "edition", label: "Edition order" }, { id: "trend", label: "Trending" }, ...(hasCitedData ? [{ id: "cited", label: "Most cited" }] : []), { id: "newest", label: "Newest" }].map((o) => {
                const on = effectiveSort === o.id;
                return (
                  <button key={o.id} type="button" onClick={() => setTrendSort(o.id)} aria-pressed={on}
                    style={{ minHeight: 44, padding: "9px 14px", borderRadius: RADIUS.pill, cursor: "pointer", fontFamily: "var(--cb-font)", fontSize: FONT_SIZES.caption, fontWeight: on ? 500 : 500, background: on ? withAlpha(accent, 0.24) : "transparent", color: on ? P.ink : P.ink2, border: `1px solid ${on ? withAlpha(accent, 0.42) : P.line}` }}>
                    {o.label}
                  </button>
                );
              })}
            </div>
          </div>
        )}

        {/* A loading state is a line of text, not six shimmering cards.
            The feed takes a moment; it says so, quietly. */}
        {status === "loading" && (
          <div style={{ padding: "72px 0", textAlign: "center" }}>
            <div style={{ fontSize: FONT_SIZES.body, color: P.faint, fontFamily: "var(--cb-font)" }}>
              Gathering the latest science stories…
            </div>
          </div>
        )}

        {/* An error state is a screen a real person actually lands on, so it
            gets the same treatment as any other: a contained surface rather
            than text floating in the middle of an empty page, a headline
            separated from the explanation, and — the part that was actually
            missing — a way to act on it. Telling someone to "try again in a
            moment" without giving them a button to do it with is a dead
            end dressed up as guidance. */}
        {status === "error" && (
          <div style={{
            maxWidth: 460, margin: "56px auto", textAlign: "center",
            padding: "36px 32px", borderRadius: RADIUS.lg,
            background: P.dark ? "rgba(255,255,255,0.025)" : "rgba(0,0,0,0.015)",
            border: `1px solid ${P.line}`,
          }} className="cb-rise">
            <div aria-hidden="true" style={{
              width: 48, height: 48, borderRadius: "50%", margin: "0 auto 18px",
              display: "flex", alignItems: "center", justifyContent: "center",
              background: withAlpha(STATUS.bad, 0.1),
              border: `1px solid ${withAlpha(STATUS.bad, 0.25)}`,
            }}>
              <Icon name="warning" size={22} style={{ color: statusBad(P) }} />
            </div>
            <div style={{ fontSize: FONT_SIZES.subhead, fontWeight: 500, color: P.ink, marginBottom: 8 }}>
              Trending feed didn&apos;t load
            </div>
            <div style={{ fontSize: FONT_SIZES.small, color: P.ink2, lineHeight: 1.6, marginBottom: 22 }}>
              The upstream science feed didn&apos;t answer. It&apos;s usually busy rather than
              down, so a retry in a few seconds normally works.
            </div>
            <UIButton P={P} variant="ghost"
              onClick={() => setReloadTick((t) => t + 1)}
              style={{ minHeight: 44,
                padding: "12px 22px", borderRadius: RADIUS.sm, cursor: "pointer",
                fontSize: FONT_SIZES.small, fontWeight: 500, fontFamily: "var(--cb-font)",
                background: accent, color: at, border: "none",
              }}
            >Try again</UIButton>
          </div>
        )}

        {status === "ready" && (
          <>
            {visibleItems.length === 0 && (
              <WorkspaceEmpty P={P} accent={accent} icon="chart" isMobile={isMobile}
                title="Nothing in this edition matches"
                body={query ? `No story here matches "${trendQuery.trim()}". Clear the search or pick another section.` : "This section has no stories in the current edition. Pick another section above, or read the whole edition."}
                action={(
                  <UIButton P={P} variant="ghost" onClick={() => { setTrendQuery(""); setTrendCat("All"); }}
                    style={{ minHeight: 44, padding: "10px 20px", borderRadius: RADIUS.pill, background: accent, color: at, border: "none", fontSize: FONT_SIZES.small, fontWeight: 500, fontFamily: "var(--cb-font)", cursor: "pointer" }}
                  >Show the whole edition</UIButton>
                )} />
            )}
            {/* The Most cited ordering discloses its own basis: it ranks
                only the stories with a positive count, and the rest are
                not ranked at all. Without this line a two story ranking
                over a forty story edition reads as a ranking of forty. */}
            {effectiveSort === "cited" && visibleItems.length > 0 && (
              <div style={{ fontSize: FONT_SIZES.caption, color: P.faint, fontFamily: "var(--cb-font)", lineHeight: 1.55, marginBottom: 18 }}>
                Ranked by citation count, most cited first. {citedRankedCount} of {filteredItems.length} stories in this view have a count above zero. Stories without a reported count are not ranked; they follow in edition order.
              </div>
            )}
            {/* The lead story, full width. The digest below is the index;
                this is the front-page feature. */}
            {hero && <div style={{ marginBottom: 26 }}><TrendingHero P={P} accent={accent} at={at} item={hero} onExpand={setExpanded} generatedAt={generatedAt} isMobile={isMobile} heroLabel={heroLabel} /></div>}
            {visibleItems.length > 0 && newest.length > 1 && (
              <div style={{ marginBottom: 28 }}>
                <TrendRailList P={P} title={isDefaultView ? "Newest in this edition" : "Newest in this view"} items={newest} onExpand={setExpanded} generatedAt={generatedAt} mode="newest" />
              </div>
            )}
            {/* ══════════════════════════════════════════════════
                The digest. One ruled line per story: number, headline,
                summary, and the source line. The whole day fits on a
                screen — you scan it, then open the two things worth
                reading. This used to be one tab of two; the card grid
                was the generic news-template residue and it is gone.
                ══════════════════════════════════════════════════ */}
            {rest.length > 0 && (
              <div style={{ display: "flex", alignItems: "baseline", justifyContent: "space-between", gap: 12, margin: "2px 0 2px" }}>
                <h2 style={{ margin: 0, fontSize: FONT_SIZES.title, fontWeight: 500, color: P.ink, fontFamily: "var(--cb-font)", letterSpacing: TYPE.heading.letterSpacing }}>The digest</h2>
                <span style={{ fontSize: FONT_SIZES.caption, color: P.faint, fontFamily: "var(--cb-font)" }}>{rest.length} more {rest.length === 1 ? "story" : "stories"}</span>
              </div>
            )}
            {rest.length > 0 && (<div style={{ borderTop: `1px solid ${P.line}` }} className="cb-stagger">
              {rest.map((item, i) => (
                <button key={item.url || i} onClick={() => setExpanded(item)} className="cb-row"
                  style={{
                    display: "flex", flexDirection: narrow ? "column" : "row", alignItems: narrow ? "stretch" : "baseline", gap: narrow ? 6 : 16, width: "100%", textAlign: "left",
                    padding: "24px 6px", background: "transparent", border: "none",
                    borderBottom: `1px solid ${P.line}`, cursor: "pointer", fontFamily: "var(--cb-font)",
                  }}
                >
                  {!narrow && <span style={{ fontSize: FONT_SIZES.small, color: P.faint, fontFamily: "var(--cb-font)", width: 32, flexShrink: 0, fontWeight: 500, fontVariantNumeric: "tabular-nums" }}>{String(i + 1).padStart(2, "0")}</span>}
                  <span style={{ flex: 1, minWidth: 0 }}>
                    <span style={{ display: "block", fontSize: FONT_SIZES.body, fontWeight: 500, color: P.ink, lineHeight: 1.45 }}>{renderInlineMdLite(item.title, P)}</span>
                    {item.summary ? (
                      <span style={{ fontSize: FONT_SIZES.small, color: P.ink2, lineHeight: 1.6, marginTop: 6, display: "-webkit-box", WebkitLineClamp: 2, WebkitBoxOrient: "vertical", overflow: "hidden" }}>{renderInlineMdLite(item.summary, P)}</span>
                    ) : (
                      <span style={{ fontSize: FONT_SIZES.small, color: P.faint, lineHeight: 1.6, marginTop: 6, display: "block", fontStyle: "italic" }}>No summary was published with this record.</span>
                    )}
                    <span style={{ display: "block", fontSize: FONT_SIZES.caption, color: P.faint, marginTop: 8 }}>
                      {trendProvenance(item, generatedAt)}
                    </span>
                    {item.coverageCount > 1 && (
                      <span style={{ display: "block", fontSize: FONT_SIZES.caption, color: P.faint, marginTop: 4 }}>
                        Covered by {item.coverageCount} reports
                      </span>
                    )}
                    {trendImageCredit(item) && (
                      <span style={{ display: "block", fontSize: FONT_SIZES.micro, color: P.faint, marginTop: 4 }}>
                        Image: {trendImageCredit(item)}
                      </span>
                    )}
                  </span>
                  {/* Verified lead media as a small thumb. On narrow
                      phones the row goes full width text instead, so a
                      headline never gets squeezed beside a thumbnail. */}
                  {!narrow && <TrendThumb P={P} media={trendingMediaOf(item)} title={(item.title || "").replace(/\*/g, "")} />}
                </button>
              ))}
            </div>)}
          </>
        )}
      </div>
      {expanded && (
        <TrendingArticleModal
          P={P} accent={accent} at={at} item={expanded}
          close={() => setExpanded(null)}
          onAsk={onAsk}
          upNext={(() => {
            // Relevance, not list adjacency: same section first, then
            // shared title words with the story being read.
            const curTokens = trendTitleTokens(expanded.title);
            return visibleItems
              .filter((x) => trendStoryKey(x) !== trendStoryKey(expanded))
              .map((x) => {
                const toks = trendTitleTokens(x.title);
                let shared = 0;
                for (const w of toks) if (curTokens.has(w)) shared++;
                return { x, score: (x.category === expanded.category ? 3 : 0) + Math.min(shared, 4) };
              })
              .sort((a, b) => b.score - a.score)
              .slice(0, 4)
              .map((r) => r.x);
          })()}
          onOpenItem={(nx) => setExpanded(nx)}
        />
      )}
    </div>
  );
}


function LiteratureTimeline({ P, accent, at, turn, close }) {
  /* The Plot|Arc toggle is gone — the Arc is the only view. The scatter
     plot survives only as the year-strip inside each era header (see
     EraYearStrip): dots = papers, position = year. Zero backend. */
  const sources = (turn && turn.sources) || [];
  const eras = useMemo(() => groupSourcesIntoEras(sources), [sources]);
  return (
    <ModalChrome media label="The arc of this literature" eyebrow="Evidence" title="The arc of this literature" accent={accent} width={880} tall onClose={close}>
      <div style={{ fontSize: FONT_SIZES.caption, color: "rgba(242,244,242,0.6)", lineHeight: 1.6, margin: "2px 0 4px" }}>
        The story the cited years tell: foundations, building, current.
      </div>
      {!eras ? (
        <div style={{ padding: "36px 12px", textAlign: "center", color: "rgba(242,244,242,0.55)", fontSize: FONT_SIZES.small, lineHeight: 1.6 }}>
          Not enough distinct publication years among these sources to draw an arc.
        </div>
      ) : (
        <div style={{ margin: "0 -22px -22px" }}>
          <AnswerArc turn={turn} P={P.dark ? P : PALETTES.Dark} accent={accent} />
        </div>
      )}
    </ModalChrome>
  );
}

/* ══════════════════════════════════════════════════════════════════
   Flowchart Studio

   A real diagram instrument: typed nodes (start / process / decision /
   input-output / evidence / end), connectable labeled edges,
   auto-layout, undo/redo, pan/zoom, and honest exports (SVG, PNG,
   Markdown outline). "Draft from answer" turns the current answer's
   steps into a starting graph — always labelled a draft, always
   reviewable, because a flowchart that invents structure is worse
   than no flowchart. Charts persist to localStorage (cb_flowcharts) as the
   offline cache and sync to the account (user_flowcharts) when signed in,
   and surface in the Library.
   ══════════════════════════════════════════════════════════════════ */

/* Node geometry, redesigned for terse labels: wider, taller, more air —
   a 52-char label sets in two calm lines at 15px with a mono step kicker
   above it, instead of four cramped lines at 13.5px. */
const FC_NODE_TYPES = {
  start:    { name: "Start",          w: 148, h: 58  },
  process:  { name: "Process",        w: 200, h: 92  },
  decision: { name: "Decision",       w: 200, h: 132 },
  io:       { name: "Input / Output", w: 200, h: 80  },
  evidence: { name: "Evidence",       w: 208, h: 104 },
  end:      { name: "End",            w: 148, h: 58  },
};
const FC_ORDER = ["start", "process", "decision", "io", "evidence", "end"];
const FC_GAP_Y = 104;

let fcSeq = 0;
function fcId(p) { fcSeq += 1; return `fc-${p}-${Date.now().toString(36)}-${fcSeq.toString(36)}`; }

// Sign-in merge for evidence maps: the account's copy wins on id conflicts,
// charts that exist only in this browser are kept (never silently dropped),
// and the result is most-recent-first. Pure so the sync tests can cover it.
function mergeFlowcharts(serverCharts, localCharts) {
  const server = Array.isArray(serverCharts) ? serverCharts : [];
  const local = Array.isArray(localCharts) ? localCharts : [];
  const serverIds = new Set(server.map((c) => c && c.id));
  const merged = [...server, ...local.filter((c) => c && !serverIds.has(c.id))];
  merged.sort((a, b) => (b.updatedAt || 0) - (a.updatedAt || 0));
  return merged;
}

function fcNewNode(type, x, y, label, extra = {}) {
  const t = FC_NODE_TYPES[type] || FC_NODE_TYPES.process;
  return { id: fcId("n"), type, x: Math.round(x), y: Math.round(y), w: t.w, h: t.h, label: label || t.name, ...extra };
}
function fcNewEdge(from, to, label = "") { return { id: fcId("e"), from, to, label }; }
function fcNodeById(nodes, id) { return nodes.find((n) => n.id === id); }
function fcSlug(s) { return (s || "flowchart").replace(/[^\w\- ]+/g, "").trim().replace(/\s+/g, "-").toLowerCase().slice(0, 60) || "flowchart"; }

/* Word-wrap a label into lines that fit ~maxChars each. */
function fcWrap(label, maxChars) {
  const words = String(label || "").split(/\s+/).filter(Boolean);
  const lines = [];
  let cur = "";
  for (const w of words) {
    const next = cur ? cur + " " + w : w;
    if (next.length > maxChars && cur) { lines.push(cur); cur = w; }
    else cur = next;
  }
  if (cur) lines.push(cur);
  return lines.length ? lines : [""];
}

/* ── Edge geometry: pick the closest port pair, route a bezier ── */
function fcPorts(n) {
  const cx = n.x + n.w / 2, cy = n.y + n.h / 2;
  return [
    { x: cx, y: n.y, side: "t" },
    { x: n.x + n.w, y: cy, side: "r" },
    { x: cx, y: n.y + n.h, side: "b" },
    { x: n.x, y: cy, side: "l" },
  ];
}
function fcEdgeGeom(a, b) {
  const pa = fcPorts(a), pb = fcPorts(b);
  let best = null;
  for (const p of pa) for (const q of pb) {
    const d = (p.x - q.x) * (p.x - q.x) + (p.y - q.y) * (p.y - q.y);
    if (!best || d < best.d) best = { p, q, d };
  }
  const { p, q } = best;
  const dir = (pt) => (pt.side === "t" ? [0, -1] : pt.side === "b" ? [0, 1] : pt.side === "l" ? [-1, 0] : [1, 0]);
  const [dx1, dy1] = dir(p), [dx2, dy2] = dir(q);
  const dist = Math.sqrt(best.d) || 1;
  const k = Math.min(90, Math.max(30, dist * 0.35));
  return {
    d: `M ${p.x} ${p.y} C ${p.x + dx1 * k} ${p.y + dy1 * k}, ${q.x + dx2 * k} ${q.y + dy2 * k}, ${q.x} ${q.y}`,
    mx: (p.x + q.x) / 2, my: (p.y + q.y) / 2,
  };
}

/* ── Layered auto-layout: topological layers, centered ── */
function fcAutoLayout(nodes, edges) {
  if (!nodes.length) return nodes;
  const result = nodes.map((n) => ({ ...n }));
  /* No connections yet: a single centered column reads better than a
     1200px-wide row that pushes nodes off-screen. */
  if (!edges.length) {
    let y = 60;
    const cx = 600;
    [...result].sort((a, b) => a.y - b.y || a.x - b.x).forEach((n) => {
      n.x = Math.round(cx - n.w / 2);
      n.y = Math.round(y);
      y += n.h + FC_GAP_Y;
    });
    return result;
  }
  const byId = new Map(nodes.map((n) => [n.id, n]));
  const incoming = new Map(nodes.map((n) => [n.id, 0]));
  const out = new Map(nodes.map((n) => [n.id, []]));
  for (const e of edges) {
    if (e.from !== e.to && byId.has(e.from) && byId.has(e.to)) {
      out.get(e.from).push(e.to);
      incoming.set(e.to, incoming.get(e.to) + 1);
    }
  }
  const order = [...nodes].sort((a, b) => a.x - b.x);
  const layer = new Map();
  const queue = order.filter((n) => incoming.get(n.id) === 0);
  queue.forEach((n) => layer.set(n.id, 0));
  const q = [...queue];
  const inQueue = new Set(q.map((n) => n.id));
  while (q.length) {
    const n = q.shift();
    for (const t of out.get(n.id)) {
      const nl = layer.get(n.id) + 1;
      if (!layer.has(t) || layer.get(t) < nl) layer.set(t, nl);
      if (!inQueue.has(t)) { inQueue.add(t); q.push(byId.get(t)); }
    }
  }
  let maxL = 0;
  for (const v of layer.values()) maxL = Math.max(maxL, v);
  for (const n of nodes) if (!layer.has(n.id)) layer.set(n.id, maxL + 1);
  const layers = new Map();
  for (const n of order) {
    const l = layer.get(n.id);
    if (!layers.has(l)) layers.set(l, []);
    layers.get(l).push(n);
  }
  const rById = new Map(result.map((n) => [n.id, n]));
  const totalW = 1200;
  [...layers.keys()].sort((a, b) => a - b).forEach((l, li) => {
    const arr = layers.get(l);
    const y = 60 + li * 172;
    arr.forEach((n, i) => {
      const c = rById.get(n.id);
      const slotW = totalW / arr.length;
      c.x = Math.round(slotW * i + slotW / 2 - c.w / 2);
      c.y = Math.round(y + (104 - Math.min(c.h, 104)) / 2);
    });
  });
  return result;
}

/* ── Draft from answer: extract steps, never invent them ──
   Labels go through fcCompressStep (src/fcLabel.js): a few words per node,
   compressed by deleting filler — never a 96-char slice with "…". Steps
   that carried citations in the answer become evidence nodes grounded to
   the real paper (sourceIdx into `sources`); the full source sentence is
   kept on node.detail so the inspector can show what the label compressed. */
function fcDraftFromAnswer(text, sources) {
  const rawSteps = fcExtractSteps(text, 7);
  if (!rawSteps.length) return null;
  const srcCount = Array.isArray(sources) ? sources.length : 0;
  const nodes = [];
  const edges = [];
  const cx = 600;
  let y = 60;
  const addStep = (type, label, extra = {}) => {
    const t = FC_NODE_TYPES[type];
    const n = fcNewNode(type, cx - t.w / 2, y, label, extra);
    nodes.push(n);
    y += t.h + FC_GAP_Y;
    return n;
  };
  const start = addStep("start", "Start");
  let prev = start;
  rawSteps.forEach((st, i) => {
    const label = fcCompressStep(st.text);
    const isDecision = /^(if|when|whether)\b/i.test(st.text) || /\bdepends on\b/i.test(st.text);
    // A step that cited a paper is evidence, not prose: ground the node to
    // the real source. Citation indices are 1-based; anything out of range
    // is ignored rather than guessed at.
    const citeIdx = st.cites.find((n) => n >= 1 && n <= srcCount);
    const type = typeof citeIdx === "number" ? "evidence" : isDecision ? "decision" : "process";
    const n = addStep(type, label, {
      step: i + 1,
      ...(st.text !== label ? { detail: st.text } : {}),
      ...(typeof citeIdx === "number" ? { sourceIdx: citeIdx - 1 } : {}),
    });
    edges.push(fcNewEdge(prev.id, n.id, prev.type === "decision" ? "yes" : ""));
    prev = n;
  });
  const end = addStep("end", "End");
  edges.push(fcNewEdge(prev.id, end.id, prev.type === "decision" ? "yes" : ""));
  return { nodes: fcAutoLayout(nodes, edges), edges, isDraft: true };
}

/* ── Export helpers ── */
function fcEsc(s) {
  return String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}
function fcBounds(nodes, pad = 60) {
  if (!nodes.length) return { x: 0, y: 0, w: 800, h: 600 };
  let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
  for (const n of nodes) {
    x0 = Math.min(x0, n.x); y0 = Math.min(y0, n.y);
    x1 = Math.max(x1, n.x + n.w); y1 = Math.max(y1, n.y + n.h);
  }
  return { x: x0 - pad, y: y0 - pad, w: x1 - x0 + pad * 2, h: y1 - y0 + pad * 2 };
}
const FC_EXPORT_COLORS = {
  bg: "#ffffff", fill: "#f6f7f6", stroke: "#232723", text: "#161916",
  accent: "#2e7d52", accentText: "#ffffff", edge: "#5b625b", decisionFill: "#eef4ef",
};
function fcNodeSvg(n) {
  const C = FC_EXPORT_COLORS;
  const cx = n.x + n.w / 2, cy = n.y + n.h / 2;
  const lines = fcWrap(n.label, Math.max(8, Math.floor((n.w - 30) / 7)));
  const lh = 16;
  const ty = cy - ((lines.length - 1) * lh) / 2 + 5;
  const isAccent = n.type === "start" || n.type === "end";
  const textFill = isAccent ? C.accentText : C.text;
  const text = lines.map((ln, i) => `<text x="${cx}" y="${(ty + i * lh).toFixed(1)}" text-anchor="middle" font-family="Inter, system-ui, sans-serif" font-size="13" fill="${textFill}">${fcEsc(ln)}</text>`).join("");
  let shape = "";
  if (n.type === "start" || n.type === "end") {
    shape = `<rect x="${n.x}" y="${n.y}" width="${n.w}" height="${n.h}" rx="${n.h / 2}" fill="${C.accent}"/>`;
  } else if (n.type === "decision") {
    shape = `<polygon points="${cx},${n.y} ${n.x + n.w},${cy} ${cx},${n.y + n.h} ${n.x},${cy}" fill="${C.decisionFill}" stroke="${C.accent}" stroke-width="1.6"/>`;
  } else if (n.type === "io") {
    const s = 22;
    shape = `<polygon points="${n.x + s},${n.y} ${n.x + n.w},${n.y} ${n.x + n.w - s},${n.y + n.h} ${n.x},${n.y + n.h}" fill="${C.fill}" stroke="${C.stroke}" stroke-width="1.5"/>`;
  } else if (n.type === "evidence") {
    shape = `<rect x="${n.x}" y="${n.y}" width="${n.w}" height="${n.h}" rx="10" fill="${C.fill}" stroke="${C.accent}" stroke-width="1.6"/><rect x="${n.x}" y="${n.y}" width="5" height="${n.h}" rx="2.5" fill="${C.accent}"/>`;
  } else {
    shape = `<rect x="${n.x}" y="${n.y}" width="${n.w}" height="${n.h}" rx="10" fill="${C.fill}" stroke="${C.stroke}" stroke-width="1.5"/>`;
  }
  return `<g>${shape}${text}</g>`;
}
function fcSvgString(nodes, edges, title) {
  const C = FC_EXPORT_COLORS;
  const b = fcBounds(nodes);
  const byId = new Map(nodes.map((n) => [n.id, n]));
  const edgeSvg = edges.map((e) => {
    const a = byId.get(e.from), bb = byId.get(e.to);
    if (!a || !bb) return "";
    const g = fcEdgeGeom(a, bb);
    const lbl = e.label ? `<text x="${g.mx}" y="${(g.my - 7).toFixed(1)}" text-anchor="middle" font-family="Inter, system-ui, sans-serif" font-size="11" font-style="italic" fill="${C.edge}">${fcEsc(e.label)}</text>` : "";
    return `<path d="${g.d}" fill="none" stroke="${C.edge}" stroke-width="1.6" marker-end="url(#fcArrow)"/>${lbl}`;
  }).join("");
  const nodeSvg = nodes.map(fcNodeSvg).join("");
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${Math.ceil(b.w)}" height="${Math.ceil(b.h)}" viewBox="${b.x} ${b.y} ${b.w} ${b.h}"><title>${fcEsc(title || "Flowchart")}</title><defs><marker id="fcArrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M 0 1 L 9 5 L 0 9 z" fill="${C.edge}"/></marker></defs><rect x="${b.x}" y="${b.y}" width="${b.w}" height="${b.h}" fill="${C.bg}"/>${edgeSvg}${nodeSvg}</svg>`;
}
function fcToMarkdown(nodes, edges, title) {
  const byId = new Map(nodes.map((n) => [n.id, n]));
  const out = new Map(nodes.map((n) => [n.id, []]));
  const incoming = new Map(nodes.map((n) => [n.id, 0]));
  for (const e of edges) {
    if (e.from !== e.to && byId.has(e.from) && byId.has(e.to)) {
      out.get(e.from).push(e);
      incoming.set(e.to, incoming.get(e.to) + 1);
    }
  }
  const roots = nodes.filter((n) => incoming.get(n.id) === 0);
  const startNodes = roots.length ? roots : nodes.slice(0, 1);
  const lines = [`# ${title || "Flowchart"}`, ""];
  const seen = new Set();
  const tag = { start: "Start", end: "End", decision: "Decision", io: "Input/Output", evidence: "Evidence", process: "Step" };
  const walk = (n, depth, viaLabel) => {
    if (!n) return;
    if (seen.has(n.id)) { lines.push(`${"  ".repeat(depth)}- ↺ *${n.label}* (see above)`); return; }
    seen.add(n.id);
    lines.push(`${"  ".repeat(depth)}- ${viaLabel ? `*${viaLabel}* → ` : ""}**${tag[n.type] || "Step"}:** ${n.label}`);
    for (const e of out.get(n.id)) walk(byId.get(e.to), depth + 1, e.label);
  };
  startNodes.forEach((n) => walk(n, 0, ""));
  return lines.join("\n");
}

/* Mini static preview for Library cards. */
function FcThumb({ chart, accent }) {
  const nodes = chart.nodes || [];
  if (!nodes.length) return null;
  const b = fcBounds(nodes, 30);
  const scale = Math.min(1, 280 / b.w, 120 / b.h);
  const byId = new Map(nodes.map((n) => [n.id, n]));
  return (
    <svg viewBox={`${b.x} ${b.y} ${b.w} ${b.h}`} style={{ width: "100%", height: 96, display: "block", background: "rgba(127,140,127,0.06)", borderRadius: RADIUS.md }}>
      {(chart.edges || []).map((e) => {
        const a = byId.get(e.from), bb = byId.get(e.to);
        if (!a || !bb) return null;
        const g = fcEdgeGeom(a, bb);
        return <path key={e.id} d={g.d} fill="none" stroke={accent} strokeWidth={3} opacity={0.45} />;
      })}
      {nodes.map((n) => {
        const cx = n.x + n.w / 2, cy = n.y + n.h / 2;
        const fill = n.type === "start" || n.type === "end" ? accent : n.type === "decision" ? withAlpha(accent, 0.35) : withAlpha(accent, 0.14);
        if (n.type === "decision") return <polygon key={n.id} points={`${cx},${n.y} ${n.x + n.w},${cy} ${cx},${n.y + n.h} ${n.x},${cy}`} fill={fill} />;
        if (n.type === "io") { const s = 22; return <polygon key={n.id} points={`${n.x + s},${n.y} ${n.x + n.w},${n.y} ${n.x + n.w - s},${n.y + n.h} ${n.x},${n.y + n.h}`} fill={fill} />; }
        return <rect key={n.id} x={n.x} y={n.y} width={n.w} height={n.h} rx={n.type === "start" || n.type === "end" ? n.h / 2 : 10} fill={fill} />;
      })}
    </svg>
  );
}

/* Small palette button showing the node shape. */
function FcPaletteBtn({ type, P, accent, selected, onClick, isMobile }) {
  const t = FC_NODE_TYPES[type];
  const isAccent = type === "start" || type === "end";
  const shape = (() => {
    if (type === "decision") return <polygon points="20,2 38,12 20,22 2,12" fill={isAccent ? accent : withAlpha(accent, 0.16)} stroke={accent} strokeWidth={1.4} />;
    if (type === "io") return <polygon points="8,3 34,3 30,21 4,21" fill={withAlpha(accent, 0.12)} stroke={P.faint} strokeWidth={1.4} />;
    if (type === "evidence") return (<g><rect x="3" y="3" width="34" height="18" rx="4" fill={withAlpha(accent, 0.10)} stroke={accent} strokeWidth={1.4} /><rect x="3" y="3" width="4" height="18" rx="2" fill={accent} /></g>);
    return <rect x="3" y="4" width="34" height="16" rx={isAccent ? 8 : 4} fill={isAccent ? accent : withAlpha(accent, 0.10)} stroke={isAccent ? accent : P.faint} strokeWidth={1.4} />;
  })();
  return (
    <button type="button" onClick={onClick} title={`Add ${t.name}: click to drop it on the canvas`}
      aria-label={`Add ${t.name} node`}
      style={{
        display: "flex", flexDirection: isMobile ? "row" : "column", alignItems: "center", gap: isMobile ? 7 : 5,
        padding: isMobile ? "8px 12px 8px 8px" : "10px 4px", borderRadius: RADIUS.lg, cursor: "pointer",
        background: selected ? withAlpha(accent, 0.12) : "transparent",
        border: `1px solid ${selected ? accent : "transparent"}`,
        transition: "background-color 150ms ease, border-color 150ms ease, transform 150ms ease", flexShrink: 0,
      }}
      onMouseEnter={(e) => { e.currentTarget.style.background = withAlpha(accent, 0.10); e.currentTarget.style.borderColor = withAlpha(accent, 0.35); e.currentTarget.style.transform = "translateY(-1px)"; }}
      onMouseLeave={(e) => { e.currentTarget.style.background = selected ? withAlpha(accent, 0.12) : "transparent"; e.currentTarget.style.borderColor = selected ? accent : "transparent"; e.currentTarget.style.transform = "none"; }}>
      <svg width="40" height="24" viewBox="0 0 40 24" aria-hidden="true" style={{ filter: `drop-shadow(0 2px 4px ${withAlpha(accent, 0.25)})` }}>{shape}</svg>
      <span style={{ fontSize: FONT_SIZES.caption, color: P.ink2, fontFamily: "var(--cb-font)", lineHeight: 1.2, textAlign: "center", fontWeight: 500 }}>{t.name}</span>
    </button>
  );
}

/* In-canvas node shape (JSX). Layered: base fill, top-light gradient sheen,
   soft drop shadow. Selected nodes get an accent glow ring.
   Redesigned pass: softer, deeper shadow; hairline 1.5px strokes; larger
   corner radii — the chrome gets out of the way of the terse labels. */
function FcNodeShape({ n, P, accent, selected, pending }) {
  const cx = n.w / 2, cy = n.h / 2;
  const isAccent = n.type === "start" || n.type === "end";
  const fill = isAccent ? accent : n.type === "decision" ? withAlpha(accent, 0.14) : n.type === "evidence" ? withAlpha(accent, 0.12) : (P.dark ? "rgba(255,255,255,0.055)" : "#ffffff");
  const stroke = selected ? accent : pending ? accent : isAccent ? accent : n.type === "decision" || n.type === "evidence" ? accent : (P.dark ? "rgba(255,255,255,0.20)" : "rgba(20,30,20,0.24)");
  const sw = selected || pending ? 2.6 : 1.5;
  const shape = (() => {
    if (n.type === "decision") return <polygon points={`${cx},0 ${n.w},${cy} ${cx},${n.h} 0,${cy}`} />;
    if (n.type === "io") { const s = 20; return <polygon points={`${s},0 ${n.w},0 ${n.w - s},${n.h} 0,${n.h}`} />; }
    if (n.type === "evidence") return <rect x={0} y={0} width={n.w} height={n.h} rx={14} />;
    return <rect x={0} y={0} width={n.w} height={n.h} rx={isAccent ? n.h / 2 : 14} />;
  })();
  return (
    <g filter="url(#fcNodeShadow)">
      {selected && (
        <g opacity={0.55}>
          {n.type === "decision"
            ? <polygon points={`${cx},-7 ${n.w + 7},${cy} ${cx},${n.h + 7} -7,${cy}`} fill="none" stroke={accent} strokeWidth={2.4} />
            : <rect x={-7} y={-7} width={n.w + 14} height={n.h + 14} rx={(isAccent ? n.h / 2 : 14) + 7} fill="none" stroke={accent} strokeWidth={2.4} />}
        </g>
      )}
      {React.cloneElement(shape, { fill, stroke, strokeWidth: sw })}
      {React.cloneElement(shape, { fill: "url(#fcNodeGrad)", stroke: "none", pointerEvents: "none" })}
      {n.type === "evidence" && <rect x={0} y={0} width={5} height={n.h} rx={2.5} fill={accent} stroke="none" pointerEvents="none" />}
    </g>
  );
}

/* Moved to src/flowcharts.jsx: FlowchartStudio+Mermaid */

// Accounts modal — a single 6-digit-code sign-in flow. Talks to /api/auth
// (see functions/api/auth.js). `onAuthed(user)` fires once verify-code
// succeeds; the caller (App) decides what to do with the account's data
// (pull it down, offer to import local data, etc.) — this component only
// handles the two-step credential exchange itself: send-code, verify-code.
// No password is ever collected — proving inbox ownership is the entire
// credential, which is also why there's nothing here for a phishing page to
// usefully imitate beyond the code itself, and that code is single-use and
// dead within 15 minutes even if it leaks.
const OTP_LENGTH = 6;
const OTP_RESEND_COOLDOWN_S = 30;

function AuthModal({ P, accent, at, close, onAuthed, intent = "login" }) {
  const [step, setStep] = useState("email"); // "email" | "code"
  const [email, setEmail] = useState("");
  const [digits, setDigits] = useState(Array(OTP_LENGTH).fill(""));
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [cooldown, setCooldown] = useState(0);
  const [shakeKey, setShakeKey] = useState(0);
  const [passkeyBusy, setPasskeyBusy] = useState(false);
  const boxRefs = useRef([]);
  const passkeySupported = typeof window !== "undefined" && !!window.PublicKeyCredential &&
    typeof window.PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable === "function";

  // base64url helpers for the WebAuthn ceremony (ArrayBuffer <-> string).
  const b64urlEncode = (buf) => {
    const bytes = new Uint8Array(buf);
    let bin = "";
    for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
    return btoa(bin).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
  };
  const b64urlDecode = (s) => {
    const b64 = s.replace(/-/g, "+").replace(/_/g, "/");
    const bin = atob(b64 + "=".repeat((4 - (b64.length % 4)) % 4));
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    return bytes.buffer;
  };

  // Passkey sign-in: one tap, no email round trip. The server issues the
  // challenge bound to this email; the authenticator signs it; the server
  // verifies and returns a session through the same path as OTP.
  async function signInWithPasskey() {
    if (passkeyBusy || busy) return;
    const cleanEmail = email.trim();
    if (!cleanEmail) { setError("Enter your email first, then use your passkey."); return; }
    setError("");
    setPasskeyBusy(true);
    try {
      const begin = await apiAuth("passkey-auth-begin", { email: cleanEmail });
      if (!begin || !begin.ok || !begin.allowCredentials || !begin.allowCredentials.length) {
        setError("No passkey is registered for that email yet. Sign in with a code once, then set one up.");
        return;
      }
      const cred = await navigator.credentials.get({
        publicKey: {
          challenge: b64urlDecode(begin.challenge),
          rpId: begin.rpId,
          allowCredentials: begin.allowCredentials.map((id) => ({ type: "public-key", id: b64urlDecode(id) })),
          userVerification: "preferred",
        },
      });
      if (!cred) throw new Error("cancelled");
      const finish = await apiAuth("passkey-auth-finish", {
        email: cleanEmail,
        credentialId: cred.id,
        authenticatorData: b64urlEncode(cred.response.authenticatorData),
        clientDataJSON: b64urlEncode(cred.response.clientDataJSON),
        signature: b64urlEncode(cred.response.signature),
      });
      if (finish && finish.user) onAuthed(finish.user);
      else throw new Error("verify");
    } catch (err) {
      if (err && err.name === "NotAllowedError") setError("Passkey was cancelled. Try again when ready.");
      else setError(err.message || "That passkey didn't work. Try the email code instead.");
    } finally {
      setPasskeyBusy(false);
    }
  }
  useEffect(() => {
    if (cooldown <= 0) return;
    const id = setInterval(() => setCooldown((c) => Math.max(0, c - 1)), 1000);
    return () => clearInterval(id);
  }, [cooldown]);

  async function requestCode(e) {
    if (e) e.preventDefault();
    if (busy) return;
    setError("");
    setBusy(true);
    try {
      await apiAuth("send-code", { email });
      setDigits(Array(OTP_LENGTH).fill(""));
      setStep("code");
      setCooldown(OTP_RESEND_COOLDOWN_S);
      setTimeout(() => boxRefs.current[0]?.focus(), 60);
    } catch (err) {
      setError(err.message || "Something went wrong.");
    } finally {
      setBusy(false);
    }
  }

  async function verify(fullCode) {
    if (busy) return;
    setError("");
    setBusy(true);
    try {
      const data = await apiAuth("verify-code", { email, code: fullCode });
      onAuthed(data.user);
    } catch (err) {
      // The digits stay put on a wrong code. Wiping all six boxes punishes
      // a single typo with full retyping; the error names the fix instead.
      setError(err.message || "That code didn't match. Check the newest email, codes refresh each time you resend.");
      setShakeKey((k) => k + 1);
      setTimeout(() => boxRefs.current[0]?.focus(), 60);
    } finally {
      setBusy(false);
    }
  }

  function setDigitAt(i, val) {
    setDigits((prev) => {
      const next = [...prev];
      next[i] = val;
      const joined = next.join("");
      if (joined.length === OTP_LENGTH && next.every((d) => d !== "")) {
        setTimeout(() => verify(joined), 0);
      }
      return next;
    });
  }

  function onBoxChange(i, e) {
    const raw = e.target.value;
    const clean = raw.replace(/\D/g, "");
    if (!clean) { setDigitAt(i, ""); return; }
    // Typing normally lands one digit; a fast mobile keyboard or autofill
    // can hand this box more than one character at once — treat either the
    // same way paste is handled below rather than dropping the extras.
    if (clean.length > 1) { distributeFromIndex(i, clean); return; }
    setDigitAt(i, clean);
    if (i < OTP_LENGTH - 1) boxRefs.current[i + 1]?.focus();
  }

  function distributeFromIndex(startIdx, str) {
    const chars = str.replace(/\D/g, "").slice(0, OTP_LENGTH - startIdx).split("");
    setDigits((prev) => {
      const next = [...prev];
      chars.forEach((c, j) => { next[startIdx + j] = c; });
      const joined = next.join("");
      if (joined.length === OTP_LENGTH && next.every((d) => d !== "")) {
        setTimeout(() => verify(joined), 0);
      }
      return next;
    });
    const landOn = Math.min(startIdx + chars.length, OTP_LENGTH - 1);
    setTimeout(() => boxRefs.current[landOn]?.focus(), 0);
  }

  function onBoxKeyDown(i, e) {
    if (e.key === "Backspace") {
      if (digits[i]) { setDigitAt(i, ""); return; }
      if (i > 0) { boxRefs.current[i - 1]?.focus(); setDigitAt(i - 1, ""); }
      e.preventDefault();
    } else if (e.key === "ArrowLeft" && i > 0) {
      e.preventDefault(); boxRefs.current[i - 1]?.focus();
    } else if (e.key === "ArrowRight" && i < OTP_LENGTH - 1) {
      e.preventDefault(); boxRefs.current[i + 1]?.focus();
    }
  }

  function onBoxPaste(i, e) {
    const text = (e.clipboardData || window.clipboardData).getData("text");
    if (!/\d/.test(text)) return;
    e.preventDefault();
    distributeFromIndex(0, text);
  }

  const inputStyle = { width: "100%", padding: "11px 13px", fontSize: 16, borderRadius: RADIUS.md, border: `1px solid ${P.line}`, background: P.surface, color: P.ink, fontFamily: "var(--cb-font)", marginTop: 6 };
  const boxStyle = { width: 44, height: 52, textAlign: "center", fontSize: 22, fontWeight: 500, borderRadius: RADIUS.md, border: `1px solid ${P.line}`, background: P.surface, color: P.ink, fontFamily: "var(--cb-font)", outline: "none" };

  return (
    <ModalChrome label="Sign in to Cerebrum" P={P} accent={accent} onClose={close} zIndex={215} width={440}
      eyebrow={step === "email" ? "Account" : "Check your email"}
      title={step === "email" ? (intent === "signup" ? "Create your account" : "Sign in") : "Enter your code"}>

        {step === "email" ? (
          <form onSubmit={requestCode} style={{ paddingTop: 4 }}>
            <label style={{ display: "block", fontSize: FONT_SIZES.small, fontWeight: 500, color: P.ink2 }}>
              Email
              <input type="email" required autoFocus value={email} onChange={(e) => setEmail(e.target.value)} style={inputStyle} placeholder="you@example.com" aria-label="Email" />
            </label>
            <div style={{ fontSize: FONT_SIZES.small, color: P.faint, marginTop: 10, lineHeight: 1.5 }}>{intent === "signup" ? "No password to pick. We'll email you a 6-digit code and your account is made." : "No password to remember. We'll email you a 6-digit code that signs you in."}</div>
            {error && <div role="alert" style={{ marginTop: 14, padding: "9px 12px", borderRadius: RADIUS.md, background: withAlpha(STATUS.bad, 0.1), color: statusBad(P), fontSize: FONT_SIZES.small, lineHeight: 1.5 }}>{error}</div>}
            <UIButton P={P} variant="ghost" type="submit" disabled={busy} style={{ width: "100%", marginTop: 18, padding: "12px", fontSize: FONT_SIZES.body, fontWeight: 500, background: accent, color: at, border: "none", borderRadius: RADIUS.md, cursor: busy ? "default" : "pointer", opacity: busy ? 0.7 : 1, fontFamily: "var(--cb-font)" }}>
              {busy ? "Sending…" : "Send sign-in code"}
            </UIButton>
            {passkeySupported && (
              <button type="button" onClick={signInWithPasskey} disabled={passkeyBusy || busy}
                style={{ width: "100%", marginTop: 10, minHeight: 44, padding: "10px", fontSize: FONT_SIZES.small, fontWeight: 500, background: "none", border: `1px solid ${P.line2}`, borderRadius: RADIUS.md, color: P.ink2, cursor: (passkeyBusy || busy) ? "default" : "pointer", opacity: (passkeyBusy || busy) ? 0.6 : 1, fontFamily: "var(--cb-font)" }}>
                {passkeyBusy ? "Waiting for your passkey…" : "Use a passkey instead"}
              </button>
            )}
            <div style={{ fontSize: FONT_SIZES.caption, color: P.faint, marginTop: 14, lineHeight: 1.6 }}>
              Saved articles, collections, and history stay local unless you sign in. See <a href="/privacy" style={{ color: P.faint, borderBottom: `1px dotted ${P.faint}`, textDecoration: "none" }}>Privacy</a> for exactly what that means.
            </div>
          </form>
        ) : (
          <div style={{ paddingTop: 4 }}>
            <div style={{ fontSize: FONT_SIZES.small, color: P.ink2, lineHeight: 1.6, marginBottom: 18 }}>We sent a 6-digit code to <strong>{email}</strong>. It expires in 15 minutes.</div>
            <div key={shakeKey} style={{ display: "flex", gap: 8, justifyContent: "center", animation: shakeKey > 0 ? "cb-otp-shake 320ms cubic-bezier(0.16, 1, 0.3, 1)" : "none" }} onPaste={(e) => onBoxPaste(0, e)}>
              {digits.map((d, i) => (
                <input
                  key={i}
                  ref={(el) => { boxRefs.current[i] = el; }}
                  type="text"
                  inputMode="numeric"
                  autoComplete={i === 0 ? "one-time-code" : "off"}
                  maxLength={1}
                  value={d}
                  disabled={busy}
                  onChange={(e) => onBoxChange(i, e)}
                  onKeyDown={(e) => onBoxKeyDown(i, e)}
                  onPaste={(e) => onBoxPaste(i, e)}
                  aria-label={`Digit ${i + 1} of ${OTP_LENGTH}`}
                  style={{ ...boxStyle, borderColor: error ? STATUS.bad : P.line }}
                />
              ))}
            </div>
            {error && <div role="alert" style={{ marginTop: 16, padding: "9px 12px", borderRadius: RADIUS.md, background: withAlpha(STATUS.bad, 0.1), color: statusBad(P), fontSize: FONT_SIZES.small, lineHeight: 1.5, textAlign: "center" }}>{error}</div>}
            {busy && <div style={{ marginTop: 16, textAlign: "center", fontSize: FONT_SIZES.small, color: P.faint }}>Verifying…</div>}
            <div style={{ marginTop: 20, textAlign: "center", fontSize: FONT_SIZES.small, color: P.faint }}>
              {cooldown > 0 ? (
                <span>Didn't receive it? Resend in {cooldown}s</span>
              ) : (
                <button type="button" onClick={requestCode} disabled={busy} style={{ background: "none", border: "none", color: accent, fontWeight: 500, cursor: busy ? "default" : "pointer", fontFamily: "var(--cb-font)", fontSize: FONT_SIZES.small, padding: 0 }}>Resend code</button>
              )}
            </div>
            <button type="button" onClick={() => { setStep("email"); setError(""); setDigits(Array(OTP_LENGTH).fill("")); }} style={{ minHeight: 44, width: "100%", marginTop: 16, padding: "9px", fontSize: FONT_SIZES.small, color: P.faint, background: "none", border: "none", cursor: "pointer", fontFamily: "var(--cb-font)" }}>Use a different email</button>
          </div>
        )}
    </ModalChrome>
  );
}

// Commit 50 — VideoHuddle rebuilt on Cerebrum's own WebRTC signaling instead
// of embedding Jitsi's free public server (meet.jit.si).
//
// Root cause of the bug this replaces: on August 24, 2023, Jitsi permanently
// ended anonymous room creation on meet.jit.si — every room's first
// participant now has to authenticate via Google/GitHub/Facebook to become
// "moderator" before the call starts
// (https://jitsi.org/blog/authentication-on-meet-jit-si/,
// https://github.com/jitsi/jitsi-meet/issues/13753). That requirement is
// enforced on Jitsi's own server, not by anything this app's client code
// configured, so no JitsiMeetExternalAPI option could bypass it — the
// "please log-in" screen was Jitsi's 2023 policy showing up inside our
// embed, not a bug in the usual sense.
//
// This is a genuine from-scratch replacement, not a patch: real
// getUserMedia capture, a real RTCPeerConnection per call, and a real
// signaling channel of our own (functions/api/callsignal.js, backed by the
// call_signals D1 table) instead of a third party's server. No OAuth wall
// is possible here because there is no third party in the call path at all
// — only two browsers and Cerebrum's own backend relaying the small
// SDP/ICE messages needed to introduce them to each other. Media itself
// never touches Cerebrum's servers; it flows directly between the two
// browsers (or via a STUN-negotiated path — see functions/api/
// ice-servers.js) the same way FaceTime/Instagram's own calling does.
//
// Scope, stated plainly: this is peer-to-peer, built for the 1:1 calls the
// product actually surfaces today (the single "Video Huddle" button on a DM
// thread in InboxView) — a group call would need a media relay (SFU)
// fanning out N streams each way, a materially bigger project. There is
// also no TURN relay configured yet (see ice-servers.js for the env vars
// that turn one on with zero further code changes) — STUN alone already
// covers the large majority of home/mobile networks, but two callers both
// behind a restrictive/symmetric NAT (some corporate/hotel Wi-Fi) may fail
// to connect directly until TURN is added. And there is still no push
// notification when someone starts a huddle — both people have to already
// know to open it — pre-existing since the very first Jitsi version of this
// feature, unrelated to today's fix, flagged here rather than left for
// someone to rediscover.
//
// Commit 46: rebuilt as a dedicated full-screen overlay (FaceTime-style)
// instead of an inline panel confined to the Inbox's right pane — kept as-is
// below, only what's inside it changed.
/* ════════════════════════════════════════════════════════════════
   INCOMING CALL — the receiving half of a video huddle
   ════════════════════════════════════════════════════════════════
   Until this existed, "calling someone" in Cerebrum wasn't a thing that
   could happen: VideoHuddle assumed both people had already independently
   opened the same thread's huddle, and if they hadn't, both sides simply
   sat on "Waiting for X to join" until one of them gave up. That is the
   whole of the reported bug — the WebRTC handshake underneath was fine.

   The caller now emits a `ring` heartbeat (see VideoHuddle), every signed-in
   client polls "is anyone calling me" app-wide (see the effect in App), and
   this is what that poll puts on screen. Modeled on the incoming-call sheet
   every phone uses: who's calling, and two unmistakable choices.

   Declining posts a `bye` on the thread so the caller's own huddle closes
   immediately rather than ringing into a void — a decline the caller can't
   see is just a call that seems to go unanswered. */
function IncomingCall({ call, P, accent, at, isMobile, onAccept, onDecline }) {
  useCallTone("incoming", true);
  const initial = (call.fromName || "?").trim().charAt(0).toUpperCase();
  const skin = avatarSkin(call.fromName || call.fromId);
  /* Dialog semantics, in place (the Cortex Player pattern): this card is
     not routed through the Dialog primitive because it is not a centered
     modal sheet — it anchors to a corner and the page stays visible and
     scrollable behind it — but it declares aria-modal, so it carries the
     full contract itself: focus moves into the card on mount, Tab cycles
     inside it, Escape declines, and focus returns to whatever held it
     when the card goes away. It previously had no focus handling at
     all, so a keyboard user tabbed through the page behind a dialog
     that claimed to be modal. */
  const panelRef = useRef(null);
  const onDeclineRef = useRef(onDecline);
  onDeclineRef.current = onDecline;
  useEffect(() => {
    const prevFocus = document.activeElement;
    const panel = panelRef.current;
    if (panel) panel.focus();
    const onKey = (e) => {
      if (e.key === "Escape") { e.preventDefault(); onDeclineRef.current(); return; }
      if (e.key !== "Tab" || !panel) return;
      const f = panel.querySelectorAll('button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])');
      if (!f.length) return;
      const first = f[0], last = f[f.length - 1];
      // Focus starts on the panel root itself (tabIndex -1, so it is
      // not in the list above): treat the root as the boundary, or
      // Shift + Tab from the freshly focused root steps backward out
      // of a surface that declares aria-modal before any wrap engages.
      if (document.activeElement === panel) { e.preventDefault(); (e.shiftKey ? last : first).focus(); }
      else if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
      else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
    };
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("keydown", onKey);
      try { if (prevFocus && prevFocus.focus) prevFocus.focus(); } catch { /* the trigger may be gone */ }
    };
  }, []);
  const btn = (bg, color, label, icon, onClick) => (
    <button onClick={onClick} style={{
      display: "flex", flexDirection: "column", alignItems: "center", gap: 8,
      background: "none", border: "none", cursor: "pointer", color: P.ink2,
      fontSize: FONT_SIZES.caption, fontWeight: 500, fontFamily: "var(--cb-font)",
    }}>
      <span style={{
        width: 58, height: 58, borderRadius: "50%", background: bg, color,
        display: "flex", alignItems: "center", justifyContent: "center",
      }}><Icon name={icon} size={22} /></span>
      {label}
    </button>
  );
  return (
    <div role="dialog" aria-modal="true" aria-label={`Incoming call from ${call.fromName}`}
      ref={panelRef} tabIndex={-1}
      style={{
        position: "fixed", zIndex: Z.modalTop,
        // Phone-like placement: top sheet on mobile (where a call banner
        // belongs), bottom-right card on desktop (where it doesn't cover
        // what someone is reading).
        ...(isMobile
          ? { top: 12, left: 12, right: 12 }
          : { bottom: 24, right: 24, width: 340 }),
        padding: 20, borderRadius: RADIUS.lg,
        background: P.dark ? "#121318" : "#ffffff",
        border: `1px solid ${P.line2}`,
        boxShadow: "none",
      }}
      className="cb-modal"
    >
      <div style={{ display: "flex", alignItems: "center", gap: 14, marginBottom: 20 }}>
        <span aria-hidden="true" style={{
          width: 52, height: 52, borderRadius: "50%", flexShrink: 0,
          background: withAlpha(accent, 0.2), border: `1px solid ${withAlpha(accent, 0.45)}`,
          display: "flex", alignItems: "center", justifyContent: "center",
          fontSize: 20, fontWeight: 500, color: P.ink, fontFamily: "var(--cb-font)",
          animation: "cbHuddleRing 1.6s ease-in-out infinite",
        }}>{initial}</span>
        <div style={{ minWidth: 0 }}>
          <div style={{ fontSize: FONT_SIZES.caption, color: P.faint, fontFamily: "var(--cb-font)", letterSpacing: TRACKING.tight }}>Incoming call</div>
          <div style={{ fontSize: FONT_SIZES.subhead, fontWeight: 500, color: P.ink, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{call.fromName}</div>
        </div>
      </div>
      <div style={{ display: "flex", justifyContent: "space-evenly" }}>
        {btn(withAlpha(STATUS.bad, 0.16), STATUS.bad, "Decline", "phoneOff", onDecline)}
        {/* The accept glyph names the call the person is actually
            answering: a phone for an audio only call, a camera for a
            video call. This always drew the camera, so an audio call
            announced itself with the wrong medium. */}
        {btn(accent, at, "Accept", call.audioOnly ? "phone" : "camera", onAccept)}
      </div>
    </div>
  );
}

let __cbHuddleClientSeq = 0;
function newHuddleClientId() {
  __cbHuddleClientSeq += 1;
  return `${Date.now().toString(36)}-${__cbHuddleClientSeq}-${Math.random().toString(36).slice(2, 8)}`;
}
// Returns true only if the signal actually landed. Commit 59: this used to
// be fire-and-forget, which is why a call could ring on the caller's screen
// while the ring POST was being rejected — nothing anywhere looked at the
// result, so a 404 (endpoint not deployed) and a 200 were indistinguishable.
// Commit 70 — returns `true` on success, or a short human-readable reason
// on failure, so the caller can say what actually went wrong instead of
// guessing. The old version returned a bare boolean, which is why a failed
// ring rendered as "Calls aren't fully set up on the server" whether the
// real cause was a missing table, a rate limit, a blocked user, an expired
// session, or a dropped connection — five very different problems, one
// misleading sentence, and no way to tell them apart from a screenshot.
/* ── API ROUTE NAMING: NO HYPHENS. EVER. ────────────────────────────────
   Cloudflare Pages maps functions/api/<name>.js to /api/<name>, literally
   and with no normalization. These endpoints were originally called
   call-signal, ice-servers and trending-refresh, and when the files were
   copied into the repo the hyphens were lost — so the files existed as
   callsignal.js and iceservers.js while the app kept asking for
   /api/call-signal. Nothing served those paths.

   That is not a small bug. Pages answers a request for a route no Function
   claims by falling back to the STATIC handler: a GET returns index.html
   with HTTP 200, and a POST returns 405. So the app got a 200 containing a
   web page where it expected JSON, and failed silently. Calling never
   worked at all, and Trending never showed a single picture, for weeks —
   while every health probe reported "live", because a 200 is a 200.

   The convention is now: API filenames are a single lowercase word, no
   hyphens, no underscores. It is not prettier. It is simply the only
   version of this that cannot be broken by a filename losing a character
   in transit, and a route name nobody can mistype is worth more than a
   route name that reads nicely.
   ─────────────────────────────────────────────────────────────────────── */
async function postCallSignal(threadId, clientId, type, payload) {
  try {
    const res = await fetch("/api/callsignal", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ threadId, clientId, type, payload }),
    });
    if (res.ok) return true;
    let reason = "";
    try { reason = (await res.json()).error || ""; } catch (cbErr) { console.error("[Cerebrum] CerebrumApp.jsx postCallSignal: reason = (await res.json()).error || ''; }:", cbErr); }
    if (!reason) {
      reason = res.status === 401 ? "Your session expired: sign in again."
        : res.status === 403 ? "You're not authorized to call in this conversation."
        : res.status === 429 ? "Too many requests: wait a moment."
        : `Server returned ${res.status}.`;
    }
    return reason;
  } catch {
    // Best-effort. A dropped offer/answer/ICE post is recoverable — the
    // sender's own retry logic or the next natural signal covers it, except
    // `bye` on unmount, which is inherently best-effort everywhere (the tab
    // may already be closing when it fires).
    return false;
  }
}

