/* ── Label ───────────────────────────────────────────────────────────
   The section marker. Sentence case, body face, one accent dot — the
   pattern that replaced five different shouted uppercase-mono eyebrows. */
function UILabel({ children, P, accent, right, style }) {
  return (
    <div style={{
      display: "flex", alignItems: "center", gap: SP.sm, marginBottom: SP.md,
      fontSize: FONT_SIZES.micro, ...TYPE.label, color: P.faint, ...style,
    }}>
      <span aria-hidden="true" style={{ width: 5, height: 5, borderRadius: "50%", background: accent, flexShrink: 0 }} />
      <span>{children}</span>
      {right && <span style={{ marginLeft: "auto" }}>{right}</span>}
    </div>
  );
}

/* ══════════════════════════════════════════════════════════════════
   REDESIGN PRIMITIVES — the shared instrument language

   Eyebrow: mono uppercase micro-label with a hairline rule. This is the
   one section grammar the whole answer view now speaks: every section
   opens the same way, so a reader can tell at a glance what kind of
   thing they're looking at.

   AnswerSection: eyebrow + hairline + content, one wrapper for every
   block under an answer.

   ChromeHeader / ModalChrome: the single modal language. Twelve modals
   and two drawers each had their own header treatment; now there is one:
   mono eyebrow, title, one ghost close. Drawers reuse ChromeHeader with
   the drawer variant (left hairline instead of corner ticks).

   ToolChip: the answer toolbar's labeled hairline chip — icon-only
   buttons hid meaning behind tooltips, so every action now says its name.

   SegControl: mono segmented control — the one selection language for
   bibliography styles, settings tabs, notebook tabs, trending filters.
   ══════════════════════════════════════════════════════════════════ */

function Eyebrow({ children, P, right, style }) {
  return (
    <div className="cb-eyebrow" style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 14, ...style }}>
      <span style={{
        fontFamily: "var(--cb-font)", fontSize: 14, fontWeight: 500,
        letterSpacing: "normal", textTransform: "none", color: P.faint, whiteSpace: "nowrap",
      }}>{children}</span>
      <span aria-hidden="true" style={{ flex: 1, height: 1, background: P.line, minWidth: 24 }} />
      {right && <span className="cb-eyebrow-right" style={{ flexShrink: 0 }}>{right}</span>}
    </div>
  );
}

function AnswerSection({ eyebrow, title, right, children, P, accent, style, quiet = false }) {
  return (
    <section style={{ marginTop: 30, ...style }} className="cb-fade">
      {quiet ? (
        /* Pass 5: the evidence-area sections (map, venn, compare) use the
           quiet instrument kicker instead of the letterspaced caps eyebrow. */
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 14 }}>
          <span className="cb-kicker" style={{ whiteSpace: "nowrap" }}>{eyebrow}</span>
          <span aria-hidden="true" style={{ flex: 1, height: 1, background: P.line, minWidth: 24 }} />
          {right && <span className="cb-eyebrow-right" style={{ flexShrink: 0 }}>{right}</span>}
        </div>
      ) : (
        <Eyebrow P={P} right={right}>{eyebrow}</Eyebrow>
      )}
      {title && (
        <div style={{ fontSize: FONT_SIZES.subhead, fontWeight: 500, color: P.ink, margin: "-6px 0 12px", letterSpacing: TYPE.heading.letterSpacing, fontFamily: "var(--cb-font)", lineHeight: 1.35 }}>{title}</div>
      )}
      {children}
    </section>
  );
}

